INSERT INTO `accommodations` (`id`, `title`, `slug`, `subtitle`, `excerpt`, `description`, `hero_image`, `hero_image_alt`, `hero_mobile_image`, `hero_mobile_image_alt`, `card_image`, `card_image_alt`, `size`, `occupancy`, `bed_type`, `view`, `accommodation_type`, `villa_code`, `button_label`, `button_url`, `booking_url_override`, `meta_title`, `meta_description`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Panoramic Jungle View Villa', 'panoramic-jungle-view-villa', 'Breathtaking Views', 'Stay in private jungle villas in Ubud and spacious royal suites surrounded by rainforest, tropical greenery, and the calm atmosphere of Bali. Each accommodation at Nandini Jungle by Hanging Gardens is designed for comfort, privacy, and warm Balinese character, creating a refined jungle retreat for couples, families, and guests seeking space to reconnect with nature.', '<p>Our Panoramic Jungle View Villa offers breathtaking and uninterrupted views of the river valley, as well as a sense of opulent isolation from the outer world. The Panoramic Jungle View Villa is built with luxurious teak flooring that is inspired by Balinese architecture. It offers 48 square metres of luxury accommodation with a canopied king bed, an enormous bathroom and a private balcony overlooking Ubud&#039;s rainforest center.</p>', 'accommodations/hero/panoramic-jungle-view-villa-private-balcony-ubud-bali.webp', 'Private balcony of the Panoramic Jungle View Villa with jungle and river valley views in Ubud, Bali', 'accommodations/hero-mobile/panoramic-jungle-view-villa-private-balcony-ubud-bali.webp', 'Private balcony of the Panoramic Jungle View Villa with jungle and river valley views in Ubud, Bali', 'accommodations/cards/panoramic-jungle-view-villa-private-balcony-ubud-bali.webp', 'Private balcony of the Panoramic Jungle View Villa with jungle and river valley views in Ubud, Bali', NULL, NULL, NULL, NULL, 'villa', 'PVV', 'ROOM + FLIGHT', 'https://ovs.tour-list.com/DPSearch/?HotelCode=nandinihgs&Language=en&ExtRoomCode=PVV', NULL, 'Panoramic Jungle View Villa in Ubud | Nandini Jungle', 'Stay in Panoramic Jungle View Villa with river valley views, teak flooring, king bed, spacious bathroom, and private balcony in Ubud.', 0, 1, 3, '2024-04-30 02:28:53', '2026-07-07 00:23:32'),
(2, 'Presidential Royal Suite', 'presidential-royal-suite', NULL, 'One of the largest suites in Bali, the Presidential Royal Suite offers exceptional space, privacy, and refined comfort within the natural setting of Nandini Jungle by Hanging Gardens. With elegant furnishings, a generous living area, a master bedroom, and a private terrace overlooking lush gardens, this suite is ideal for families or guests seeking an elevated Bali jungle resort stay.', '<p>One of the largest suites in Bali, the Presidential Royal Suite offers exceptional space, privacy, and refined jungle living. <br><br>Elegantly designed with rich furnishings, the suite features a master bedroom opening onto a generous private terrace overlooking lush gardens and the majestic Ubud rainforest. The expansive living area is ideal for families or guests seeking space to relax and gather. <br><br>A stay in the Presidential Royal Suite is defined by tranquillity, scale, and complete immersion in nature.</p>', 'accommodations/hero/presidential-royal-suite-nandini-jungle-bali.webp', 'Presidential Royal Suite surrounded by lush tropical gardens at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'accommodations/hero-mobile/presidential-royal-suite-nandini-jungle-bali.webp', 'Presidential Royal Suite surrounded by lush tropical gardens at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'accommodations/cards/presidential-royal-suite-nandini-jungle-bali.webp', 'Presidential Royal Suite surrounded by lush tropical gardens at Nandini Jungle by Hanging Gardens in Ubud, Bali', NULL, NULL, NULL, NULL, 'suite', 'PDRS', 'ROOM + FLIGHT', 'https://ovs.tour-list.com/DPSearch/?HotelCode=nandinihgs&Language=en&ExtRoomCode=PDS', NULL, 'Presidential Royal Suite in Ubud | Nandini Jungle', 'Experience the Presidential Royal Suite with spacious interiors, private terrace, lush garden views, and refined jungle living in Ubud.', 0, 1, 7, '2024-04-30 04:56:08', '2026-07-07 00:23:32'),
(3, 'Sunrise View Villa', 'sunrise-view-villa', NULL, 'The Sunrise View Villa welcomes golden morning light and tranquil rainforest ambience into your stay. Created for quiet mornings and relaxed moments, this villa offers a serene jungle experience in Bali where nature, comfort, and understated luxury come together.', '<p>Featuring a breathtaking golden sunshine spilling into the room, the Sunrise View Villa is surrounded by the tranquil rainforest ambiance. Featuring a wide outdoor living area, a canopied king bed, a huge bathroom, and a private balcony with breathtaking views of Ubud&#039;s rainforest, the Sunrise View Villa is 48 square meters in size. Every aspect of the space beautifully captures the essence of Bali, its natural beauty, and friendly hospitality.</p>', 'accommodations/hero/sunrise-view-villa-private-balcony-rainforest-ubud-bali.webp', 'Private balcony of the Sunrise View Villa with golden morning light and rainforest views in Ubud, Bali', 'accommodations/hero-mobile/sunrise-view-villa-private-balcony-rainforest-ubud-bali.webp', 'Private balcony of the Sunrise View Villa with golden morning light and rainforest views in Ubud, Bali', 'accommodations/cards/sunrise-view-villa-private-balcony-rainforest-ubud-bali.webp', 'Private balcony of the Sunrise View Villa with golden morning light and rainforest views in Ubud, Bali', NULL, NULL, NULL, NULL, 'villa', 'SVV', 'ROOM + FLIGHT', 'https://ovs.tour-list.com/DPSearch/?HotelCode=nandinihgs&Language=en&ExtRoomCode=SVV', NULL, 'Sunrise View Villa in Ubud | Nandini Jungle', 'Wake up in the Sunrise View Villa with golden light, rainforest views, a canopied king bed, generous bathroom, and private balcony.', 0, 1, 2, '2024-04-30 05:49:04', '2026-07-07 00:23:32'),
(4, 'Jungle View Villa', 'jungle-view-villa', NULL, 'The Jungle View Villa offers forest views, generous outdoor living, and Balinese village-inspired details. This private villa in Ubud invites you to slow down, enjoy the resort\'s tropical setting, and stay close to the natural beauty of Bali.', '<p>A breathtaking view of the forest greets you in the morning from the Jungle View Villa. The Jungle View Villa is the same size as the Panoramic View Villa, with spacious outside living areas for a sense of grandeur while maintaining a casual atmosphere. Feel the experience of luxurious seclusion from the rest of the world. The Jungle View Villa is modeled after a typical Balinese village and offers a true Balinese experience.</p>', 'accommodations/hero/jungle-view-villa-private-balcony-ubud-bali.webp', 'Private balcony of the Jungle View Villa with lush rainforest views in Ubud, Bali', 'accommodations/hero-mobile/jungle-view-villa-private-balcony-ubud-bali.webp', 'Private balcony of the Jungle View Villa with lush rainforest views in Ubud, Bali', 'accommodations/cards/jungle-view-villa-private-balcony-ubud-bali.webp', 'Private balcony of the Jungle View Villa with lush rainforest views in Ubud, Bali', NULL, NULL, NULL, NULL, 'villa', 'JVV', 'ROOM + FLIGHT', 'https://ovs.tour-list.com/DPSearch/?HotelCode=nandinihgs&Language=en&ExtRoomCode=JVV', NULL, 'Jungle View Villa in Ubud | Nandini Jungle', 'Enjoy the Jungle View Villa with forest views, spacious outdoor living, Balinese-inspired design, and secluded comfort in Ubud.', 0, 1, 1, '2024-04-30 05:50:34', '2026-07-07 00:23:32'),
(5, 'Jungle View Royal Suite', 'jungle-view-royal-suite', NULL, 'The Jungle View Royal Suite blends refined comfort with the natural beauty of the surrounding rainforest. This spacious luxury suite in Ubud offers elegant interiors, peaceful views, and extra room for guests who want more space during their Bali escape.', '<p>In our Jungle View Royal Suite, the elegance of a five-star hotel is seamlessly blended with the natural beauty of the jungle. The Jungle View Royal Suite are lavishly furnished and artistically designed. These luxurious suites are constructed with ingenuity and craftsmanship and showcase the natural beauty of the location. They boast a master bedroom with a large patio facing a stunning jungle and garden vista. The distinctive bathroom makes the most of its size, with amenities such as an outdoor bath and rain shower, as well as a dressing area.</p>', 'accommodations/hero/jungle-view-royal-suite-bedroom-living-area-ubud-bali.webp', 'Jungle View Royal Suite with canopy bedroom, living area, and private balcony overlooking the rainforest in Ubud, Bali', 'accommodations/hero-mobile/jungle-view-royal-suite-bedroom-living-area-ubud-bali.webp', 'Jungle View Royal Suite with canopy bedroom, living area, and private balcony overlooking the rainforest in Ubud, Bali', 'accommodations/cards/jungle-view-royal-suite-bedroom-living-area-ubud-bali.webp', 'Jungle View Royal Suite with canopy bedroom, living area, and private balcony overlooking the rainforest in Ubud, Bali', NULL, NULL, NULL, NULL, 'suite', 'JVRS', 'ROOM + FLIGHT', 'https://ovs.tour-list.com/DPSearch/?HotelCode=nandinihgs&Language=en&ExtRoomCode=JVRS', NULL, 'Jungle View Royal Suite in Ubud | Nandini Jungle', 'Stay in the Jungle View Royal Suite with elegant interiors, spacious terrace, jungle garden views, outdoor bath, rain shower, and dressing area.', 0, 1, 5, '2024-04-30 05:51:47', '2026-07-07 00:23:32'),
(6, 'Panoramic Corner Jacuzzi Royal Suite', 'panoramic-corner-jacuzzi-royal-suite', NULL, 'The Panoramic Corner Jacuzzi Royal Suite is a spacious 120-square-meter sanctuary with panoramic views of the lush jungle in Ubud, Bali. With generous space, refined comfort, and a private Jacuzzi setting, this suite is ideal for guests seeking a luxury jungle suite surrounded by nature.', '<p>Escape to a spacious sanctuary spanning 120 square meters, offering breathtaking panoramic views of the verdant jungle Ubud, Bali - a serene retreat from the hustle and bustle of everyday life. The suite boasts a sumptuous king-sized bed and a Jacuzzi in one corner, complemented by a cozy living area perfect for unwinding or hosting guests and a private in-suite spa option with an add-on package. When it&#039;s time to refresh, a luxurious outdoor bathtub and separate shower promise an invigorating experience to complete your blissful retreat.</p>', 'accommodations/hero/panoramic-corner-jacuzzi-royal-suite-balcony-jacuzzi-ubud-bali.webp', 'Panoramic Corner Jacuzzi Royal Suite with private balcony jacuzzi and jungle views in Ubud, Bali', 'accommodations/hero-mobile/panoramic-corner-jacuzzi-royal-suite-balcony-jacuzzi-ubud-bali.webp', 'Panoramic Corner Jacuzzi Royal Suite with private balcony jacuzzi and jungle views in Ubud, Bali', 'accommodations/cards/panoramic-corner-jacuzzi-royal-suite-balcony-jacuzzi-ubud-bali.webp', 'Panoramic Corner Jacuzzi Royal Suite with private balcony jacuzzi and jungle views in Ubud, Bali', NULL, NULL, NULL, NULL, 'suite', 'PJCS', 'ROOM + FLIGHT', 'https://ovs.tour-list.com/DPSearch/?HotelCode=nandinihgs&Language=en&ExtRoomCode=PJCS', NULL, 'Panoramic Corner Jacuzzi Royal Suite | Nandini Jungle', 'Relax in a 120 sqm Panoramic Corner Jacuzzi Royal Suite with jungle views, king bed, Jacuzzi, living area, outdoor bath, and separate shower.', 0, 1, 6, '2024-06-18 21:31:38', '2026-07-07 00:23:32'),
(7, 'Private Garden Royal Suite', 'private-garden-royal-suite', NULL, 'The Private Garden Royal Suite offers refined comfort, generous space, and a private terrace overlooking lush tropical gardens. Designed for quiet relaxation, this royal suite in Ubud creates a restful stay with privacy and natural charm.', '<p>The Private Garden Royal Suite are professionally illustrated and loaded with lavish furnishing. These prosperous suites offer a master bedroom with an ample patio fronting the rampant and green grassland panorama.<br><br>The luxurious bathroom completes most of its area, with bathroom elements including an outdoor bath and rain shower, completed by a dressing facility. Wake up to the squirrels of birds tweeting merrily in the sunrise and also in the evening at the time of sunset on the terrace overlooking the lush garden. Private Garden Royal Suite offers a feeling of real serenity.</p>', 'accommodations/hero/private-garden-royal-suite-living-area-garden-view-ubud-bali.webp', 'Private Garden Royal Suite living area with tropical garden views at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'accommodations/hero-mobile/private-garden-royal-suite-living-area-garden-view-ubud-bali.webp', 'Private Garden Royal Suite living area with tropical garden views at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'accommodations/cards/private-garden-royal-suite-living-area-garden-view-ubud-bali.webp', 'Private Garden Royal Suite living area with tropical garden views at Nandini Jungle by Hanging Gardens in Ubud, Bali', NULL, NULL, NULL, NULL, 'suite', 'GVRS', 'ROOM + FLIGHT', 'https://ovs.tour-list.com/DPSearch/?HotelCode=nandinihgs&Language=en&ExtRoomCode=GVRS', NULL, 'Private Garden Royal Suite in Ubud | Nandini Jungle', 'Discover the Private Garden Royal Suite with a lush garden terrace, refined furnishings, outdoor bath, rain shower, and peaceful jungle setting.', 0, 1, 4, '2024-07-03 16:12:52', '2026-07-07 00:23:32');

