INSERT INTO `awards` (`id`, `title`, `slug`, `subtitle`, `excerpt`, `description`, `award_name`, `awarded_by`, `award_year`, `award_date`, `hero_image`, `hero_image_alt`, `hero_mobile_image`, `hero_mobile_image_alt`, `card_image`, `card_image_alt`, `button_label`, `button_url`, `meta_title`, `meta_description`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, '2017 WINNER - WORLD LUXURY HOTEL AWARDS', '2017-winner-world-luxury-hotel-awards', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens was proudly recognized as a 2017 Winner by the World Luxury Hotel Awards. This achievement reflects our commitment to refined hospitality, exceptional guest experiences, and luxury stays surrounded by the natural beauty of Ubud’s jungle.</p>', '2017 WINNER - WORLD LUXURY HOTEL AWARDS', 'World Luxury Hotel Awards', '2017', NULL, 'images/awards/01J0QR8HXCCFNSAWEN0AMGAF7E.png', '2017 WINNER - WORLD LUXURY HOTEL AWARDS', NULL, NULL, 'images/awards/01J0QR8HXCCFNSAWEN0AMGAF7E.png', '2017 WINNER - WORLD LUXURY HOTEL AWARDS', NULL, NULL, '2017 WINNER - WORLD LUXURY HOTEL AWARDS | Nandini Jungle Resort', 'Explore 2017 WINNER - WORLD LUXURY HOTEL AWARDS from Nandini Jungle by Hanging Gardens.', 0, 1, 10, '2024-06-19 00:01:56', '2026-06-27 13:18:29'),
(2, '2018 RECOGNITION OF EXCELLENCE - HOTELS COMBINED', '2018-recognition-of-excellence-hotels-combined', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens was honored with the 2018 Recognition of Excellence by HotelsCombined, achieving an impressive guest score of 8.9. This award reflects our continued dedication to exceptional hospitality, memorable guest experiences, and a peaceful jungle retreat in Ubud.</p>', '2018 RECOGNITION OF EXCELLENCE - HOTELS COMBINED', 'HotelsCombined', '2018', NULL, 'images/awards/01J0QR92G821J16683QPWP4E5P.jpg', '2018 RECOGNITION OF EXCELLENCE - HOTELS COMBINED', NULL, NULL, 'images/awards/01J0QR92G821J16683QPWP4E5P.jpg', '2018 RECOGNITION OF EXCELLENCE - HOTELS COMBINED', NULL, NULL, '2018 RECOGNITION OF EXCELLENCE - HOTELS COMBINED | Nandini Jungle Resort', 'Explore 2018 RECOGNITION OF EXCELLENCE - HOTELS COMBINED from Nandini Jungle by Hanging Gardens.', 0, 1, 7, '2024-06-19 00:02:13', '2026-06-27 13:18:29'),
(3, '2017 WINNER - WORLD LUXURY SPA AWARDS', '2017-winner-world-luxury-spa-awards', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens was proudly recognized as a 2017 Winner by the World Luxury Spa Awards. This award reflects our dedication to delivering exceptional spa experiences, refined wellness rituals, and peaceful rejuvenation surrounded by the natural beauty of Ubud’s jungle.</p>', '2017 WINNER - WORLD LUXURY SPA AWARDS', 'World Luxury Spa Awards', '2017', NULL, 'images/awards/01J0QR9XGFEV2H3E6E5WK3GM3P.png', '2017 WINNER - WORLD LUXURY SPA AWARDS', NULL, NULL, 'images/awards/01J0QR9XGFEV2H3E6E5WK3GM3P.png', '2017 WINNER - WORLD LUXURY SPA AWARDS', NULL, NULL, '2017 WINNER - WORLD LUXURY SPA AWARDS | Nandini Jungle Resort', 'Explore 2017 WINNER - WORLD LUXURY SPA AWARDS from Nandini Jungle by Hanging Gardens.', 0, 1, 11, '2024-06-19 00:02:41', '2026-06-27 13:18:29'),
(4, 'TRAVELLER SPA & WELLNESS', 'traveller-spa-wellness', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens was proudly featured by Traveller Spa &amp; Wellness, recognizing our commitment to serene spa journeys, restorative wellness experiences, and peaceful relaxation surrounded by the natural beauty of Ubud’s jungle.</p>', 'TRAVELLER SPA & WELLNESS', 'Traveller Spa & Wellness', NULL, NULL, 'images/awards/01J0QRBS4F21T56QVHYX4C1K75.jpg', 'TRAVELLER SPA & WELLNESS', NULL, NULL, 'images/awards/01J0QRBS4F21T56QVHYX4C1K75.jpg', 'TRAVELLER SPA & WELLNESS', NULL, NULL, 'TRAVELLER SPA & WELLNESS | Nandini Jungle Resort', 'Explore TRAVELLER SPA & WELLNESS from Nandini Jungle by Hanging Gardens.', 0, 1, 14, '2024-06-19 00:03:42', '2026-06-27 13:18:29'),
(5, 'GALATIAN SIGNATURE HOTELS AWARDS', 'galatian-signature-hotels-awards', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens was proudly recognized by the Galatian Signature Hotels Awards, celebrating our dedication to refined hospitality, memorable guest experiences, and luxury stays surrounded by the natural beauty of Ubud’s jungle.</p>', 'GALATIAN SIGNATURE HOTELS AWARDS', 'Galatian Signature Hotels Awards', NULL, NULL, 'images/awards/01J0QRCG2K1AD2KN78DJQ6F5BP.png', 'GALATIAN SIGNATURE HOTELS AWARDS', NULL, NULL, 'images/awards/01J0QRCG2K1AD2KN78DJQ6F5BP.png', 'GALATIAN SIGNATURE HOTELS AWARDS', NULL, NULL, 'GALATIAN SIGNATURE HOTELS AWARDS | Nandini Jungle Resort', 'Explore GALATIAN SIGNATURE HOTELS AWARDS from Nandini Jungle by Hanging Gardens.', 0, 1, 15, '2024-06-19 00:04:05', '2026-06-27 13:18:29'),
(6, 'LUX GLOBAL LUXURY HOTEL & SPA AWARDS', 'lux-global-luxury-hotel-spa-awards', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens was honored by the LUX Global Luxury Hotel &amp; Spa Awards 2018 as Most Outstanding Luxury Hideaway. This recognition reflects our commitment to intimate luxury, peaceful wellness experiences, and exceptional hospitality in Bali’s lush jungle setting.</p>', 'LUX GLOBAL LUXURY HOTEL & SPA AWARDS', 'LUX Global Luxury Hotel & Spa Awards', NULL, NULL, 'images/awards/01J0QRDFFBP0GDKM2M7JMFGC88.png', 'LUX GLOBAL LUXURY HOTEL & SPA AWARDS', NULL, NULL, 'images/awards/01J0QRDFFBP0GDKM2M7JMFGC88.png', 'LUX GLOBAL LUXURY HOTEL & SPA AWARDS', NULL, NULL, 'LUX GLOBAL LUXURY HOTEL & SPA AWARDS | Nandini Jungle Resort', 'Explore LUX GLOBAL LUXURY HOTEL & SPA AWARDS from Nandini Jungle by Hanging Gardens.', 0, 1, 18, '2024-06-19 00:04:38', '2026-06-27 13:18:29'),
(7, 'BEST LUXURY JUNGLE RETREAT 2023', 'best-luxury-jungle-retreat-2023', NULL, 'NANDINI JUNGLE BY HANGING GARDENS was victorious at the 10TH annual Seven Stars Luxury, Hospitality and Lifestyle Awards 2023 held at the Wyndham Grand Crete Mirabello Bay, Greece, taking home a win in the BEST LUXURY JUNGLE RETREAT 2023 category.', '<p>NANDINI JUNGLE BY HANGING GARDENS<strong> </strong>was victorious at the 10TH annual Seven Stars Luxury, Hospitality and Lifestyle Awards 2023 held at the Wyndham Grand Crete Mirabello Bay, Greece, taking home a win in the <strong>BEST LUXURY JUNGLE RETREAT 2023 </strong>category.&nbsp;</p><p>Nandini Jungle by Hanging Gardens, an authentic and luxurious jungle resort under the Hanging Gardens International (HGI) flag is recognized as a cutting-edge and innovative Bali property and a true frontrunner in the Bali hospitality scene.</p>', 'BEST LUXURY JUNGLE RETREAT 2023', 'Seven Stars Luxury, Hospitality and Lifestyle Awards', '2023', NULL, 'images/awards/01J0QREDFFJCX6D71AJ6TK3V2R.jpg', 'BEST LUXURY JUNGLE RETREAT 2023', NULL, NULL, 'images/awards/01J0QREDFFJCX6D71AJ6TK3V2R.jpg', 'BEST LUXURY JUNGLE RETREAT 2023', 'Read More', NULL, 'BEST LUXURY JUNGLE RETREAT 2023 | Nandini Jungle Resort', 'NANDINI JUNGLE BY HANGING GARDENS was victorious at the 10TH annual Seven Stars Luxury, Hospitality and Lifestyle Awards 2023 held at the Wyndham Grand Crete Mi', 0, 1, 6, '2024-06-19 00:05:08', '2026-06-27 13:18:29'),
(8, 'Inspiring Business & Leadership Award 2013 – Category: The Best Choice In Loyalty Service Of The Year 2013', 'inspiring-business-leadership-award-2013-category-the-best-choice-in-loyalty-service-of-the-year-2013', NULL, 'The Inspiring Business & Leadership Award 2013 recognized Nandini Jungle by Hanging Gardens in the category of Best Choice in Loyalty Service of the Year.', '<p>The <strong>Inspiring Business &amp; Leadership Award 2013</strong> recognized <strong>Nandini Jungle by Hanging Gardens</strong> in the category of <strong>Best Choice in Loyalty Service of the Year</strong>. This award highlights the resort\'s exceptional commitment to customer service and guest loyalty, underscoring its dedication to creating memorable experiences for visitors. Nandini Jungle is celebrated for its unique blend of luxury and natural beauty, situated in the heart of Bali\'s lush rainforest, providing guests with an unparalleled retreat and a deep connection to nature&nbsp;</p>', 'Inspiring Business & Leadership Award 2013 – Category: The Best Choice In Loyalty Service Of The Year 2013', 'Inspiring Business & Leadership Award', '2013', NULL, 'images/awards/01JAY9X85BVCZXEEBRCQ1833SX.jpg', 'Inspiring Business & Leadership Award 2013 – Category: The Best Choice In Loyalty Service Of The Year 2013', NULL, NULL, 'images/awards/01JAY9X85BVCZXEEBRCQ1833SX.jpg', 'Inspiring Business & Leadership Award 2013 – Category: The Best Choice In Loyalty Service Of The Year 2013', 'Read More', NULL, 'Inspiring Business & Leadership Award 2013 – Category: The Best Choice In Loyalty Service Of The Year 2013 | Nandini Jungle Resort', 'The Inspiring Business & Leadership Award 2013 recognized Nandini Jungle by Hanging Gardens in the category of Best Choice in Loyalty Service of the Year.', 0, 1, 13, '2024-09-17 13:00:11', '2026-06-27 13:18:29'),
(9, 'Guest Review Awards 2017 (Booking.com) – Score: 8.8 out of 10', 'guest-review-awards-2017-booking-com-score-8-8-out-of-10', NULL, 'The Guest Review Awards 2017 from Booking.com awarded Nandini Jungle by Hanging Gardens an impressive score of 8.8 out of 10. This high rating reflects the resort\'s commitment to exceptional service, quality accommodations, and positive guest experiences.', '<p>The <strong>Guest Review Awards 2017</strong> from <strong>Booking.com</strong> awarded <strong>Nandini Jungle by Hanging Gardens</strong> an impressive score of <strong>8.8 out of 10</strong>. This high rating reflects the resort\'s commitment to exceptional service, quality accommodations, and positive guest experiences. The award is based on verified guest reviews and signifies the resort\'s consistent performance in meeting and exceeding customer expectations, making it a favored choice for travelers seeking a serene and luxurious retreat in Bali​&nbsp;</p>', 'Guest Review Awards 2017 (Booking.com) – Score: 8.8 out of 10', 'Booking.com', '2017', NULL, 'images/awards/01JAYA4F5901W95XC33K3JSVQH.jpg', 'Guest Review Awards 2017 (Booking.com) – Score: 8.8 out of 10', NULL, NULL, 'images/awards/01JAYA4F5901W95XC33K3JSVQH.jpg', 'Guest Review Awards 2017 (Booking.com) – Score: 8.8 out of 10', 'Read More', NULL, 'Guest Review Awards 2017 (Booking.com) – Score: 8.8 out of 10 | Nandini Jungle Resort', 'The Guest Review Awards 2017 from Booking.com awarded Nandini Jungle by Hanging Gardens an impressive score of 8.8 out of 10. This high rating reflects the reso', 0, 1, 12, '2024-09-17 13:00:22', '2026-06-27 13:18:29'),
(10, '2018 Global Experience Award – Thwisht Travel Wish List', '2018-global-experience-award-thwisht-travel-wish-list', NULL, 'The 2018 Global Experience Award from Thwisht Travel recognized Nandini Jungle by Hanging Gardens for its exceptional offerings listed on travel wish lists. This award highlights the resort’s ability to create unique and memorable experiences for its guests, contributing to its reputation as a top destination in Bali.', '<p>The <strong>2018 Global Experience Award</strong> from <strong>Thwisht Travel</strong> recognized <strong>Nandini Jungle by Hanging Gardens</strong> for its exceptional offerings listed on travel wish lists. This award highlights the resort’s ability to create unique and memorable experiences for its guests, contributing to its reputation as a top destination in Bali. The recognition underscores the resort\'s commitment to providing immersive experiences that resonate with travelers looking for a luxurious escape amidst nature.&nbsp;</p>', '2018 Global Experience Award – Thwisht Travel Wish List', 'Thwisht Travel', '2018', NULL, 'images/awards/01JAYAD8ERQT7N3RW33PBXXZD6.jpg', '2018 Global Experience Award – Thwisht Travel Wish List', NULL, NULL, 'images/awards/01JAYAD8ERQT7N3RW33PBXXZD6.jpg', '2018 Global Experience Award – Thwisht Travel Wish List', 'Read More', NULL, '2018 Global Experience Award – Thwisht Travel Wish List | Nandini Jungle Resort', 'The 2018 Global Experience Award from Thwisht Travel recognized Nandini Jungle by Hanging Gardens for its exceptional offerings listed on travel wish lists. Thi', 0, 1, 8, '2024-09-17 13:00:31', '2026-06-27 13:18:29'),
(11, 'Guest Review Awards 2018 (Booking.com) – Score: 8.9 out of 10', 'guest-review-awards-2018-booking-com-score-8-9-out-of-10', NULL, 'The Guest Review Awards 2018 from Booking.com awarded Nandini Jungle by Hanging Gardens a remarkable score of 8.9 out of 10. This score reflects the resort\'s dedication to providing high-quality service, comfortable accommodations, and an overall positive experience for its guests.', '<p>The <strong>Guest Review Awards 2018</strong> from <strong>Booking.com</strong> awarded <strong>Nandini Jungle by Hanging Gardens</strong> a remarkable score of <strong>8.9 out of 10</strong>. This score reflects the resort\'s dedication to providing high-quality service, comfortable accommodations, and an overall positive experience for its guests. The award is based on verified reviews, highlighting the resort\'s consistent performance and commitment to guest satisfaction, making it a top choice for travelers seeking luxury and tranquility in Bali​&nbsp;</p>', 'Guest Review Awards 2018 (Booking.com) – Score: 8.9 out of 10', 'Booking.com', '2018', NULL, 'images/awards/01JAYAK18XXF4QZVS47PM7AVEM.jpg', 'Guest Review Awards 2018 (Booking.com) – Score: 8.9 out of 10', NULL, NULL, 'images/awards/01JAYAK18XXF4QZVS47PM7AVEM.jpg', 'Guest Review Awards 2018 (Booking.com) – Score: 8.9 out of 10', 'Read More', NULL, 'Guest Review Awards 2018 (Booking.com) – Score: 8.9 out of 10 | Nandini Jungle Resort', 'The Guest Review Awards 2018 from Booking.com awarded Nandini Jungle by Hanging Gardens a remarkable score of 8.9 out of 10. This score reflects the resort\'s de', 0, 1, 9, '2024-09-17 13:00:40', '2026-06-27 13:18:29'),
(12, 'National Geographic Traveller (UK) Spa & Wellness Collection 2020', 'national-geographic-traveller-uk-spa-wellness-collection-2020', NULL, NULL, NULL, 'National Geographic Traveller (UK) Spa & Wellness Collection 2020', 'National Geographic Traveller', '2020', NULL, 'images/awards/01J81CASRHV9R0G3D1VY12H1GB.jpg', 'National Geographic Traveller (UK) Spa & Wellness Collection 2020', NULL, NULL, 'images/awards/01J81CASRHV9R0G3D1VY12H1GB.jpg', 'National Geographic Traveller (UK) Spa & Wellness Collection 2020', NULL, NULL, 'National Geographic Traveller (UK) Spa & Wellness Collection 2020 | Nandini Jungle Resort', 'Explore National Geographic Traveller (UK) Spa & Wellness Collection 2020 from Nandini Jungle by Hanging Gardens.', 0, 0, 16, '2024-09-17 13:00:49', '2026-06-27 13:18:29'),
(13, 'Traveloka Certified Hotel Partner', 'traveloka-certified-hotel-partner', NULL, 'The Traveloka Certified Hotel Partner award proudly recognizes Nandini Jungle by Hanging Gardens for its outstanding commitment to excellence in hospitality.', '<p>The <strong>Traveloka Certified Hotel Partner</strong> award proudly recognizes <strong>Nandini Jungle by Hanging Gardens</strong> for its outstanding commitment to excellence in hospitality. This esteemed designation is a testament to the hotel’s unwavering dedication to providing exceptional service, luxurious accommodations, and a unique guest experience amidst the breathtaking beauty of nature.&nbsp;</p>', 'Traveloka Certified Hotel Partner', 'Traveloka', NULL, NULL, 'images/awards/01JAYB2V6SERWSV82GKGASFZKN.png', 'Traveloka Certified Hotel Partner', NULL, NULL, 'images/awards/01JAYB2V6SERWSV82GKGASFZKN.png', 'Traveloka Certified Hotel Partner', 'Read More', NULL, 'Traveloka Certified Hotel Partner | Nandini Jungle Resort', 'The Traveloka Certified Hotel Partner award proudly recognizes Nandini Jungle by Hanging Gardens for its outstanding commitment to excellence in hospitality.', 0, 1, 17, '2024-09-17 13:01:02', '2026-06-27 13:18:29'),
(14, 'Booking.com - 2025 Traveller Review Award', 'booking-com-2025-traveller-review-award', NULL, 'Nandini Jungle by Hanging Gardens is proud to be recognized with the Traveler Review Award 2025, celebrating our commitment to delivering exceptional experiences in the heart of Bali\'s natural beauty.', '<p>Nandini Jungle by Hanging Gardens is proud to be recognized with the Traveler Review Award 2025, celebrating our commitment to delivering exceptional experiences in the heart of Bali\'s natural beauty.&nbsp;</p>', 'Booking.com - 2025 Traveller Review Award', 'Booking.com', '2025', NULL, 'images/awards/01JJNWSK3TJ21FQ3HCKF13B6H3.jpg', 'Booking.com - 2025 Traveller Review Award', NULL, NULL, 'images/awards/01JJNWSK3TJ21FQ3HCKF13B6H3.jpg', 'Booking.com - 2025 Traveller Review Award', 'Read More', NULL, 'Booking.com - 2025 Traveller Review Award | Nandini Jungle Resort', 'Nandini Jungle by Hanging Gardens is proud to be recognized with the Traveler Review Award 2025, celebrating our commitment to delivering exceptional experience', 0, 1, 3, '2025-01-28 14:25:13', '2026-06-27 13:18:29'),
(15, 'BOOKING.COM - 2026 TRAVELLER REVIEW AWARD', 'bookingcom-2026-traveller-review-award', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens is proud to be recognized with the <a href=\"http://Booking.com\">Booking.com</a> Traveller Review Award 2026, achieving an outstanding score of 9.2 out of 10. This award reflects our continued commitment to delivering exceptional guest experiences, warm Balinese hospitality, and unforgettable stays in the heart of Bali’s natural beauty.</p>', '2026 TRAVELLER REVIEW AWARD', 'BOOKING.COM', '2026', NULL, 'awards/hero/8df4c71a-93c5-4d82-a822-2bee62c6aaf2.webp', 'Booking.com Traveller Review Award 2026 awarded to Nandini Jungle by Hanging Gardens with a 9.2 guest review score', 'awards/hero-mobile/booking-com-traveller-review-award-2026-nandini-jungle-bali.webp', 'Booking.com Traveller Review Award 2026 awarded to Nandini Jungle by Hanging Gardens with a 9.2 guest review score', 'awards/cards/booking-com-traveller-review-award-2026-nandini-jungle-bali.webp', 'Booking.com Traveller Review Award 2026 awarded to Nandini Jungle by Hanging Gardens with a 9.2 guest review score', NULL, NULL, NULL, NULL, 0, 1, 2, '2026-06-23 21:09:09', '2026-06-27 13:18:29'),
(16, 'TRIPADVISOR - 2026 TRAVELERS\' CHOICE AWARD', 'tripadvisor-2026-travelers-choice-award', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens is proud to be recognized with the Tripadvisor Travelers&#039; Choice Award 2026. This award celebrates our continued commitment to delivering memorable stays, warm Balinese hospitality, and exceptional guest experiences surrounded by the natural beauty of Ubud, Bali.</p>', '2026 TRAVELERS\' CHOICE AWARD', 'TRIPADVISOR', '2026', NULL, 'awards/hero/tripadvisor-travelers-choice-award-2026-nandini-jungle-bali-4.webp', 'Tripadvisor Travelers\' Choice Award 2026 badge for Nandini Jungle by Hanging Gardens in Ubud, Bali', 'awards/hero-mobile/tripadvisor-travelers-choice-award-2026-nandini-jungle-bali-4.webp', 'Tripadvisor Travelers\' Choice Award 2026 badge for Nandini Jungle by Hanging Gardens in Ubud, Bali', 'awards/cards/tripadvisor-travelers-choice-award-2026-nandini-jungle-bali-4.webp', 'Tripadvisor Travelers\' Choice Award 2026 badge for Nandini Jungle by Hanging Gardens in Ubud, Bali', NULL, NULL, NULL, NULL, 0, 1, 1, '2026-06-23 21:26:45', '2026-06-27 13:18:29'),
(17, 'BEST LUXURY JUNGLE RETREAT 2024', 'best-luxury-jungle-retreat-2024', NULL, NULL, '<p><strong>NANDINI JUNGLE BY HANGING GARDENS</strong> was honored as the winner of <strong>BEST LUXURY JUNGLE RETREAT 2024</strong> at the Seven Stars Luxury, Hospitality and Lifestyle Awards. This recognition celebrates Nandini Jungle by Hanging Gardens as an exceptional jungle sanctuary in Bali, combining authentic Balinese hospitality, refined luxury, and an immersive natural setting in the heart of Ubud’s lush rainforest.</p>', 'BEST LUXURY JUNGLE RETREAT 2024', 'Seven Stars Luxury, Hospitality and Lifestyle Awards', '2024', NULL, 'awards/hero/nandini-jungle-by-hanging-gardens-best-luxury-jungle-retreat-2024-award.webp', 'Nandini Jungle by Hanging Gardens winner of Best Luxury Jungle Retreat 2024 at the Seven Stars Luxury Hospitality and Lifestyle Awards', 'awards/hero-mobile/nandini-jungle-by-hanging-gardens-best-luxury-jungle-retreat-2024-award.webp', 'Nandini Jungle by Hanging Gardens winner of Best Luxury Jungle Retreat 2024 at the Seven Stars Luxury Hospitality and Lifestyle Awards', 'awards/cards/nandini-jungle-by-hanging-gardens-best-luxury-jungle-retreat-2024-award.webp', 'Nandini Jungle by Hanging Gardens winner of Best Luxury Jungle Retreat 2024 at the Seven Stars Luxury Hospitality and Lifestyle Awards', NULL, NULL, NULL, NULL, 0, 1, 5, '2026-06-27 13:17:16', '2026-06-27 13:18:29'),
(18, 'BEST LUXURY JUNGLE RETREAT & SPA 2025', 'best-luxury-jungle-retreat-spa-2025', NULL, NULL, '<p><strong>NANDINI JUNGLE BY HANGING GARDENS</strong> proudly received the <strong>BEST LUXURY JUNGLE RETREAT &amp; SPA 2025</strong> award at the Seven Stars Luxury, Hospitality and Lifestyle Awards. This prestigious achievement highlights Nandini’s continued excellence as a luxury jungle retreat and wellness destination, offering guests a serene escape surrounded by nature, personalized service, and restorative spa experiences inspired by the beauty and spirit of Bali.</p>', 'BEST LUXURY JUNGLE RETREAT & SPA 2025', 'Seven Stars Luxury, Hospitality and Lifestyle Awards', '2025', NULL, 'awards/hero/nandini-jungle-by-hanging-gardens-best-luxury-jungle-retreat-spa-2025-award.webp', 'Nandini Jungle by Hanging Gardens winner of Best Luxury Jungle Retreat and Spa 2025 at the Seven Stars Luxury Hospitality and Lifestyle Awards', 'awards/hero-mobile/nandini-jungle-by-hanging-gardens-best-luxury-jungle-retreat-spa-2025-award.webp', 'Nandini Jungle by Hanging Gardens winner of Best Luxury Jungle Retreat and Spa 2025 at the Seven Stars Luxury Hospitality and Lifestyle Awards', 'awards/cards/nandini-jungle-by-hanging-gardens-best-luxury-jungle-retreat-spa-2025-award.webp', 'Nandini Jungle by Hanging Gardens winner of Best Luxury Jungle Retreat and Spa 2025 at the Seven Stars Luxury Hospitality and Lifestyle Awards', NULL, NULL, NULL, NULL, 0, 1, 4, '2026-06-27 13:18:15', '2026-06-27 13:18:29');

