INSERT INTO `experiences` (`id`, `experience_category_id`, `title`, `slug`, `subtitle`, `excerpt`, `description`, `inclusions`, `duration`, `location`, `image`, `image_alt`, `card_image`, `card_image_alt`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 1, 'Balinese blessing purification at the holy river', 'balinese-blessing-purification-at-the-holy-river', NULL, 'Surrender to the embrace of Bali\'s healing waters with a sacred purification ritual led by a Balinese priest. This riverside wellness retreat renews your body and soul in a soulful, restorative escape.', '<p>Surrender to the embrace of Bali&#039;s healing waters with a sacred purification ritual led by a Balinese priest. This riverside wellness retreat renews your body and soul in a soulful, restorative escape.<br><br><strong>Inclusions:</strong><br>A healthy welcome drink upon arrival<br>Traditional Balinese sarong and towels provided<br>Balinese healing and purification ritual with energy transfer led by Pemangku</p>', '<p></p>', NULL, NULL, 'experiences/b377fe4a-8726-49d4-931e-18d017ce6837.webp', 'Balinese blessing purification at the holy river', 'experiences/b377fe4a-8726-49d4-931e-18d017ce6837.webp', 'Balinese blessing purification at the holy river', 0, 1, 1, 'Balinese Blessing Purification at the Holy River | Nandini Bali', 'Experience a Balinese blessing purification at Nandini’s Holy River in Ubud, with healing rituals, traditional sarong, welcome drink, and priest-led cleansing.', '2026-05-01 00:00:44', '2026-05-03 22:55:58'),
(2, 1, 'sacred waters: Half-Day Ubud Healing Retreat', 'sacred-waters-half-day-ubud-healing-retreat', NULL, 'Reconnect with nature and your inner self through a serene half-day wellness journey by the river. Begin with our signature Spa at the River treatment designed to relax and restore body and mind. Continue with a Melukat purification ritual, a sacred Balinese blessing led by a traditional priest to cleanse and renew your spirit.', '<p>Reconnect with nature and your inner self through a serene half-day wellness journey by the river. Begin with our signature Spa at the River treatment designed to relax and restore body and mind. Continue with a Melukat purification ritual, a sacred Balinese blessing led by a traditional priest to cleanse and renew your spirit.<br><br><strong>Inclusions:</strong><br>Traditional Balinese sarong and towels<br>Melukat purification and blessing ceremony by the river<br>Signature Spa at the River treatment for two<br>60-minutes Exotic Balinese massage<br>30-minutes Body mask<br>30-minutes Body Scrub treatment<br>Couple of tea at the spa reception</p>', '<p></p>', NULL, NULL, 'experiences/2020a644-e920-4642-8fb0-7abb772b6301.webp', NULL, 'experiences/2020a644-e920-4642-8fb0-7abb772b6301.webp', NULL, 0, 1, 2, 'Half-Day Wellness Journey by the River | Nandini Bali', 'Reconnect with nature through a half-day wellness journey at Nandini Bali, featuring Spa at the River, Melukat purification, Balinese massage, and body treatments.', '2026-05-01 00:55:06', '2026-05-03 22:55:58'),
(3, 1, 'Nandini Signature:  Spa On The River', 'nandini-signature-spa-on-the-river', NULL, 'Indulge in the ultimate riverside retreat by the sacred Ayung River. Begin your journey with a soothing foot bath, followed by a 180-minute signature spa treatment, serenaded by the sounds of the rushing waters.', '<p>Indulge in the ultimate riverside retreat by the sacred Ayung River. Begin your journey with a soothing foot bath, followed by a 180-minute signature spa treatment, serenaded by the sounds of the rushing waters.<br><br><strong>Inclusions:</strong><br>60-minutes Exotic Balinese massage<br>30-minutes Body mask<br>30-minutes Body Scrub treatment<br>60-minutes Relaxing Facial Treatments</p>', '<p></p>', NULL, NULL, 'experiences/2524f045-fe0a-4001-9a5f-f0f9810e2612.webp', 'Riverside Spa Retreat by Ayung River | Nandini Bali', 'experiences/2524f045-fe0a-4001-9a5f-f0f9810e2612.webp', 'Riverside Spa Retreat by Ayung River | Nandini Bali', 0, 1, 3, 'Riverside Spa Retreat by Ayung River | Nandini Bali', 'Indulge in a riverside spa retreat by the sacred Ayung River at Nandini Bali, with a soothing foot bath, signature spa treatment, massage, scrub, mask, and facial.', '2026-05-01 01:05:09', '2026-05-03 22:55:58'),
(4, 2, 'Blissful Calm', 'blissful-calm', 'A JOURNEY INTO WELL-BEING', 'A Journey into well-being. A serene wellness experience designed with care for your body, mind, and soul—set within the calming embrace of the jungle.', '<p>A serene wellness experience designed with care for your body, mind, and soul—set within the calming embrace of the jungle.<br><br><strong>Inclusions:</strong><br>45 minutes of Private Yoga Session<br>60 minutes of Exotic Spa Treatment<br>30 minutes of Complimentary Reflexology</p>', '<p></p>', NULL, NULL, 'experiences/main/ad3abde6-b5d6-4a8e-949f-e8bf104760da.webp', 'Blissful Calm Wellness Experience in Bali | Yoga, Spa & Reflexology', 'experiences/cards/ab484850-1d4d-402a-bbfb-a1ee743d38b1.webp', 'Blissful Calm Wellness Experience in Bali | Yoga, Spa & Reflexology', 0, 1, 31, 'Blissful Calm Wellness Experience in Bali | Yoga, Spa & Reflexology', 'Indulge in a serene jungle wellness journey featuring a 45-minute private yoga session, 60-minute exotic spa treatment, and 30-minute complimentary reflexology for complete body.', '2026-02-26 12:07:16', '2026-05-03 23:03:04'),
(5, 2, 'Intimate Wellness Rituals', 'intimate-wellness-rituals', 'WHERE STILLNESS HEALS AND ENERGY ALIGNS', 'Where stillness heals and energy aligns. A timeless ritual of movement and restoration, beginning with a 60-minute private yoga practice and continuing with a 30-minute energy healing session—held within the hidden calm of river and jungle.', '<p>A timeless ritual of movement and restoration, beginning with a 60-minute private yoga practice and continuing with a 30-minute energy healing session—held within the hidden calm of river and jungle.</p>', '<p></p>', NULL, NULL, 'experiences/main/a6c8d729-1fbc-49ac-99c3-eddc007f1f81.webp', 'Intimate Wellness Rituals in Bali | Private Yoga & Energy Healing', 'experiences/cards/873daa1d-4111-43ec-8095-8be818c29ff6.webp', 'Intimate Wellness Rituals in Bali | Private Yoga & Energy Healing', 0, 1, 30, 'Intimate Wellness Rituals in Bali | Private Yoga & Energy Healing', 'Reconnect through a 60-minute private yoga session followed by a 30-minute energy healing ritual in serene jungle surroundings. A restorative wellness experience in Bali.', '2026-02-26 09:16:27', '2026-05-03 23:01:55'),
(6, 2, 'A Sacred Moment of Renewal', 'a-sacred-moment-of-renewal', 'A GUIDED PURIFICATION AND MEDITATION EXPERIENCE ROOTED IN TRADITION', 'A guided purification and meditation experience rooted in tradition. A timeless ritual of renewal for body and spirit, guided by water and embraced by jungle serenity—featuring a 30-minute blessing purification followed by a 45-minute meditation by the river.', '<p>A timeless ritual of renewal for body and spirit, guided by water and embraced by jungle serenity—featuring a 30-minute blessing purification followed by a 45-minute meditation by the river.</p>', '<p></p>', NULL, NULL, 'experiences/main/5c4c2115-48a0-4fce-bdda-abe75c5fcc75.webp', 'Sacred Renewal Ritual in Bali | Blessing & River Meditation Experience', 'experiences/cards/ea58e6b3-2d4a-4f0a-84c6-ebed8284887b.webp', 'Sacred Renewal Ritual in Bali | Blessing & River Meditation Experience', 0, 1, 29, 'Sacred Renewal Ritual in Bali | Blessing & River Meditation Experience', 'Join a sacred purification ritual in Bali featuring a 30-minute blessing ceremony and 45-minute river meditation. A guided spiritual renewal experience surrounded by serene.', '2026-02-26 09:07:50', '2026-05-03 23:05:49'),
(7, 2, 'From Bike Trails to Bar Skills', 'from-bike-trails-to-bar-skills', 'WHERE MOVEMENT MEETS MIXOLOGY', 'Where movement meets mixology. A graceful balance of adventure and elegance, beginning with a 60-minute morning cycling journey and continuing with a 60-minute cocktails class creating three cocktails—where jungle air meets the art of mixology.', '<p>A graceful balance of adventure and elegance, beginning with a 60-minute morning cycling journey and continuing with a 60-minute cocktails class creating three cocktails—where jungle air meets the art of mixology.</p>', '<p></p>', NULL, NULL, 'experiences/main/cde2b6ef-723b-4b5b-ab39-b45a920628c0.webp', 'Bike Trails to Bar Skills Experience in Bali | Cycling & Cocktail Class', 'experiences/cards/836ada4d-2595-4d64-b3a1-f9197792b4f2.webp', 'Bike Trails to Bar Skills Experience in Bali | Cycling & Cocktail Class', 0, 1, 28, 'Bike Trails to Bar Skills in Bali | Nandini Jungle', 'Enjoy a unique Bali experience combining a 60-minute morning cycling tour with a 60-minute cocktail-making class. Discover where jungle adventure meets the art of mixology.', '2026-02-26 09:14:41', '2026-05-03 23:05:25'),
(19, 5, 'In-Suite Personalized Bartender Sevice', 'in-suite-personalized-bartender-sevice', NULL, 'In-Suite personal bartender service. Enjoy our signature cocktails in the comfort of your suite. Our experienced bartender creates your favorite cocktails in front of you in your own suite.', '<p>In-Suite personal bartender service. Enjoy our signature cocktails in the comfort of your suite. Our experienced bartender creates your favorite cocktails in front of you in your own suite.</p>', '<p></p>', NULL, NULL, 'experiences/main/44035801-d49d-4b9d-9e99-e28ab3ec2736.webp', 'In-Suite Personalized Bartender Sevice', 'experiences/cards/a86ad5f5-132b-4eac-af31-7206a0560edc.webp', 'In-Suite Personalized Bartender Sevice', 0, 1, 18, 'In-Suite Personalized Bartender Service | Private Cocktail Experience', 'Enjoy a private in-suite bartender service with handcrafted signature cocktails prepared live in the comfort of your suite. A refined, personalized luxury experience.', '2024-06-17 20:07:28', '2026-05-03 22:55:58'),
(18, 5, 'Cooking Class', 'cooking-class', NULL, 'You are what you eat. Our executive chef Gustu brings this philosophy to heart and invites all our guests to enjoy the excellence of Balinese cooking made by themselves.', '<p>You are what you eat. Our executive chef Gustu brings this philosophy to heart and invites all our guests to enjoy the excellence of Balinese cooking made by themselves.<br><br>Join Nandini Cooking Class and learn how to cook like a Balinese, bringing a culinary journey you experienced to your home.<br><br><strong>24 hours booking is required in advance.</strong></p>', '<p></p>', NULL, NULL, 'experiences/main/54986383-f3ff-445e-97e0-fee0fd4f173a.webp', 'Balinese Cooking Class | Authentic Culinary Experience in Bali', 'experiences/cards/0a328525-7f53-43f9-b4e0-c1481e36ac4b.webp', 'Balinese Cooking Class | Authentic Culinary Experience in Bali', 0, 1, 17, 'Balinese Cooking Class | Authentic Culinary Experience in Bali', 'Join an immersive Balinese cooking class guided by an expert chef. Learn traditional recipes, cook with fresh local ingredients, and bring the flavors of Bali home with you.', '2024-06-17 20:06:22', '2026-05-03 22:55:58'),
(22, 4, 'Jungle Wellness & Retreat Day Pass', 'jungle-wellness-retreat-day-pass', NULL, 'Reconnect with your body and spirit in the peaceful embrace of the jungle. Start with rejuvenating yoga, then indulge in a traditional Balinese massage for two. ', '<p>Reconnect with your body and spirit in the peaceful embrace of the jungle. Start with rejuvenating yoga, then indulge in a traditional Balinese massage for two. Savor a hearty 3-course meal and afternoon high tea. Enjoy exclusive access to the sacred Ayung River, where the healing energy flows through this secluded wellness retreat in Ubud’s lush jungle.</p>', '<p></p>', NULL, NULL, 'experiences/main/jungle-wellness-retreat-day-pass-nandini-bali.webp', 'Couple relaxing beside a jungle-view pool during a wellness retreat day pass at Nandini Jungle by Hanging Gardens.', 'experiences/cards/jungle-wellness-retreat-day-pass-nandini-bali.webp', 'Couple relaxing beside a jungle-view pool during a wellness retreat day pass at Nandini Jungle by Hanging Gardens.', 0, 1, 13, 'Jungle Wellness & Retreat Day Pass | Holistic Escape in Ubud', 'Rejuvenate mind and body with a jungle wellness day pass featuring yoga, guided meditation, traditional Balinese massage, dining, and serene river access in Ubud’s lush.', '2024-09-27 09:50:47', '2026-07-15 17:54:26'),
(16, 4, 'Yoga at DJiwa Shala', 'yoga-at-djiwa-shala', NULL, 'Ubud and yoga is inseparable, the tranquility of rainforest and rice fields bring the great zen that is great for mind and body.', '<p>With the tranquility of rainforests and rice fields, Ubud is synonymous with yoga, a place for mind and body to find great zen.<br><br>Among the rice fields of Ubud, a 97-square-meter Djiwa Shala is designed for Yoga and peace. With the sound of the breeze and the hymn of the birds in the rice fields, you&#039;ll experience a relaxing Yoga with a unique experience.</p>', '<p></p>', NULL, NULL, 'experiences/main/46e88c77-a2e2-4ab4-b10f-f2745c0665e3.webp', 'Yoga at Djiwa Shala | Tranquil Yoga Experience in Ubud', 'experiences/cards/1132dfc6-93ee-488c-95c0-40a0d8e4aed9.webp', 'Yoga at Djiwa Shala | Tranquil Yoga Experience in Ubud', 0, 1, 10, 'Yoga at Djiwa Shala | Tranquil Yoga Experience in Ubud', 'Experience yoga at Djiwa Shala, surrounded by Ubud’s rainforest and rice fields. A peaceful practice designed to restore balance, clarity, and inner calm in nature.', '2024-06-17 20:03:39', '2026-05-03 22:55:58'),
(44, 3, 'Elephant Park Tour', 'elephant-park-tour', NULL, 'Step into a world of wonder at The Mason Elephant Park, a 3.5-hectare sanctuary of tropical gardens and forest, home to Indonesia’s largest herd of Sumatran elephants. Thoughtfully landscaped by expert horticulturists, the park blends natural beauty with a nurturing haven for these gentle giants.', '<p>Step into a world of wonder at The Mason Elephant Park, a 3.5-hectare sanctuary of tropical gardens and forest, home to Indonesia’s largest herd of Sumatran elephants. Thoughtfully landscaped by expert horticulturists, the park blends natural beauty with a nurturing haven for these gentle giants.</p><p><br>Hand-feed the elephants, share unforgettable moments up close, and marvel at their playful charm in an enchanting show. Conclude your journey with a delightful lunch surrounded by lush greenery - an experience that connects you with nature at its most extraordinary.</p>', '<p></p>', NULL, NULL, 'experiences/main/75ff416b-7a2a-4dc0-bc1f-96d3fdb8afad.webp', 'Elephant Park Tour | Hand-Feed Elephants & Garden Lunch', 'experiences/cards/7841c5cb-37b7-454b-8845-1356402f3c81.webp', 'Elephant Park Tour | Hand-Feed Elephants & Garden Lunch', 0, 1, 26, 'Elephant Park Tour | Hand-Feed Elephants & Garden Lunch', 'Discover a remarkable elephant park set within lush tropical gardens. Get up close with gentle Sumatran elephants, enjoy interactive moments, and conclude with a relaxing garden.', '2025-10-01 09:41:17', '2026-07-25 21:22:53'),
(20, 6, 'Romantic Dining by The Chapel', 'romantic-dining-by-the-chapel', NULL, 'Treat your love to an unforgettable romantic dinner under the moonlight at Nandini Jungle. Experience royal treatment and a magical evening by our iconic chapel overlooking the mystical jungle pool.', '<p>Treat your love to an unforgettable romantic dinner under the moonlight at Nandini Jungle. Experience royal treatment and a magical evening by our iconic chapel overlooking the mystical jungle pool.</p>', '<p></p>', NULL, NULL, 'experiences/main/romantic-dining-by-the-chapel-nandini-jungle-bali-2.webp', 'Romantic candlelit dining by the chapel at Nandini Jungle by Hanging Gardens in Bali.', 'experiences/cards/romantic-dining-by-the-chapel-nandini-jungle-bali-2.webp', 'Romantic candlelit dining by the chapel at Nandini Jungle by Hanging Gardens in Bali.', 0, 1, 6, 'Romantic Dining by the Chapel | Private Candlelit Dinner Experience', 'Enjoy an unforgettable romantic dining experience by the chapel with a private candlelit dinner under the moonlight, surrounded by tranquil jungle ambiance and timeless elegance.', '2024-08-23 23:24:47', '2026-07-13 17:36:06'),
(23, 4, 'Self-Healing Day Pass', 'self-healing-day-pass', NULL, 'Begin your journey to inner peace with a sacred Balinese Blessing Purification by the healing waters of the Ayung River. Follow with an indulgent couples\' massage and afternoon high tea. ', '<p>Begin your journey to inner peace with a sacred Balinese Blessing Purification by the healing waters of the Ayung River. Follow with an indulgent couples&#039; massage and afternoon high tea. With exclusive access to the river and full-day pool access, this package invites you to experience the deep spiritual wellness that only our Ubud healing retreat can offer.</p>', '<p></p>', NULL, NULL, 'experiences/main/self-healing-day-pass-sacred-river-ritual-nandini-bali.webp', 'Couple joining a traditional Balinese purification ritual during the Self-Healing Day Pass at Nandini Jungle by Hanging Gardens.', 'experiences/cards/self-healing-day-pass-sacred-river-ritual-nandini-bali.webp', 'Couple joining a traditional Balinese purification ritual during the Self-Healing Day Pass at Nandini Jungle by Hanging Gardens.', 0, 1, 14, 'Self-Healing Day Pass | Sacred River Wellness Experience', 'Restore inner peace with a Self-Healing Day Pass featuring sacred river purification, a relaxing couples’ massage, and refined afternoon high tea in a serene jungle setting.', '2024-09-27 09:51:12', '2026-07-13 17:31:15'),
(24, 3, 'Balinese Village Cultural Experience Day Pass', 'balinese-village-cultural-experience-day-pass', NULL, 'Step into the heart of Bali’s rich traditions with a guided sunset walk through the village, traditional bamboo kite-making, and an exclusive \"Nasi Jinggo One Hundred Dollars\" meal. ', '<p>Step into the heart of Bali’s rich traditions with a guided sunset walk through the village, traditional bamboo kite-making, and an exclusive &quot;Nasi Jinggo One Hundred Dollars&quot; meal. Immerse yourself in the sacred ambiance of the jungle, with all-day access to the Mystical Jungle Pool, and exclusive entry to the Ayung River, a true cultural and spiritual retreat.</p>', '<p></p>', NULL, NULL, 'experiences/main/096f774c-0c26-4c21-ba7d-043fb713fb93.webp', 'Balinese Village Cultural Experience Day Pass | Authentic Traditions', 'experiences/cards/6d5dc5eb-ffd1-4f8c-9cc2-3ed2a3c0f6f7.webp', 'Balinese Village Cultural Experience Day Pass | Authentic Traditions', 0, 1, 20, 'Balinese Village Cultural Experience Day Pass | Authentic Traditions', 'Immerse yourself in Balinese village life with a cultural day pass featuring a guided sunset walk, traditional bamboo kite-making, exclusive dining, and serene jungle surroundings.', '2024-09-27 09:51:38', '2026-05-03 22:55:58'),
(25, 3, 'Regular Day Pass', 'regular-day-pass', NULL, 'Escape into tranquility with our Regular Day Pass. Relish IDR 500,000 in resort credit, perfect for indulging in gourmet dining, spa rituals, or immersive experiences. Surrounded by the spiritual energy of the sacred Ayung River, your day of rejuvenation awaits at Bali’s most serene healing resort.', '<p>Escape into tranquility with our Regular Day Pass. Relish IDR 500,000 in resort credit, perfect for indulging in gourmet dining, spa rituals, or immersive experiences. Surrounded by the spiritual energy of the sacred Ayung River, your day of rejuvenation awaits at Bali’s most serene healing resort.</p>', '<p></p>', NULL, NULL, 'experiences/main/regular-day-pass-nandini-jungle-bali.webp', 'Couple relaxing on poolside loungers during a day pass at Nandini Jungle by Hanging Gardens in Bali.', 'experiences/cards/regular-day-pass-nandini-jungle-bali.webp', 'Couple relaxing on poolside loungers during a day pass at Nandini Jungle by Hanging Gardens in Bali.', 0, 1, 19, 'Regular Day Pass | Relaxing Resort Day Experience in Bali', 'Enjoy a peaceful escape with a Regular Day Pass featuring resort credit for dining, spa treatments, and immersive experiences, all set beside the serene Ayung River.', '2024-09-27 09:52:23', '2026-07-13 17:19:04'),
(26, 6, 'Moonlit Jungle Romance', 'moonlit-jungle-romance', 'Intimate candlelight dinner by Nandini\'s jungle pool', 'Bask in an evening of romance under the moonlit sky, savoring a four-course dinner by the pool. As the sun sets beyond the jungle’s canopy, the soft candlelight envelops you, transforming your night into an intimate, dreamlike escape—a memory to cherish forever.', '<p>Bask in an evening of romance under the moonlit sky, savoring a four-course dinner by the pool. As the sun sets beyond the jungle’s canopy, the soft candlelight envelops you, transforming your night into an intimate, dreamlike escape—a memory to cherish forever.</p>', '<p></p>', NULL, NULL, 'experiences/main/66c499cd-618c-48b9-837c-2d9158b07b24.webp', 'Moonlit Jungle Romance | Candlelit Poolside Dinner Experience', 'experiences/cards/7364ab25-f4ca-41f8-b181-b254899ae3be.webp', 'Moonlit Jungle Romance | Candlelit Poolside Dinner Experience', 0, 1, 4, 'Moonlit Jungle Romance | Candlelit Poolside Dinner Experience', 'Enjoy a magical moonlit jungle romance with an intimate four-course candlelit dinner by the pool. Surrounded by soft lights and jungle serenity, this enchanting evening is made.', '2024-11-09 07:52:31', '2026-05-03 22:55:58'),
(27, 4, 'Riverside Sanctuary Spa Package', 'riverside-sanctuary-spa-package', NULL, 'Indulge in the ultimate riverside retreat by the sacred Ayung River. Begin your journey with a soothing foot bath, followed by a combination of our signature spa treatments—traditional Balinese massage, body mask, and body scrub, serenaded by the sounds of the rushing waters.', '<p>Indulge in the ultimate riverside retreat by the sacred Ayung River. Begin your journey with a soothing foot bath, followed by a combination of our signature spa treatments—traditional Balinese massage, body mask, and body scrub, serenaded by the sounds of the rushing waters.</p>', '<p></p>', NULL, NULL, 'experiences/main/9b3cf57f-ac67-4dd7-9871-ca2a055b6343.webp', 'Riverside Sanctuary Spa Package | Ultimate Ayung River Retreat', 'experiences/cards/21025695-2987-4ad7-a8d2-f628791cc323.webp', 'Riverside Sanctuary Spa Package | Ultimate Ayung River Retreat', 0, 1, 7, 'Riverside Sanctuary Spa Package | Ultimate Ayung River Retreat', 'Indulge in a serene riverside spa journey by the sacred Ayung River, featuring a soothing foot bath, traditional Balinese massage, body scrub, and body mask, all accompanied by.', '2024-11-09 07:58:15', '2026-05-03 22:55:58'),
(29, 4, 'Luxury Spa Package: Wine Spa', 'luxury-spa-package-wine-spa', NULL, 'Designed to renew both body and spirit, this 2.5-hour wellness ritual blends ancient Balinese massage techniques with the potent antioxidants of wine, deeply nourishing the skin.', '<p>Designed to renew both body and spirit, this 2.5-hour wellness ritual blends ancient Balinese massage techniques with the potent antioxidants of wine, deeply nourishing the skin. The journey features a gentle flower bath and a ceremonial wine-pouring, complemented by celebratory glasses of red wine and canapés amidst the ambiance of the jungle and the sound of the river.<br><br><strong>Includes:</strong></p><ul><li><p>60-minute traditional Balinese massage</p></li><li><p>wine-infused body scrub</p></li><li><p>wine-infused body mask</p></li><li><p>a luxe flower bath</p></li><li><p>2 glasses of red wine and chef’s curated canapés</p></li></ul>', '<p></p>', NULL, NULL, 'experiences/main/28a2dfe0-aaea-4c5c-b596-8cf51d025779.webp', 'Luxury Wine Spa Package | Indulgent Wellness Ritual', 'experiences/cards/78e8cc44-0a2b-49e5-8e87-102827601ff1.webp', 'Luxury Wine Spa Package | Indulgent Wellness Ritual', 0, 1, 8, 'Luxury Wine Spa Package | Indulgent Wellness Ritual', 'Indulge in a luxurious wine spa experience featuring Balinese massage, wine-infused body treatments, a flower bath, and celebratory wine and canapés in a serene jungle setting.', '2024-11-09 08:00:44', '2026-05-03 22:55:58'),
(30, 4, 'Hatha Yoga & Lunch', 'hatha-yoga-lunch', NULL, 'Centered on breathwork and alignment, the Hatha Yoga session invites you to breathe in rhythm with nature, cultivating balance and inner calm amid the lush rice paddies.', '<p>Centered on breathwork and alignment, the Hatha Yoga session invites you to breathe in rhythm with nature, cultivating balance and inner calm amid the lush rice paddies. Conclude your healing journey with a nourishing lunch for two, thoughtfully prepared to enrich and rejuvenate your afternoon at our serene wellness resort.</p>', '<p></p>', NULL, NULL, 'experiences/main/fdabd4ef-864d-46cc-8256-de3bbb6a5586.webp', 'Hatha Yoga & Lunch | Wellness Experience in Nature', 'experiences/cards/d367325f-a4e4-4415-a7f6-41d2a2141f2f.webp', 'Hatha Yoga & Lunch | Wellness Experience in Nature', 0, 1, 11, 'Hatha Yoga & Lunch | Wellness Experience in Nature', 'Enjoy a rejuvenating Hatha Yoga session focused on breath and balance, followed by a nourishing lunch. A serene wellness experience set amid lush rice paddies and tranquil nature.', '2024-11-09 08:12:56', '2026-05-03 22:55:58'),
(31, 5, 'Luxe High Tea', 'luxe-high-tea', NULL, 'Relish a refined afternoon with our Luxe High Tea amidst the verdant jungles of Ubud. Delight in premium teas, freshly brewed coffee, and a chef-curated selection of sweet and savory bites blending flavors from East and West. An elegant indulgence for two, this experience offers a perfect pause as your day drifts into a tranquil dusk.', '<p>Relish a refined afternoon with our Luxe High Tea amidst the verdant jungles of Ubud. Delight in premium teas, freshly brewed coffee, and a chef-curated selection of sweet and savory bites blending flavors from East and West. An elegant indulgence for two, this experience offers a perfect pause as your day drifts into a tranquil dusk.</p>', '<p></p>', NULL, NULL, 'experiences/main/d84ba74e-87a1-4b3b-a904-3c2142a58d33.webp', 'Luxe High Tea in Ubud | Elegant Afternoon Tea Experience', 'experiences/cards/d10a3431-a83f-4735-b419-e4561f3d7dfb.webp', 'Luxe High Tea in Ubud | Elegant Afternoon Tea Experience', 0, 1, 16, 'Luxe High Tea in Ubud | Elegant Afternoon Tea Experience', 'Indulge in a refined Luxe High Tea set amidst Ubud’s lush jungle surroundings. Enjoy premium teas, freshly brewed coffee, and curated sweet and savory delights for a relaxing.', '2024-11-09 08:13:44', '2026-05-03 22:55:58'),
(32, 6, 'Riverside Romance', 'riverside-romance', 'Intimate candlelight dinner at the mystical Ayung River', 'Descend through lush jungle paths to the riverbank, where a truly intimate, six-course dinner awaits you. As you approach the wooden deck suspended above the Ayung River, the scene unfolds: hundreds of breathtaking, flickering candlelights.', '<p>Descend through lush jungle paths to the riverbank, where a truly intimate, six-course dinner awaits you. As you approach the wooden deck suspended above the Ayung River, the scene unfolds: hundreds of breathtaking, flickering candlelights. The sound of the rushing water drowns out the world beyond, drawing your body and spirit into a timeless moment with your loved one.</p>', '<p></p>', NULL, NULL, 'experiences/main/79b27fd8-8a3b-435d-a2b4-a88be75d645b.webp', 'Riverside Romance | Private Candlelit Dinner by the Ayung River', 'experiences/cards/c7329aa9-3ce8-45fa-9076-4e68a3b9cbe9.webp', 'Riverside Romance | Private Candlelit Dinner by the Ayung River', 0, 1, 5, 'Riverside Romance | Private Candlelit Dinner by the Ayung River', 'Experience an unforgettable riverside romance with a private six-course candlelit dinner above the Ayung River. Surrounded by jungle serenity, flickering lights, and flowing.', '2024-11-09 08:15:25', '2026-05-03 22:55:58'),
(33, 4, 'Riverside Bliss: Half-Day Picnic and Wellness Escape at the River', 'riverside-bliss-half-day-picnic-and-wellness-escape-at-the-river', NULL, 'Treat your loved one to an intimate riverside picnic by the scenic river\'s edge for moments of leisure and connection amidst the pristine Ubud jungle. ', '<p>Treat your loved one to an intimate riverside picnic by the scenic river&#039;s edge for moments of leisure and connection amidst the pristine Ubud jungle. Cooled by the river’s touch and enriched by a traditional Balinese massage for two, this restorative retreat invites you to slow down, savor the present, and breathe in harmony with the heart of nature.</p>', '<p></p>', NULL, NULL, 'experiences/main/e113296d-0015-4549-a4e4-d9495cc50169.webp', 'Riverside Bliss Half-Day Picnic & Wellness Escape | Romantic Retreat', 'experiences/cards/0acc3f2d-b6d6-4dd0-81fe-ca97ab164990.webp', 'Riverside Bliss Half-Day Picnic & Wellness Escape | Romantic Retreat', 0, 1, 9, 'Riverside Bliss Half-Day Picnic & Wellness Escape | Romantic Retreat', 'Enjoy a serene half-day riverside picnic paired with a relaxing wellness experience. Unwind by the river, savor intimate moments, and reconnect amidst Ubud’s pristine jungle.', '2024-12-06 09:45:10', '2026-05-03 22:55:58'),
(37, 4, 'Yoga or Chakra Meditation at Sacred River', 'yoga-or-chakra-meditation-at-sacred-river', NULL, 'Awaken your spirit by the sacred river, where the gentle flow of water and the heartbeat of the jungle create a sanctuary of renewal. Embrace yoga that moves in harmony with nature’s rhythm, restoring balance, vitality, and inner calm.', '<p>Awaken your spirit by the sacred river, where the gentle flow of water and the heartbeat of the jungle create a sanctuary of renewal. Embrace yoga that moves in harmony with nature’s rhythm, restoring balance, vitality, and inner calm. Or journey within through chakra meditation, a powerful practice that purifies and aligns the seven chakras. When your energy centers are in harmony, you become more attuned to the natural flow of the universe, opening the path to clarity, well-being, and deep inner peace.</p>', '<p></p>', NULL, NULL, 'experiences/main/2c1ace46-a39b-4a85-a604-88c80da56159.webp', 'Yoga or Chakra Meditation at Sacred River | Wellness Experience', 'experiences/cards/9d8c9dc9-3224-47a8-a0cc-082e095b1938.webp', 'Yoga or Chakra Meditation at Sacred River | Wellness Experience', 0, 1, 12, 'Yoga or Chakra Meditation at Sacred River | Wellness Experience', 'Reconnect mind and body with yoga or chakra meditation by a sacred river. Experience deep relaxation, energy alignment, and inner balance surrounded by tranquil jungle nature.', '2025-04-11 10:40:44', '2026-05-03 22:55:58'),
(38, 3, 'Ayung White Water Rafting', 'ayung-white-water-rafting', NULL, 'Elevate your Bali adventure with the ultimate river rafting experience on the Ayung River. This thrilling journey combines adrenaline, breathtaking nature, and pure excitement as you navigate through exhilarating rapids, glide past cascading waterfalls, and immerse yourself in the lush tropical jungle.', '<p>Elevate your Bali adventure with the ultimate river rafting experience on the Ayung River. This thrilling journey combines adrenaline, breathtaking nature, and pure excitement as you navigate through exhilarating rapids, glide past cascading waterfalls, and immerse yourself in the lush tropical jungle.<br><br>Perfect for both beginners and adventure enthusiasts, expert guides ensure a safe and unforgettable ride. Get ready for splashes, laughter, and stunning scenery at every twist and turn of Bali’s most iconic river.</p>', '<p></p>', NULL, NULL, 'experiences/main/9bee4b86-a1ba-421d-904a-112db1277ead.webp', 'Ayung White Water Rafting | Bali River Adventure Experience', 'experiences/cards/14f47f42-52c6-469e-a72f-dd9dcb481f09.webp', 'Ayung White Water Rafting | Bali River Adventure Experience', 0, 1, 21, 'Ayung White Water Rafting | Bali River Adventure Experience', 'Experience an exhilarating white water rafting adventure on one of Bali’s most iconic rivers. Navigate thrilling rapids, pass waterfalls, and immerse yourself in lush tropical.', '2025-04-11 10:54:28', '2026-07-25 21:22:07'),
(39, 3, 'ATV Adventure', 'atv-adventure', NULL, 'Embark on an exhilarating off-road ATV journey through Bali’s lush jungles, picturesque rice fields, and challenging muddy trails.', '<p>Embark on an exhilarating off-road ATV journey through Bali’s lush jungles, picturesque rice fields, and challenging muddy trails. Designed for all skill levels, this guided adventure includes a comprehensive safety briefing before you navigate rivers, rugged terrains, and breathtaking landscapes. Prepare for an unforgettable ride filled with adventure and natural beauty.</p>', '<p></p>', NULL, NULL, 'experiences/main/220b6fb1-d202-40a7-8363-896957c89391.webp', 'ATV Adventure in Bali | Off-Road Jungle & Rice Field Ride', 'experiences/cards/5ba42cac-fd20-4ffa-ad77-5af06b8a2561.webp', 'ATV Adventure in Bali | Off-Road Jungle & Rice Field Ride', 0, 1, 22, 'ATV Adventure in Bali | Off-Road Jungle & Rice Field Ride', 'Experience an exhilarating ATV adventure through Bali’s lush jungles, scenic rice fields, and muddy off-road trails. A guided ride combining adrenaline, nature, and unforgettable.', '2025-04-11 10:55:25', '2026-07-25 21:22:15'),
(40, 3, 'Land Rover Jeep Sunrise Tour at Mount Batur', 'land-rover-jeep-sunrise-tour-at-mount-batur', NULL, 'Experience the ultimate Land Rover Jeep adventure, traversing Bali’s rugged terrain on an unforgettable journey to witness the breathtaking sunrise over Mount Batur, Kintamani. This is more than just a sunrise tour—it’s a premier off-road expedition into the heart of nature.', '<p>Experience the ultimate Land Rover Jeep adventure, traversing Bali’s rugged terrain on an unforgettable journey to witness the breathtaking sunrise over Mount Batur, Kintamani. This is more than just a sunrise tour—it’s a premier off-road expedition into the heart of nature.</p>', '<p></p>', NULL, NULL, 'experiences/main/4219406f-b5bc-4045-bd82-85b67e7de61f.webp', 'Land Rover Jeep Sunrise Tour at Mount Batur | Off-Road Adventure', 'experiences/cards/b2bada05-e03b-40eb-b7c5-8c0576c7305d.webp', 'Land Rover Jeep Sunrise Tour at Mount Batur | Off-Road Adventure', 0, 1, 23, 'Land Rover Jeep Sunrise Tour at Mount Batur | Off-Road Adventure', 'Discover Mount Batur at sunrise on a thrilling Land Rover Jeep adventure. Traverse rugged volcanic terrain and enjoy panoramic Kintamani views on an unforgettable off-road journey.', '2025-04-11 11:15:00', '2026-05-03 22:55:58'),
(41, 3, 'VW Safari Adventure', 'vw-safari-adventure', NULL, 'Embark on a thrilling open-air adventure in a vintage VW Safari to the breathtaking landscapes of Mount Batur, Kintamani.', '<p>Embark on a thrilling open-air adventure in a vintage VW Safari to the breathtaking landscapes of Mount Batur, Kintamani. Explore the sacred Tirta Empul Holy Spring Temple, take in panoramic views of the majestic Mount Batur, stroll through a lush coffee plantation, and marvel at the iconic Tegallalang Rice Terraces. Immerse yourself in Bali’s natural beauty and cultural heritage on this unforgettable journey.</p>', '<p></p>', NULL, NULL, 'experiences/main/45d90d81-012e-4c72-8ee0-eb64f4a2efba.webp', 'VW Safari Adventure | Open-Air Journey Around Mount Batur', 'experiences/cards/ad1a42c5-abf0-4942-a752-e1fee9d9f361.webp', 'VW Safari Adventure | Open-Air Journey Around Mount Batur', 0, 1, 24, 'VW Safari Adventure | Open-Air Journey Around Mount Batur', 'Explore Bali in a classic open-air VW safari, discovering Mount Batur, scenic Kintamani views, sacred springs, coffee plantations, and iconic rice terraces on one unforgettable.', '2025-04-11 11:15:39', '2026-07-25 21:22:42'),
(42, 3, 'Mount Batur Sunrise Trekking Adventure', 'mount-batur-sunrise-trekking-adventure', NULL, 'Step into the stillness of the night and begin an unforgettable journey to the summit of Mount Batur. Guided by the glow of the stars, each step brings you closer to an awe-inspiring reward. ', '<p>Step into the stillness of the night and begin an unforgettable journey to the summit of Mount Batur. Guided by the glow of the stars, each step brings you closer to an awe-inspiring reward. As dawn breaks, watch in wonder as the sky transforms into a masterpiece of fiery hues, painting the landscape below. A breathtaking sunrise, crisp mountain air, and the thrill of adventure.</p>', '<p></p>', NULL, NULL, 'experiences/main/6e161eb5-8630-4020-82ca-6c33e3bca878.webp', 'Mount Batur Sunrise Trekking Adventure | Iconic Bali Volcano Hike', 'experiences/cards/cb40c61e-aa62-43a4-9261-3d5af308b91c.webp', 'Mount Batur Sunrise Trekking Adventure | Iconic Bali Volcano Hike', 0, 1, 25, 'Mount Batur Sunrise Trekking Adventure | Iconic Bali Volcano Hike', 'Embark on a Mount Batur sunrise trekking adventure and witness a breathtaking dawn from the summit. Experience crisp mountain air, dramatic volcanic views, and an unforgettable.', '2025-04-11 11:16:30', '2026-05-03 22:55:58'),
(43, 5, 'The Floating Boat Experience', 'the-floating-boat-experience', NULL, 'Indulge in a moment of pure tranquility aboard our handcrafted floating boat, gently drifting atop the iconic main pool at Nandini Jungle by Hanging Gardens. ', '<p>Indulge in a moment of pure tranquility aboard our handcrafted floating boat, gently drifting atop the iconic main pool at Nandini Jungle by Hanging Gardens. Surrounded by the emerald canopy of the Ubud rainforest, this exclusive experience invites you to unwind in timeless elegance, whether basking in the golden hour or enjoying a bespoke floating breakfast beneath the open sky. Seamlessly blending natural beauty with opulent comfort, this is where jungle serenity meets unparalleled sophistication.</p>', '<p></p>', NULL, NULL, 'experiences/main/floating-boat-dining-experience-nandini-jungle-bali.webp', 'Couple enjoying a floating boat dining experience in a jungle pool at Nandini Jungle by Hanging Gardens.', 'experiences/cards/floating-boat-dining-experience-nandini-jungle-bali.webp', 'Couple enjoying a floating boat dining experience in a jungle pool at Nandini Jungle by Hanging Gardens.', 0, 1, 15, 'The Floating Boat Experience | Luxury Pool Dining in Ubud', 'Indulge in a serene floating boat experience, drifting gently across a tranquil jungle pool. Enjoy bespoke dining in an elegant setting surrounded by Ubud’s lush rainforest.', '2025-05-28 08:57:31', '2026-07-13 17:17:55'),
(45, 2, 'From Ride to Relief', 'from-ride-to-relief', 'SUNRISE CYCLING WITH RELAXING FOOT MASSAGE', 'Sunrise cycling with relaxing foot massage. A graceful journey of motion and calm at Payangan, guided through the nature—featuring a 60-minute cycling experience with guide and a 15-minute soothing foot massage.', '<p>A graceful journey of motion and calm at Payangan, guided through the nature—featuring a 60-minute cycling experience with guide and a 15-minute soothing foot massage.</p>', '<p></p>', NULL, NULL, 'experiences/main/5071e8c8-4859-4cba-b8d6-07a14aab9342.webp', 'Sunrise Cycling & Foot Massage in Payangan | Nandini Jungle Bali', 'experiences/cards/f1d7c301-b2f1-42da-b48d-25cb69c33f02.webp', 'Sunrise Cycling & Foot Massage in Payangan | Nandini Jungle Bali', 0, 1, 27, 'Sunrise Cycling & Foot Massage in Payangan | Nandini Jungle Bali', 'Experience a 60-minute guided sunrise cycling tour in Payangan followed by a 15-minute relaxing foot massage. A perfect blend of nature, movement, and wellness at Nandini Jungle.', '2026-02-26 08:57:27', '2026-05-03 23:04:39');

