(1, 'Holy River', 'holy-river', NULL, NULL, '<p></p>', NULL, NULL, 1, 6, '2026-04-30 23:56:31', '2026-05-03 21:05:47'),
(2, 'Curated Experience Packages', 'curated-experience-packages', NULL, NULL, '<p>Explore thoughtfully curated experiences that bring together Nandini’s most memorable activities, from romance and wellness to adventure and authentic Balinese moments.</p>', 'experience-categories/8a08b1e7-4058-470c-a338-a03f8b57b2aa.webp', 'Curated Experience Packages', 1, 5, '2026-05-03 20:03:43', '2026-07-07 00:20:11'),
(3, 'Ubud Jungle Adventures', 'ubud-jungle-adventures', NULL, NULL, '<p>Discover Bali’s natural beauty through outdoor adventures, cultural encounters, and scenic jungle experiences designed to enrich your stay at Nandini.</p>', 'experience-categories/0b764bc6-95d2-4fa7-bd1b-58f4eba5eb97.webp', 'Ubud Jungle Adventures', 1, 4, '2026-05-03 20:03:58', '2026-07-07 00:20:03'),
(4, 'Jungle Wellness & Spa Rituals', 'jungle-wellness-spa-rituals', NULL, NULL, '<p>Restore balance with calming spa and wellness rituals inspired by Bali&#039;s rainforest. Designed to relax the body, refresh the mind, and reconnect you with nature, each treatment brings a deeper sense of peace to your jungle retreat.</p>', 'experience-categories/0f670856-8d39-49a1-97ff-96a88f13e2e2.webp', 'Jungle Wellness & Spa Rituals', 1, 3, '2026-05-03 20:04:10', '2026-07-07 00:18:59'),
(5, 'Signature Dining Experiences', 'signature-dining-experiences', NULL, NULL, '<p>Enjoy memorable dining moments surrounded by tropical scenery, refined flavors, and warm Balinese hospitality. Each dining experience at Nandini Jungle by Hanging Gardens is created to make your stay feel personal, memorable, and connected to the beauty of Ubud.</p>', 'experience-categories/cff9f2ff-71e8-42c8-bcf4-a95c32488c53.webp', 'Signature Dining Experiences', 1, 2, '2026-05-03 20:04:20', '2026-07-07 00:18:43'),
(6, 'Jungle Romance', 'jungle-romance', NULL, NULL, '<p>Celebrate intimate moments with a candlelit setting surrounded by tropical greenery and the soft atmosphere of Bali&#039;s jungle. Created for couples, this romantic jungle experience is designed for proposals, anniversaries, honeymoons, and meaningful celebrations in nature.</p>', 'experience-categories/c5e0deb3-cd14-4488-ba06-31efb046d0fd.webp', 'Jungle Romance', 1, 1, '2026-05-03 20:04:29', '2026-07-07 00:18:27');

