INSERT INTO `honeymoons` (`id`, `title`, `slug`, `subtitle`, `excerpt`, `description`, `hero_image`, `hero_image_alt`, `hero_mobile_image`, `hero_mobile_image_alt`, `card_image`, `card_image_alt`, `valid_start_date`, `valid_end_date`, `booking_checkin_date`, `booking_nights`, `booking_rooms`, `booking_adults`, `booking_rate_code`, `booking_bkcode`, `booking_url_override`, `button_label`, `button_url`, `is_featured`, `is_active`, `meta_title`, `meta_description`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Honeymoon Packages - 4 Days 3 Nights', 'honeymoon-packages-4-days-3-nights', NULL, NULL, '<p>Discover an oasis of love at Nandini Jungle by Hanging Gardens, acclaimed as Bali&#039;s best honeymoon retreat, where an exceptionally romantic ambiance awaits within the secluded haven of Bali&#039;s rainforest.<br><br>Immerse yourself in a 3-night stay in our Jungle View Royal Suite or Garden View Royal Suite and lavish your beloved with irresistible romantic experiences enveloped by the tranquil beauty of Ubud&#039;s lush jungle.<br><br><strong>Your package includes:</strong></p><ul><li><p>Flower decoration &amp; cake upon arrival</p></li><li><p>One-time Moonlit Jungle Romance special dinner</p></li><li><p>One-time 120&#039; Riverside Sanctuary Spa Package</p></li><li><p>One-time Luxe High Tea</p></li><li><p>Daily à la carte &amp; mezze breakfast for 2 persons</p></li><li><p>Daily complimentary shuttle to Ubud downtown based on schedule</p></li><li><p>Daily Balinese afternoon tea from 3 – 5 PM at the Restaurant</p></li><li><p>Daily Village Tours based on Resort schedule</p></li><li><p>Free Cycling Tour around the village</p></li><li><p>Free Sunset Yoga at Djiwa Shala</p></li><li><p>In room tea &amp; coffee making facilities</p></li><li><p>Healthy welcome drink &amp; chilled towel upon arrival</p></li><li><p>Fresh fruit basket in resorts upon arrival</p></li></ul><p><br>Craft memories of a lifetime amidst the enchanting jungle resort. Reserve your romantic escape now.</p>', 'honeymoons/hero/0fd7b356-02c6-408c-845b-fc4e2dc91603.webp', 'Honeymoon Packages - 4 Days 3 Nights', 'honeymoons/hero-mobile/077556b3-ceff-4a46-a062-24db4106b421.webp', 'Honeymoon Packages - 4 Days 3 Nights', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://nandinijunglebyhanginggardens.reserve-online.net/?checkin=2026-05-27&nights=3&bkcode=romance', 'Book Now', NULL, 0, 1, 'Honeymoon Package in Ubud Bali | Nandini Jungle Resort', 'Celebrate love with a 4 days 3 nights honeymoon package at Nandini Jungle by Hanging Gardens, featuring a romantic dinner, spa treatment, high tea, and jungle suite stay.', 0, '2026-05-27 01:24:39', '2026-05-27 01:35:25');

