(1, 'EARLY SUMMER ESCAPE', 'Special Offer', '<ul><li><p>One-time one-hour free flow cocktails</p></li><li><p>One-time 2-course set menu lunch</p></li><li><p>Daily à la carte &amp; mezze breakfast</p></li><li><p>A 10% savings on spa treatments</p></li><li><p>A 10% savings on food &amp; beverages</p></li></ul>', 'mini-popups/01KSSEM6VNEEFD1V26J5F62FN4.jpg', 'EARLY SUMMER ESCAPE', 'More Details', 'manual', '/offer/early-summer-escape', NULL, 0, 3, '2026-05-29 08:46:45', '2026-05-30 05:05:53'),
(2, 'Why Book Direct With Us?', NULL, '<ul><li><p>Enjoy flexible bookings – no deposit needed</p></li><li><p>Unlock exclusive perks with a minimum stay</p></li><li><p>Indulge in savings on spa treatments &amp; dining</p></li><li><p>Receive a complimentary foot massage</p></li></ul><p><br><em>Terms &amp; conditions apply</em></p>', 'mini-popups/01KSSEQVTAK01VHHRSQM2XG55M.jpg', 'Why Book Direct With Us?', 'Check our offers', 'manual', '/offers', NULL, 0, 2, '2026-05-29 08:48:45', '2026-07-02 17:42:39'),
(3, 'Tropical Chill Getaway', 'Special Offer', '<ul><li><p>Daily two glasses of cocktails</p></li><li><p>One time 2-course set menu lunch for two</p></li><li><p>Daily à la carte &amp; mezze breakfast</p></li><li><p>A 10% savings on spa treatments</p></li><li><p>A 10% savings on food &amp; beverages</p></li></ul>', 'mini-popups/01KSVMB6FZG6WQQVFETRH2DT3E.jpg', 'Tropical Chill Getaway', 'More Details', 'manual', '/offer/tropical-chill-getaway', NULL, 0, 1, '2026-05-30 05:05:10', '2026-07-02 17:42:38'),
(4, 'Become Our Member', 'Join Nandini Inner Circle', '<ul><li><p>Unlock Exclusive Member Rates</p></li><li><p>Earn Points with Every Stay</p></li><li><p>Receive Special Offers First</p></li><li><p>Enjoy Member-Only Privileges</p></li><li><p>Make Every Stay More Rewarding</p></li></ul><p><br>The more you stay, the more benefits you enjoy.</p>', 'mini-popups/join-nandini-inner-circle-jungle-resort.webp', 'Guest walking through lush tropical gardens at Nandini Jungle by Hanging Gardens in Ubud.', 'Sign Up', 'route', NULL, 'membership.index', 1, 4, '2026-07-02 17:41:34', '2026-07-02 17:46:03');

