--
-- Table structure for table `pages`
--

CREATE TABLE `pages` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `page_name` varchar(191) DEFAULT NULL,
  `title` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `subtitle` varchar(191) DEFAULT NULL,
  `excerpt` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `hero_image` varchar(191) DEFAULT NULL,
  `hero_image_alt` varchar(191) DEFAULT NULL,
  `hero_mobile_image` varchar(191) DEFAULT NULL,
  `hero_mobile_image_alt` varchar(191) DEFAULT NULL,
  `meta_title` varchar(191) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `pages`
--

INSERT INTO `pages` (`id`, `page_name`, `title`, `slug`, `subtitle`, `excerpt`, `description`, `hero_image`, `hero_image_alt`, `hero_mobile_image`, `hero_mobile_image_alt`, `meta_title`, `meta_description`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Home Page', 'Nandini Jungle by Hanging Gardens', 'nandini-jungle-by-hanging-gardens', 'A Luxury Jungle Resort in Ubud, Bali', 'A secluded luxury jungle resort in Ubud, Bali surrounded by rainforest, river valley views, private villas, royal suites, spa rituals, romantic dining, and warm Balinese hospitality.', '<p>Escape to Nandini Jungle by Hanging Gardens, a secluded luxury jungle resort in Ubud, Bali surrounded by rainforest, river valley views, and warm Balinese hospitality. Stay in private jungle villas or spacious royal suites, then discover spa rituals, romantic dining, and curated experiences designed for a calm Bali jungle retreat.</p>', 'pages/hero/74e30cb4-6fec-4883-8b57-c474baa71740.webp', 'Luxury jungle resort in Ubud, Bali with rainforest pool at Nandini Jungle by Hanging Gardens.', NULL, NULL, 'Luxury Jungle Resort Bali | Nandini Jungle by Hanging Gardens', 'Stay at Nandini Jungle by Hanging Gardens, a luxury jungle resort in Ubud, Bali with private villas, royal suites, spa, dining, and river valley views.', 1, 1, '2024-04-28 22:32:40', '2026-07-06 23:53:53'),
(2, 'Offers Page', 'Limited Offers', 'limited-offers', NULL, NULL, '<p>Make the most of your Ubud wellness retreat with our exclusive offers at Nandini Jungle by Hanging Gardens. Book directly with us to enjoy our Best Rate Guarantee and secure your stay in just one easy step. Whether you&#039;re dreaming of a luxury escape, a wellness retreat, or a once-in-a-lifetime jungle-to-beach adventure, our handpicked deals are designed to elevate your experience.<br><br>Explore our current offers below and find the perfect package to reconnect with nature, revive your spirit, <br>and get the most out of your stay in Bali.</p>', 'pages/hero/db7f4bc2-1f15-4eb5-b4d9-23cac90c9743.webp', 'Limited Offers in Ubud, Bali | Nandini Jungle', NULL, NULL, 'Limited Offers in Ubud, Bali | Nandini Jungle', 'Discover limited offers at Nandini Jungle by Hanging Gardens, from luxury escapes to wellness retreats and exclusive Bali stay packages.', 1, 3, '2024-04-29 06:14:43', '2026-04-29 01:05:52'),
(3, 'Accommodations Page', 'The Royal Suites & Jungle Villas', 'the-royal-suites-jungle-villas', NULL, 'Nandini Jungle by Hanging Gardens features 18 beautiful jungle villas and 16 luxury royal suites inspired by Balinese architecture and coupled with the notion of luxurious comfort.', '<p>Nandini Jungle by Hanging Gardens features 18 beautiful jungle villas and 16 luxury royal suites inspired by Balinese architecture and coupled with the notion of luxurious comfort. With our assortment of accommodation arrangements, you may experience the real luxury of the Ubud forest.</p>', 'pages/hero/86b1d694-5fc7-49d6-a9a9-baccc0b83662.webp', 'The Royal Suites & Jungle Villas in Ubud | Nandini Jungle', 'pages/hero-mobile/3505e750-8919-47dd-930a-86043245382d.webp', 'The Royal Suites & Jungle Villas in Ubud | Nandini Jungle', 'The Royal Suites & Jungle Villas in Ubud | Nandini Jungle', 'Stay in elegant jungle villas and royal suites in Ubud, inspired by Balinese design and surrounded by the natural beauty of the forest.', 1, 5, '2024-04-29 06:19:50', '2026-05-04 23:41:40'),
(4, 'Dining Page', 'A Culinary Journey in the Heart of the Jungle', 'a-culinary-journey-in-the-heart-of-the-jungle', NULL, NULL, '<p>Experience unforgettable dining at Nandini Jungle by Hanging Gardens, where cuisine meets nature in perfect harmony. Savor exquisite dishes crafted with fresh, local ingredients, served in stunning jungle settings. <br><br>Combining Asian and Western cuisine with Balinese ingredients with top-notch service. Enjoy a romantic dinner or savor the delicious À la carte &amp; Mezze Breakfast and Healthy food amidst tranquil surroundings with a maximum restaurant capacity.</p>', 'pages/hero/d3cdc84f-a16d-4dd1-b1f8-c7cb680d5c8a.webp', 'Jungle Dining in Ubud, Bali | Nandini Jungle', NULL, NULL, 'Jungle Dining in Ubud, Bali | Nandini Jungle', 'Experience jungle dining in Ubud at Nandini Jungle by Hanging Gardens, with Asian, Western, and Balinese flavors served in a serene rainforest setting.', 1, 11, '2024-04-29 06:24:38', '2026-04-29 01:05:52'),
(5, 'Experiences Page', 'Unique Experiences', 'unique-experiences', NULL, NULL, '<p>Set in gorgeous Balinese jungles and sitting along the Ayung river, Nandini Jungle by Hanging Gardens promises to create exceptional experiences that you will never forget</p>', 'pages/hero/d3c498e1-88e2-40ea-8c57-2a623a2f32fd.webp', 'Unique Experiences', 'pages/hero-mobile/3cf83304-eaa8-4ed6-b785-e473bc25fffb.webp', 'Unique Experiences', 'Unique Experiences in Ubud Bali | Nandini Jungle', 'Discover unique Balinese jungle experiences at Nandini Jungle by Hanging Gardens, from riverside rituals to cultural and nature-inspired activities.', 1, 4, '2024-04-29 06:27:52', '2026-05-03 19:57:09'),
(6, 'Spa Page', 'Spa & Wellness', 'spa-wellness', NULL, NULL, '<p>Immerse yourself in a transformative experience at our Wellness Retreat in Bali, where tranquillity meets holistic healing. Nestled in the lush jungle landscapes of Ubud, surrounded by rice terraces and vibrant jungle, our sanctuary is designed to nourish your body, mind, and soul.</p>', 'pages/hero/fb4a52d4-35a1-4c29-804d-100e00dd6b89.webp', 'Spa & Wellness', 'pages/hero-mobile/62373376-3d2e-4974-aca3-f369f10112f0.webp', 'Spa & Wellness', 'Spa & Wellness', 'Immerse yourself in a transformative experience at our Wellness Retreat in Bali, where tranquillity meets holistic healing. ', 1, 12, '2024-04-29 06:32:37', '2026-05-27 03:31:28'),
(7, 'Honeymoon Page', 'Honeymoon Bali Packages', 'honeymoon-bali-packages', NULL, NULL, '<p>Discover Bali’s most magical setting for your “happily ever after”, with our ultimate jungle resort as the perfect host for your honeymoon. Make lasting memories as you uncover the beauty of Bali, celebrating your tropical jungle island honeymoon. Delight in playful days spent in the most magical setting, and toast our vivid sunsets with romantic dining experiences tailored just for you.</p>', 'pages/hero/1c101d0a-da5a-4f26-9ab6-745ce9820373.webp', 'Honeymoon Bali Packages', 'pages/hero-mobile/c388cc6c-4a14-4658-82c4-a7a5490ef8d1.webp', 'Honeymoon Bali Packages', 'Best Ubud Resort for Honeymoon | Nandini Jungle by Hanging Gardens', 'Experience the ultimate honeymoon in Bali at Nandini Jungle by Hanging Gardens. Discover the beauty of the tropical jungle and create lasting memories.', 1, 10, '2024-04-29 06:34:52', '2026-05-26 08:41:22'),
(8, 'Wedding Page', 'Wedding', 'wedding', NULL, NULL, '<p>Your wedding day is a celebration of love, a moment when two souls unite—and the setting should be just as extraordinary as the occasion. Nestled deep within the lush Ubud jungle, Nandini Bali is a dreamlike destination where nature and elegance come together in perfect harmony.<br><br>Imagine exchanging vows surrounded by emerald forest, flowing water, and panoramic valley views—a backdrop that feels as timeless as your love. Whether you&#039;re planning an intimate ceremony or a grand celebration, Nandini offers a magical canvas for your special day.<br><br>From Bali inspired rituals to classic Western ceremonies or our own Signature Enchanting Wedding, each celebration is thoughtfully tailored to reflect your unique story. Let our team take care of every detail, so you can focus on what truly matters—making unforgettable memories with those you love.</p>', 'pages/hero/7dd7335d-e124-42ef-b398-c07e64b7c8f2.webp', 'Wedding Venue in Ubud Bali | Nandini Jungle', 'pages/hero-mobile/30ddae77-6bcc-4b78-bfad-f7a1e42360b1.webp', 'Wedding Venue in Ubud Bali | Nandini Jungle', 'Wedding Venue in Ubud Bali | Nandini Jungle', 'Celebrate your wedding at Nandini Jungle by Hanging Gardens, a romantic Ubud jungle resort with forest views, flowing water, and elegant ceremony settings.', 1, 13, '2024-04-29 06:38:22', '2026-05-27 07:13:28'),
(23, 'The Little Things Page', 'It\'s in The Little Things', 'its-in-the-little-things', NULL, 'At Nandini, we believe true luxury is not loud, it is thoughtful. It is the softness of a perfectly pressed sheet and the comforting weight of a towel that truly wraps around you. All of the details are included at no extra cost, because we want your time with us to feel effortless, generous, and unforgettable. It is a quiet kind of care, present in every corner of your stay. Here is just a glimpse of how we care for the little things, just for you.', '<p>At Nandini, we believe true luxury is not loud, it is thoughtful. It is the softness of a perfectly pressed sheet and the comforting weight of a towel that truly wraps around you. All of the details are included at no extra cost, because we want your time with us to feel effortless, generous, and unforgettable. It is a quiet kind of care, present in every corner of your stay.<br><br>Here is just a glimpse of how we care for the little things, just for you.</p>', 'pages/hero/bf71251e-d93d-4804-85dd-7ecbeaaf8720.webp', 'It\'s in The Little Things', 'pages/hero-mobile/be088bd4-4adb-4647-a83b-f398d50be181.webp', 'It\'s in The Little Things', 'It\'s in The Little Things', 'At Nandini, we believe true luxury is not loud, it is thoughtful. It is the softness of a perfectly pressed sheet and the comforting weight of a towel that truly wraps around you.', 1, 9, '2025-07-15 08:24:23', '2026-05-26 08:06:55'),
(9, 'Awards Page', 'Awards', 'awards', NULL, NULL, '<p>We are honored that our philosophy of service excellence is recognized by many leading publications of the travel, hospitality and lifestyle sectors both in the Indonesia and Internationally.</p>', 'pages/hero/8a092584-ad98-4898-ae1c-5523497309b6.webp', 'Awards & Recognition | Nandini Jungle by Hanging Gardens', 'pages/hero-mobile/5fab1380-4f4e-40a3-acb9-0a6767e99dc5.webp', 'Awards & Recognition | Nandini Jungle by Hanging Gardens', 'Awards & Recognition | Nandini Jungle by Hanging Gardens', 'Explore the awards and recognition received by Nandini Jungle by Hanging Gardens from leading travel, hospitality, and lifestyle publications in Indonesia and worldwide.', 1, 16, '2024-04-29 06:50:48', '2026-05-27 08:26:29'),
(10, 'Gallery Page', 'Gallery', 'gallery', NULL, NULL, '<p>Welcome to the gallery of our luxury jungle hotel, where every image transports you to a world of serene beauty and indulgent comfort. This collection showcases the stunning architecture and lush surroundings that define our unique retreat, nestled within the heart of nature.</p>', 'pages/hero/723430ff-4a3a-411f-a570-7e918b19ac70.webp', 'Gallery | Nandini Jungle by Hanging Gardens', 'pages/hero-mobile/a61954f4-d467-4a89-bb7e-eae3499ad37e.webp', 'Gallery | Nandini Jungle by Hanging Gardens', 'Gallery | Nandini Jungle by Hanging Gardens', 'Explore the gallery of Nandini Jungle by Hanging Gardens, showcasing luxury jungle suites, villas, pools, architecture, and serene natural surroundings in Ubud.', 1, 17, '2024-04-29 06:53:19', '2026-05-29 01:58:34'),
(11, 'Press Page', 'Press & Media Recognition', 'press-media-recognition', NULL, NULL, '<p>We are honored that our Ubud luxury resort with private pool was recognized by various press, media channels and leading publications of travel, hospitality and lifestyle sectors, both in Indonesia and internationally. Explore the latest news about our outstanding destination</p>', NULL, NULL, NULL, NULL, 'Press and Media Recognition', 'We are honored that our Ubud luxury resort with private pool was recognized by various press, media channels and leading publications of travel', 0, 22, '2024-04-29 06:54:31', '2026-07-06 19:20:05'),
(12, 'Contact Page', 'Get in Touch', 'get-in-touch', NULL, NULL, '<p>Our Reservations team will assist you with your travel planning, operating 24/7 to be at your service and plan your ultimate Nandini Jungle by Hanging Gardens experience.</p>', 'pages/hero/1357c351-7526-4eff-be79-28247798a7c4.webp', 'Contact Nandini Jungle by Hanging Gardens | Ubud Bali', 'pages/hero-mobile/18bcfb02-152b-4bca-a0c7-95952d4cd351.webp', 'Contact Nandini Jungle by Hanging Gardens | Ubud Bali', 'Contact Nandini Jungle by Hanging Gardens | Ubud Bali', 'Get in touch with Nandini Jungle by Hanging Gardens. Our reservations team is available 24/7 to assist with travel planning, bookings, and your Ubud jungle resort stay.', 1, 18, '2024-04-29 06:55:52', '2026-05-29 02:16:41'),
(36, 'Membership - Sign in Page', 'Sign In', 'sign-in', 'Nandini Inner Circle', NULL, '<p>Access your membership dashboard, view your rewards, and continue your journey with Nandini Inner Circle.</p>', 'pages/hero/d0be0980-1995-4575-ab31-79e3081027e6.webp', 'Sign In | Nandini Inner Circle Membership', 'pages/hero-mobile/f3773d29-2a50-4ba9-9406-d2af57991a1f.webp', 'Sign In | Nandini Inner Circle Membership', 'Sign In | Nandini Inner Circle Membership', 'Access your Nandini Inner Circle membership dashboard. Log in to view your exclusive rewards, track your benefits, and continue your journey.', 1, 33, '2026-05-18 03:05:05', '2026-05-18 03:26:21'),
(37, 'Membership - Dashboard page', 'Member Detail', 'member-detail', NULL, NULL, '<p>Access your exclusive member privileges.</p>', 'pages/hero/2b9246c8-27fb-4636-873b-b77f07e4c76c.webp', 'Dashboard | Nandini Inner Circle', 'pages/hero-mobile/5df8ba7a-ceb8-4069-9619-0eadf5d97ff9.webp', 'Dashboard | Nandini Inner Circle', 'Dashboard | Nandini Inner Circle', 'Access your exclusive member privileges, view your profile details, and manage your account settings directly from your Nandini Inner Circle dashboard.', 1, 34, '2026-05-18 03:25:54', '2026-05-18 03:26:59'),
(38, 'Membership - Register', 'Register', 'register', NULL, NULL, '<p>Create your membership account, access your rewards, and enjoy exclusive benefits with Nandini Inner Circle.</p>', 'pages/hero/8990cc93-86a8-4dde-be4f-19aef7351522.webp', NULL, 'pages/hero-mobile/a91b179c-d7ea-45ea-ac76-9126b856e366.webp', NULL, 'Register | Nandini Inner Circle Membership', 'Create your Nandini Inner Circle account to access rewards, exclusive benefits, and personalized offers at Nandini Jungle by Hanging Gardens.', 1, 35, '2026-05-20 02:57:50', '2026-05-20 02:57:50'),
(39, 'Membership - Benefit', 'Member-Only Privilege', 'member-only-privilege', NULL, NULL, '<ul><li><p>Exclusive member-only rates <strong>(not combinable with public promotions)</strong>.</p></li><li><p>Early access to seasonal offers and festive packages.</p></li><li><p>Invitation to exclusive experiences for <strong>Gold &amp; Platinum</strong> members, such as:</p><ul><li><p>Private yoga or wellness sessions.</p></li><li><p>Guided jungle walks.</p></li><li><p>Cultural storytelling evenings.</p></li></ul></li></ul>', 'pages/hero/f04e87bb-f1a6-4567-a65c-86566171e2ef.webp', 'Member-Only Privilege', 'pages/hero-mobile/b4a3c4ac-eb47-4f22-bcb1-ec3ac7601f7c.webp', 'Member-Only Privilege', 'Nandini Rewards Benefits | Member-Only Privileges in Ubud', 'Discover Nandini Rewards member benefits, including exclusive rates, early access to seasonal offers, and special experiences for Gold and Platinum members.', 1, 36, '2026-05-25 05:25:20', '2026-05-25 05:25:20'),
(14, 'Privacy Policy Page', 'Privacy Policy', 'privacy-policy', NULL, NULL, '<h3><strong>1. Introduction</strong></h3><p>At Nandini Jungle by Hanging Gardens, we highly value your privacy and are committed to protecting your personal information. This Privacy Policy outlines how we collect, use, store, and protect the personal data of our current and potential customers.<br><br></p><h3><strong>2. Information We Collect</strong></h3><p>We may collect and process the following types of personal information:</p><ul><li><p><strong>Contact Information:</strong> Name, email address, phone number, and mailing address.</p></li><li><p><strong>Demographic Information:</strong> Age, gender, and other demographic details.</p></li><li><p><strong>Transaction Information:</strong> Details about purchases or services you have availed.</p></li><li><p><strong>Technical Information:</strong> IP address, browser type, and usage data when you visit our website.</p></li><li><p><strong>Marketing Preferences:</strong> Information about your preferences for receiving marketing communications.</p></li></ul><p><br></p><h3><strong>3. How We Use Your Information</strong></h3><p>We use your personal information for the following purposes:</p><ul><li><p><strong>Providing Services:</strong> To process your orders and provide the products or services you request.</p></li><li><p><strong>Customer Support:</strong> To respond to your inquiries and provide customer service.</p></li><li><p><strong>Marketing Communications:</strong> To send you promotional materials and updates, if you have opted in to receive them.</p></li><li><p><strong>Improving Our Services:</strong> To analyze and improve our products, services, and website functionality.</p></li><li><p><strong>Legal Obligations:</strong> To comply with legal requirements and protect our legal rights.</p></li></ul><p><br></p><h3><strong>4. Information Sharing and Disclosure</strong></h3><p>We do not sell, trade, or rent your personal information to third parties. However, we may share your information in the following circumstances:</p><ul><li><p><strong>Service Providers:</strong> With third-party service providers who assist us in operating our business, such as payment processors and marketing agencies.</p></li><li><p><strong>Legal Requirements:</strong> If required by law or in response to legal proceedings.</p></li><li><p><strong>Business Transfers:</strong> In the event of a merger, acquisition, or sale of all or a portion of our assets.</p></li></ul><p><br></p><h3><strong>5. Data Security</strong></h3><p>We implement appropriate technical and organizational measures to protect your personal information against unauthorized access, alteration, disclosure, or destruction. However, no data transmission over the internet or electronic storage is completely secure, so we cannot guarantee absolute security.</p><p><br></p><h3><strong>6. Your Rights</strong></h3><p>You have the right to:</p><ul><li><p><strong>Access Your Information:</strong> Request a copy of the personal information we hold about you.</p></li><li><p><strong>Correct Your Information:</strong> Request corrections to any inaccurate or incomplete personal data.</p></li><li><p><strong>Delete Your Information:</strong> Request the deletion of your personal information, subject to certain legal exceptions.</p></li><li><p><strong>Object to Processing:</strong> Object to the processing of your personal data for direct marketing purposes.</p></li><li><p><strong>Withdraw Consent:</strong> Withdraw your consent for us to process your personal data at any time.</p></li></ul><p><br></p><h3><strong>7. Changes to This Privacy Policy</strong></h3><p>We may update this Privacy Policy from time to time. Any changes will be posted on this page, and we will notify you of significant changes by email or through our website.</p><p><br></p><h3><strong>8. Contact Us</strong></h3><p>If you have any questions or concerns about this Privacy Policy or our data practices, please contact us at:<br>Nandini Jungle by Hanging Gardens<br>Desa Buahan Payangan, Gianyar, Bali 80571, Indonesia<br>Tel. +62-812 3687 1170<br>E. <a href=\"mailto:reservation@nandinibali.com\"><u>reservation@nandinibali.com</u></a><br>W. <a href=\"https://hanginggardensofbali.com/\"><u>nandinibali.com</u></a></p><p><br></p>', NULL, NULL, NULL, NULL, 'Policy & Legal', 'At Nandini Jungle by Hanging Gardens, we highly value your privacy and are committed to protecting your personal information.', 0, 23, '2024-04-29 06:59:30', '2026-07-06 19:20:04'),
(24, 'Holy River Page', 'Ubud Healing Retreat: Discover Bali\'s Sacred Wellness Sanctuary', 'ubud-healing-retreat-discover-balis-sacred-wellness-sanctuary', NULL, 'In the secluded heart of Ubud\'s jungle lies Nandini, a sanctuary of ancient spirits and profound healing. This Ubud healing and wellness retreat whispers of transformations, where the spirit of Bali flows through every leaf, rock, and breeze. Here, by the sacred Ayung River—a river once known only to locals for its potent spiritual energy—you\'ll experience a relaxing retreat like no other. This Bali Healing Resort is cradled by the surrounding gorge and jungle canopies, channeling the island\'s deep-rooted spiritual heritage.', '<p>In the secluded heart of Ubud&#039;s jungle lies Nandini, a sanctuary of ancient spirits and profound healing. This Ubud healing and wellness retreat whispers of transformations, where the spirit of Bali flows through every leaf, rock, and breeze. Here, by the sacred Ayung River—a river once known only to locals for its potent spiritual energy—you&#039;ll experience a relaxing retreat like no other. This Bali Healing Resort is cradled by the surrounding gorge and jungle canopies, channeling the island&#039;s deep-rooted spiritual heritage.</p>', 'pages/hero/91bb7bbd-6884-441e-bcb7-f64f1fab7ab6.webp', NULL, NULL, NULL, 'Ubud Healing Retreat | Bali Wellness Sanctuary at Nandini', 'Discover Nandini, a secluded Ubud healing retreat by the sacred Ayung River, where Bali’s jungle, wellness, and spiritual energy create a deeply relaxing escape.', 1, 2, '2025-07-15 10:38:21', '2026-04-30 18:48:46'),
(20, 'Villas Page', 'Jungle Villas', 'jungle-villas', NULL, 'Indulge in the ultimate luxury in our exquisite villas, where elegance meets privacy. Each villa is a private oasis, featuring spacious living areas, bespoke furnishings, and breathtaking views.', '<p>Indulge in the ultimate luxury in our exquisite villas, where elegance meets privacy. Each villa is a private oasis, featuring spacious living areas, bespoke furnishings, and breathtaking views. Enjoy your secluded outdoor sanctuary, complete with lavish amenities and personalized service designed for your comfort. Experience a serene escape that redefines opulence—your exclusive haven awaits.</p>', 'pages/hero/c2f90608-9e89-48a7-ba81-a15c4937ace0.webp', 'Jungle Villas in Ubud Bali | Nandini Jungle by Hanging Gardens', 'pages/hero-mobile/63ae593d-833d-4cea-92a8-a0a8e0400180.webp', 'Jungle Villas in Ubud Bali | Nandini Jungle by Hanging Gardens', 'Jungle Villas in Ubud Bali | Nandini Jungle by Hanging Gardens', 'Discover Jungle Villas in Ubud Bali at Nandini Jungle by Hanging Gardens, offering private luxury stays with spacious living areas, elegant design, and jungle views.', 1, 6, '2024-09-26 15:38:10', '2026-05-05 18:55:22'),
(21, 'Suites Page', 'The Royal Suites', 'the-royal-suites', NULL, 'Experience refined luxury in The Royal Suites at Nandini Jungle by Hanging Gardens, where elegant design, generous living spaces, and tranquil jungle views create a private sanctuary in Ubud.', '<p>Experience refined luxury in The Royal Suites at Nandini Jungle by Hanging Gardens, where elegant design, generous living spaces, and tranquil jungle views create a private sanctuary in Ubud. Thoughtfully designed for comfort and relaxation, each suite offers a graceful balance of timeless style, modern amenities, and warm Balinese hospitality. Whether for a romantic escape, special celebration, or peaceful retreat, The Royal Suites invite you to unwind in an atmosphere of quiet sophistication.</p>', 'pages/hero/927cc5f5-2192-4a70-ad06-b2ad7cdbdba7.webp', 'The Royal Suites in Ubud Bali | Nandini Jungle by Hanging Gardens', 'pages/hero-mobile/ae5c1696-945f-457c-9a11-9ea49c080721.webp', 'The Royal Suites in Ubud Bali | Nandini Jungle by Hanging Gardens', 'The Royal Suites in Ubud Bali | Nandini Jungle by Hanging Gardens', 'Discover The Royal Suites in Ubud Bali at Nandini Jungle by Hanging Gardens, offering elegant luxury suites with spacious living areas and serene jungle views.', 1, 7, '2024-09-26 15:43:36', '2026-05-05 18:59:56'),
(15, 'Blog Page', 'Blog & News', 'blog-news', NULL, NULL, '<p>Immerse yourself in the heart of Bali with stories from Nandini Jungle by Hanging Gardens. Our blog &amp; news brings you the latest updates, travel inspiration, wellness tips, cultural insights, and behind-the-scenes moments from our jungle sanctuary. Whether you&#039;re dreaming of your next escape or reminiscing about your stay, discover the beauty, tranquility, and soul of our lush rainforest retreat through every post.</p>', 'pages/hero/436be228-eb12-49d8-862f-87ca2ca27c9a.webp', 'Blog & News', 'pages/hero-mobile/be894f96-9bc4-4856-8042-85bf433b84ee.webp', 'Blog & News', 'Blog & News | Nandini Jungle by Hanging Gardens Bali', 'Read the latest blog and news from Nandini Jungle by Hanging Gardens, featuring Bali travel inspiration, wellness tips, cultural insights, and resort updates.', 1, 15, '2024-04-29 07:00:51', '2026-05-27 07:58:02'),
(16, 'Careers', 'Careers', 'careers', NULL, NULL, '<p>A unique combination of world-class talent, unmatched design, and access to locations, cultures, and experiences few people have access to enables us to achieve our ambitions. Our team of hundreds of our employees is always looking for passionate individuals to join our growing team.</p>', NULL, NULL, NULL, NULL, 'Careers', 'Our team of hundreds of our employees is always looking for passionate individuals to join our growing team.', 0, 21, '2024-04-29 07:02:08', '2026-07-06 19:20:06'),
(17, 'Sustainability Page', 'Sustainability', 'sustainability', NULL, NULL, '<h2>Where Sustainability Whispers with the Spirit of Bali</h2><p>Embark on sustainability at Nandini Jungle by Hanging Gardens, where luxury dances hand-in-hand with ecological wisdom. Discover how we&#039;ve woven sustainability into an art form, harmonizing with the land, the people, and the future.<br><br><br></p><h2>Sustainable Sanctuary and Facilities</h2><p>Our commitment to environmental harmony is woven into every aspect of Nandini Jungle by Hanging Gardens. From cutting-edge water conservation to waste reduction initiatives, our advanced purification systems, employing filtration and UV sterilization, ensure your access to safe drinking water.<br><br><br></p><h2>Preserving the Sacred Nature</h2><p>The river below the resort, Ayung River, is not merely water, it&#039;s the dwelling place of spirits. Locals and priests speak of its sanctity by climbing down to reach this holy place. Our resort, seamlessly integrated, becomes a guardian of this sacred space creating a memorable and meaningful experience for guests.<br><br><br></p><h2>Nurturing Nature</h2><p>At Nandini Jungle by Hanging Gardens, we delicately transform leftovers into love for the planet, nurturing gardens with composted organic waste and giving materials a second life through recycling programs, all while embracing water wisdom with a commitment to rainwater harvesting, recycling, and water-efficient landscaping practices in our pursuit of a gentle, eco-conscious haven.<br><br><br></p><h2>From Waste to Wonder Program</h2><p>We transform leftovers into love for the planet. Composted organic waste nourishes our gardens while recycling programs give materials a second life. Even your leftover food scraps find purpose, enriching the soil through composting.<br><br><br></p><h2>Locally Sourced Delights and Wellbeing</h2><p>Finally, we prioritize locally sourced and sustainable materials, supporting Balinese communities through responsible procurement practices. From artisanal crafts adorning our villas to fresh, locally sourced ingredients in our dining facilities, every detail whispers the spirit of Bali.<br><br><br></p><h2>The Flower Competition</h2><p>Amidst the challenges of the pandemic, Nandini Jungle by Hanging Gardens in partnership with the International Flower Competition (IFC) Foundation, nurtured a blooming renaissance in Banjar Susut, Payangan. The flower gardening competition transformed homes into canvases of vibrant artistry, reminding us that sustainability can be a vibrant expression of resilience and community.<br><br>Weave your own story into the tapestry at Nandini Jungle by Hanging Gardens. Reconnect with nature, rediscover the sacred threads that bind us to the earth, and experience luxury with a conscience.</p>', 'pages/hero/61d21b55-e40c-4266-81f6-16678356d48d.webp', 'Our Sustainability & Ecological Commitment | Nandini Jungle Bali', 'pages/hero-mobile/cfdd8a6f-d7c8-4f10-bd0d-5a3d79065f0c.webp', 'Our Sustainability & Ecological Commitment | Nandini Jungle Bali', 'Our Sustainability & Ecological Commitment | Nandini Jungle Bali', 'Discover how luxury harmonizes with ecological wisdom at Nandini Jungle by Hanging Gardens. Explore our Bali sustainability initiatives and eco-facilities.', 1, 20, '2024-05-13 05:24:38', '2026-05-29 05:25:13'),
(18, 'Thank you Page', 'Thank you for your Inquiry', 'thank-you-for-your-inquiry', NULL, NULL, '<p>Thank you for reaching out to us. We appreciate your interest and will respond to your inquiry shortly.</p>', NULL, NULL, NULL, NULL, 'Thank You', 'Thank you for reaching out to us. We appreciate your interest and will respond to your inquiry shortly.', 0, 24, '2024-05-19 09:46:44', '2026-07-06 19:20:03'),
(40, 'Membership - Privilege Redemtion', 'Privilege Redemtion', 'privilege-redemtion', NULL, NULL, '<p>Earn Nandini Jungle Points every time you stay, dine, shop with partners, or use your card — on property.</p>', 'pages/hero/121d5f61-7716-433f-b264-e902e661f0d8.webp', 'Privilege Redemtion', 'pages/hero-mobile/f40d3a9b-54ba-495a-9c04-2ab2275bd9aa.webp', 'Privilege Redemtion', 'Nandini Rewards Point Redemption | Redeem Your Benefits', 'Learn how to redeem Nandini Jungle Points for member privileges, stays, dining, spa treatments, and curated resort experiences in Ubud.', 1, 37, '2026-05-25 08:02:04', '2026-05-25 08:02:04'),
(41, 'Membership - Redeem Thank you page', 'Thank You', 'thank-you', 'Inner Circle', NULL, '<p>Your reward has been redeemed successfully.</p>', 'pages/hero/64dd1406-962f-4167-a026-513e9a960554.webp', 'Thank You', 'pages/hero-mobile/5fb5015e-764e-462c-905f-745098751de0.webp', 'Thank You', 'Reward Redeemed Successfully | Nandini Jungle', 'Thank you for redeeming your Inner Circle reward.', 1, 38, '2026-05-26 04:47:37', '2026-05-26 04:47:37'),
(22, 'About Us Page', 'About Us', 'about-us', NULL, 'The story of Nandini Jungle by Hanging Gardens began in the early 2000s, when our founder discovered a quiet hillside in the village of Susut, Ubud, nestled in the highlands of Bali. ', '<p>The story of Nandini Jungle by Hanging Gardens began in the early 2000s, when our founder discovered a quiet hillside in the village of Susut, Ubud, nestled in the highlands of Bali. Surrounded by dense jungle and overlooking the sacred Ayung River, the land was known by locals for its spiritual energy and natural beauty. It was here that the vision for Nandini took shape—a boutique hotel deeply rooted in local tradition and built in harmony with its surroundings.<br><br>From the beginning, sustainability and cultural preservation were at the heart of our mission. Working closely with villagers and artisans, the hotel was constructed using natural materials and traditional Balinese techniques. Local stone, bamboo, and alang-alang thatch were used to create villas that blend seamlessly into the landscape, with minimal impact on the environment.<br><br>When Nandini opened its doors, it was more than a hotel—it was a partnership with the local community. Many of our team members come from Susut and nearby villages. Their knowledge of Balinese customs, ceremonies, and cuisine shapes the guest experience and ensures that Nandini remains connected to the traditions of the region.<br><br>Over the years, we have continued to grow thoughtfully. We added the Essence Spa, where guests can enjoy treatments inspired by Balinese healing practices, and the Djiwa Shala yoga pavilion, offering a peaceful space surrounded by nature. Our Wild Ginger Restaurant features seasonal dishes prepared with ingredients sourced from local farms and markets, supporting small producers and reducing our environmental footprint.<br><br>While we have introduced modern comforts expected of a luxury retreat, our core values have remained unchanged. Nandini continues to operate with care for the land, respect for culture, and a commitment to creating meaningful experiences for every guest.<br><br>Today, Nandini Jungle by Hanging Gardens is proud to be part of the Susut community. We welcome travellers from around the world who are looking not only for relaxation, but also for connection—to nature, to culture, and to the people who call this part of Bali home.<br><br>We invite you to be part of our story.</p>', 'pages/hero/66b83deb-504e-4040-94a7-f9938b1ec419.webp', 'About Nandini Jungle by Hanging Gardens | Ubud Bali Resort', 'pages/hero-mobile/36b64027-6133-492e-aa8f-ebff621fd502.webp', 'About Nandini Jungle by Hanging Gardens | Ubud Bali Resort', 'About Nandini Jungle by Hanging Gardens | Ubud Bali Resort', 'Discover the story of Nandini Jungle by Hanging Gardens, a boutique jungle resort in Ubud rooted in Balinese tradition, sustainability, and local community.', 1, 14, '2025-05-12 09:15:39', '2026-05-27 07:22:16'),
(25, 'FAQ Page', 'Frequently Asked Questions', 'frequently-asked-questions', NULL, NULL, '<p>Find quick answers to the most common questions about staying at Nandini Jungle by Hanging Gardens. Get essential details on amenities, booking, and your jungle stay.</p>', 'pages/hero/831d8ad7-5244-4e7a-a661-22bd21bd492e.webp', 'Frequently Asked Questions', 'pages/hero-mobile/a03a5b24-214c-4383-8f06-538caca9c098.webp', 'Frequently Asked Questions', 'Plan Your Stay at Nandini Jungle by Hanging Gardens', 'Got questions about your upcoming trip to Nandini Jungle by Hanging Gardens? Read our frequently asked questions to ensure a seamless luxury resort experience.', 1, 19, '2025-10-06 15:25:40', '2026-05-29 03:27:36'),
(35, 'Membership - Home page', 'NANDINI INNER CIRCLE', 'nandini-inner-circle', NULL, NULL, '<p style=\"text-align: justify;\">Om Swastyastu<br>Welcome to our membership program</p>', 'pages/hero/150bac56-19ca-4ccb-9966-801438c2c01a.webp', 'Nandini Rewards | Luxury Resort Membership in Ubud Bali', 'pages/hero-mobile/0fcb6b15-feb5-42f0-aca9-53abfbc8be71.webp', 'Nandini Rewards | Luxury Resort Membership in Ubud Bali', 'Nandini Rewards | Luxury Resort Membership in Ubud Bali', 'Join Nandini Rewards and enjoy exclusive member benefits, room savings, spa treatments, dining perks, upgrades, and complimentary stays at our Ubud jungle resort.', 1, 32, '2026-05-08 18:01:56', '2026-06-12 23:27:29'),
(26, 'Media Center', 'Media Center', 'media-center', NULL, 'Here, we provide a comprehensive hub designed to keep you informed about our brand’s activities, industry insights, and significant announcements. ', '<p>Here, we provide a comprehensive hub designed to keep you informed about our brand’s activities, industry insights, and significant announcements.</p>', NULL, NULL, NULL, NULL, 'Media Center', 'Here, we provide a comprehensive hub designed to keep you informed about our brand’s activities, industry insights, and significant announcements. ', 0, 25, '2025-10-27 12:12:31', '2026-07-06 19:20:01'),
(27, 'Image Library Page', 'Image Library', 'image-library', NULL, NULL, '<p>Discover the stunning beauty of Nandini Jungle by Hanging Gardens through our image library. Explore breathtaking photos of villas, rainforest views, spa sanctuaries, dining experiences, and unforgettable moments in the heart of Ubud.</p>', NULL, NULL, NULL, NULL, 'Image Library', 'Discover the stunning beauty of Nandini Jungle by Hanging Gardens through our image library.', 0, 26, '2025-10-29 15:57:23', '2026-07-06 19:20:00'),
(28, 'Resort Information Page', 'Resort Information', 'resort-information', NULL, NULL, '<p>Find essential details about Nandini Jungle by Hanging Gardens. Learn about our location, facilities, services, and experiences that make your stay in the heart of Ubud’s rainforest truly memorable.</p>', NULL, NULL, NULL, NULL, 'Resort Information', 'Find essential details about Nandini Jungle by Hanging Gardens. Learn about our location, facilities, services, and experiences that make your stay truly memorable.', 0, 27, '2025-10-29 15:58:24', '2026-07-06 19:20:00'),
(29, 'Video Page', 'Video', 'video', NULL, NULL, '<p>Watch captivating videos of Nandini Jungle by Hanging Gardens. Experience the serene rainforest, luxurious villas, spa rituals, and unforgettable moments that define our resort in Ubud.</p>', NULL, NULL, NULL, NULL, 'Video', 'Watch captivating videos of Nandini Jungle by Hanging Gardens. Experience the serene rainforest, luxurious villas, and unforgettable moments that define our resort in Ubud.', 0, 28, '2025-10-29 15:59:12', '2026-07-06 19:20:00'),
(32, 'Festive Page', 'Celebrate the magic of the holidays', 'bali-festive-holiday-celebrations', NULL, NULL, '<p>This festive season, Nandini Jungle by Hanging Gardens invites guests to embrace the warmth of Christmas and the joy of the New Year in the heart of Ubud’s lush rainforest. Far from crowds yet close to tradition, the resort transforms into a sanctuary of light, flavour, and celebration. From a candlelit Christmas Eve dinner to a vibrant New Year’s gathering under the stars, every moment is created to bring people closer. Here, luxury takes a gentler form, blending nature, comfort, and connection.</p>', NULL, NULL, NULL, NULL, 'Bali Holiday Season Offers at Nandini Jungle', 'Experience magical festive moments at Nandini Jungle by Hanging Gardens. Enjoy special holiday-season offers, and exclusive dining surrounded by Bali’s rainforest beauty.', 0, 29, '2025-12-05 16:13:56', '2026-04-29 01:05:52'),
(33, 'Presidential Royal Suite Page', 'Presidential Royal Suite', 'presidential-royal-suite', NULL, NULL, '<p>One of the largest suites in Bali, the Presidential Royal Suite offers exceptional space, privacy, and refined jungle living. <br><br>Elegantly designed with rich furnishings, the suite features a master bedroom opening onto a generous private terrace overlooking lush gardens and the majestic Ubud rainforest. The expansive living area is ideal for families or guests seeking space to relax and gather. <br><br>A stay in the Presidential Royal Suite is defined by tranquillity, scale, and complete immersion in nature.</p>', 'pages/hero/presidential-royal-suite-nandini-jungle-bali.webp', 'Presidential Royal Suite surrounded by lush tropical gardens at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'pages/hero-mobile/presidential-royal-suite-nandini-jungle-bali.webp', 'Presidential Royal Suite surrounded by lush tropical gardens at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'Presidential Royal Suite in Ubud Bali | Nandini Jungle', 'Stay in the Presidential Royal Suite at Nandini Jungle by Hanging Gardens, one of the largest suites in Bali with refined living space and private jungle views.', 1, 8, '2025-12-29 10:21:40', '2026-06-30 00:10:10'),
(31, 'SEO - Luxury Bali Jungle Resort in Ubud Page', 'Luxury Bali Jungle Resort in Ubud', 'ubud-jungle-resort-in-bali', 'Experience a True Ubud Jungle Resort at Nandini Jungle by Hanging Gardens', NULL, '<p>If you are searching for an authentic <strong>Ubud jungle resort</strong>, Nandini offers a rare sanctuary immersed in Bali’s lush rainforest. Perched along a dramatic river valley, this Bali jungle resort blends seclusion, nature, and refined comfort into one unforgettable retreat.<br><br>Surrounded by dense greenery, cool mountain air, and panoramic forest views, guests wake to birdsong and drifting morning mist above the treetops. Every detail — from handcrafted architecture to elevated walkways — is designed to immerse you in the natural rhythm of Ubud’s sacred landscape.<br><br>Whether you seek romance, wellness, or quiet reconnection with nature, this jungle resort in Ubud provides an intimate escape far from Bali’s crowded coastal areas.</p>', 'pages/hero/luxury-bali-jungle-resort-ubud-rainforest-pool.webp', 'Luxury Bali jungle resort in Ubud with rainforest views, infinity pool, and tropical valley setting at Nandini Jungle by Hanging Gardens', 'pages/hero-mobile/luxury-bali-jungle-resort-ubud-rainforest-pool.webp', 'Luxury Bali jungle resort in Ubud with rainforest views, infinity pool, and tropical valley setting at Nandini Jungle by Hanging Gardens', 'Best Bali Jungle Resort in Ubud | Luxury Nature Escape', 'Escape to a hidden Bali jungle resort in Ubud. Stay in private villas surrounded by lush rainforest, rivers, and serene nature just minutes from Ubud center.', 1, 30, '2025-12-03 15:33:01', '2026-06-26 18:21:34'),
(34, 'SEO - Ubud Wellness Retreat: Reconnect with Nature in the Heart of Bali Page', 'Ubud Wellness Retreat: Reconnect with Nature in the Heart of Bali', 'ubud-wellness-retreat', NULL, 'Hidden among emerald jungle valleys and the calming flow of tropical rivers, Ubud has long been considered the spiritual heart of Bali. Travelers from around the world come here not only for its breathtaking landscapes, but also for the sense of balance and renewal that naturally arises from its surroundings.', '<p>Hidden among emerald jungle valleys and the calming flow of tropical rivers, <strong>Ubud has long been considered the spiritual heart of Bali</strong>. Travelers from around the world come here not only for its breathtaking landscapes, but also for the sense of balance and renewal that naturally arises from its surroundings.</p><p>An <strong>Ubud wellness retreat</strong> offers more than a relaxing holiday. It is an opportunity to step away from the pace of everyday life and immerse yourself in a sanctuary designed for rest, reflection, and rejuvenation.</p><p>Surrounded by lush rainforest, rice terraces, and sacred temples, Ubud provides the perfect setting for a transformative wellness journey.</p>', 'pages/hero/ubud-wellness-retreat-jungle-spa-terrace.webp', 'Ubud wellness retreat spa setup on a jungle terrace at Nandini Jungle by Hanging Gardens Bali', 'pages/hero-mobile/ubud-wellness-retreat-jungle-spa-terrace.webp', 'Ubud wellness retreat spa setup on a jungle terrace at Nandini Jungle by Hanging Gardens Bali', 'Ubud Wellness Retreat in Bali | Jungle Spa & Holistic Escape', 'Experience a rejuvenating Ubud wellness retreat surrounded by Bali’s lush jungle. Enjoy yoga, spa rituals, and tranquil villa stays designed for total relaxation', 1, 31, '2026-03-09 08:47:57', '2026-06-26 18:59:42'),
(42, 'Voucher Landing', 'Gift Voucher', 'gift-voucher', NULL, NULL, '<p>Share the gift of unforgettable experiences at Nandini Jungle by Hanging Gardens. Whether you&#039;re treating a family member, surprising a friend during their stay, or enhancing your own getaway, our gift vouchers offer the perfect way to create lasting memories.<br><br>Choose from a selection of dining experiences, rejuvenating spa treatments, and unique resort activities, allowing every recipient to enjoy the beauty and tranquility of our jungle retreat in their own way.</p>', 'pages/hero/gift-voucher-relaxation-nandini-jungle.webp', 'Guests relaxing at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'pages/hero-mobile/gift-voucher-relaxation-nandini-jungle.webp', 'Guests relaxing at Nandini Jungle by Hanging Gardens in Ubud, Bali', 'Gift Vouchers in Bali | Nandini Jungle by Hanging Gardens', 'Discover luxury gift vouchers for dining, spa treatments, and resort experiences at Nandini Jungle by Hanging Gardens in Bali.', 1, 39, '2026-07-11 21:41:14', '2026-07-18 19:19:02'),
(43, 'Events', 'Events & Entertainment', 'events-entertainment', NULL, 'Discover dining experiences and live entertainment at Nandini Jungle by Hanging Gardens. Enjoy Balinese dance, Barong dance, traditional flute performances, finger musicians and live acoustic music at Wild Ginger Restaurant.', '<p>Discover dining experiences and live entertainment at Nandini Jungle by Hanging Gardens. Enjoy Balinese dance, Barong dance, traditional flute performances, finger musicians and live acoustic music at Wild Ginger Restaurant.</p>', 'pages/hero/guests-enjoying-cocktails-wild-ginger.webp', 'Two guests enjoying cocktails at Wild Ginger Restaurant at Nandini Jungle by Hanging Gardens.', 'pages/hero-mobile/guests-enjoying-cocktails-wild-ginger.webp', 'Two guests enjoying cocktails at Wild Ginger Restaurant at Nandini Jungle by Hanging Gardens.', 'Events at Wild Ginger | Nandini Jungle Bali', 'Discover Balinese performances, live music, themed dinners and BBQ events at Wild Ginger, Nandini Jungle by Hanging Gardens.', 1, 40, '2026-08-05 22:24:10', '2026-08-05 22:28:45'),
(44, 'Affiliate', 'Join the Nandini Partner Circle', 'join-the-nandini-partner-circle', NULL, NULL, '<p>Share the beauty of Nandini Jungle by Hanging Gardens with your audience and earn rewards for every successful referral.<br><br>The Nandini Partner Circle is our official affiliate program designed for travel creators, bloggers, publishers, travel advisors, wellness professionals, and anyone passionate about inspiring unforgettable travel experiences.</p>', 'pages/hero/affiliate.webp', 'Join the Nandini Partner Circle', 'pages/hero-mobile/affiliate.webp', 'Join the Nandini Partner Circle', 'Nandini Partner Circle | Affiliate Program', 'Share the beauty of Nandini Jungle by Hanging Gardens with your audience and earn rewards for every successful referral.', 1, 41, '2026-08-07 21:14:43', '2026-08-07 21:14:43');

