CREATE TABLE `page_sections` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `page_id` bigint(20) UNSIGNED NOT NULL,
  `section_key` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subtitle` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `excerpt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `image` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile_image` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `button_label` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `button_link_type` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `button_url` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `button_route` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `text_align` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'center',
  `background_color` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

--
-- Dumping data for table `page_sections`
--

INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `title`, `subtitle`, `excerpt`, `description`, `items`, `image`, `mobile_image`, `button_label`, `button_link_type`, `button_url`, `button_route`, `text_align`, `background_color`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'image_overlay_section', 'Presidential Royal Suite', NULL, NULL, '<p>One of the largest suites in Bali, the Presidential Royal Suite offers exceptional space, privacy, and refined jungle living.</p>', NULL, NULL, NULL, 'Discover', 'route', '#', 'accommodations.presidential-royal-suite.show', 'center', NULL, 0, 2, '2026-04-28 22:04:52', '2026-06-20 20:33:55'),
(2, 1, 'split_media_reverse', 'Private Jungle Villas & Royal Suites', NULL, '<p></p>', '<p>Stay in private jungle villas in Ubud and spacious royal suites surrounded by rainforest, tropical greenery, and the calm atmosphere of Bali. Each accommodation at Nandini Jungle by Hanging Gardens is designed for comfort, privacy, and warm Balinese character, creating a refined jungle retreat for couples, families, and guests seeking space to reconnect with nature.</p>', NULL, NULL, NULL, 'Discover', 'route', NULL, 'accommodations.index', 'center', NULL, 0, 3, '2026-04-28 22:35:36', '2026-07-06 23:55:31'),
(3, 1, 'split_media_section', 'Jungle Weddings', NULL, NULL, '<p>Imagine exchanging vows surrounded by emerald forest, flowing water, and panoramic valley views—a backdrop that feels as timeless as your love. Whether you&#039;re planning an intimate ceremony or a grand celebration, Nandini offers a magical canvas for your special day.</p>', NULL, NULL, NULL, 'Discover', 'route', NULL, 'wedding.index', 'center', NULL, 0, 4, '2026-04-28 22:48:51', '2026-06-20 20:33:55'),
(4, 1, 'three_images_section', 'Wild Ginger Restaurant', NULL, NULL, '<p>Your epicurean journey begins at Wild Ginger Restaurant, an authentic Indonesian restaurant that artfully weaves culinary magic.</p>', NULL, NULL, NULL, 'Discover', 'route', NULL, 'dining.index', 'center', NULL, 0, 5, '2026-04-28 23:07:35', '2026-06-20 20:33:55'),
(5, 1, 'split_media_section', 'Essence Spa', NULL, NULL, '<p>The Essence Spa welcomes you to step into a world of complete comfort, relaxation and rejuvenation.</p>', NULL, NULL, NULL, 'Discover', 'route', NULL, 'spa.index', 'center', NULL, 0, 6, '2026-04-28 23:34:20', '2026-06-20 20:33:55'),
(6, 1, 'two_images_reverse', 'Unique Experiences', NULL, NULL, '<p>Set in gorgeous Balinese jungles and sitting along the Ayung river, Nandini Jungle by Hanging Gardens promises to create exceptional experiences that you will never forget</p>', NULL, NULL, NULL, 'Discover', 'route', NULL, 'experiences.index', 'center', NULL, 0, 7, '2026-04-28 23:41:50', '2026-06-20 20:33:55'),
(7, 1, 'image_overlay_section', 'Riverside Bliss: Half-Day Picnic and Wellness Escape at the River', NULL, NULL, '<p>Treat your loved one to an intimate riverside picnic by the scenic river&#039;s edge for moments of leisure and connection amidst the pristine Ubud jungle.</p>', NULL, NULL, NULL, 'More Details', 'manual', '/experience/riverside-bliss-half-day-picnic-and-wellness-escape-at-the-river', 'home', 'left', NULL, 1, 8, '2026-04-28 23:58:42', '2026-06-20 20:33:55'),
(8, 24, 'image_overlay_section', 'A Sanctuary of Wellness in Ubud', NULL, NULL, '<p>Awaken at our Ubud healing retreat, where nature, spirituality, and serenity converge<br><br>Exclusive access to the sacred holy spring, a unique privilege among Bali wellness resorts. Immerse yourself in Ayung River&#039;s revered waters and connect to an energy known for centuries to cleanse and transform. Local folklore speaks of this river as the river of spirits, where divine energy from Bali&#039;s volcanoes and mountains flows, uniting Vishnu and Shiva in a sacred dance of earth and water.</p>', NULL, NULL, NULL, NULL, 'route', NULL, NULL, 'center', NULL, 1, 0, '2026-04-30 22:40:59', '2026-04-30 22:45:05'),
(9, 24, 'split_media_reverse', 'Recharge in Bali\'s Sacred Energy Sanctuary', NULL, NULL, '<p>Replenish your spirit at our healing resort, with meditation, yoga, and spa experiences in a setting known for its transformative powers. Drift into bliss in our infinity pool and restore harmony to your mind, body, and spirit at one of Bali&#039;s most relaxing resort and spa.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-04-30 22:46:31', '2026-04-30 22:46:31'),
(10, 24, 'split_media_section', 'Luxury Amidst Untouched Nature', NULL, NULL, '<p>Amidst Ubud&#039;s pristine nature, experience ultimate luxury in your own private terrace with sweeping views of Bali&#039;s sacred landscape, indulgent spa and wellness treatments, and refined, high-end dining at our secluded wellness resort.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-04-30 22:47:14', '2026-04-30 22:47:14'),
(11, 24, 'intro_text_section', 'immerse yourself in the holy water experience', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-04-30 22:52:53', '2026-04-30 22:52:53'),
(12, 24, 'image_overlay_section', 'Begin Your Sacred Journey of Renewal and Healing', NULL, NULL, '<p><strong>The Place of Transformation</strong><br>Experience a journey of renewal at our Ubud Healing Retreat, guided by the sacred energy of the holy waters.<br><br><strong>Secluded Yet Close</strong><br>Escape to a hidden gem of Bali healing resort, minutes from Ubud’s cultural heart, for a tranquility without isolation.<br><br><strong>Authentic Balinese Experience</strong><br>Immerse in Balinese traditions with sacred rituals, local flavors, and holistic wellness at this pristine jungle sanctuary.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', NULL, 1, 0, '2026-04-30 23:08:55', '2026-04-30 23:08:55'),
(13, 3, 'split_media_section', 'Jungle Villas', NULL, '<p></p>', '<p>Indulge in the ultimate luxury in our exquisite villas, where elegance meets privacy. Each villa is a private oasis, featuring spacious living areas, bespoke furnishings, and breathtaking views. Enjoy your secluded outdoor sanctuary, complete with lavish amenities and personalized service designed for your comfort. Experience a serene escape that redefines opulence—your exclusive haven awaits.</p>', NULL, NULL, NULL, 'Discover', 'manual', '/jungle-villas', NULL, 'center', NULL, 1, 0, '2026-05-04 18:52:55', '2026-05-27 06:29:27'),
(14, 3, 'image_overlay_section', 'The Royal Suites', NULL, '<p></p>', '<p>Experience refined luxury in The Royal Suites at Nandini Jungle by Hanging Gardens, where elegant design, generous living spaces, and tranquil jungle views create a private sanctuary in Ubud. Thoughtfully designed for comfort and relaxation, each suite offers a graceful balance of timeless style, modern amenities, and warm Balinese hospitality. Whether for a romantic escape, special celebration, or peaceful retreat, The Royal Suites invite you to unwind in an atmosphere of quiet sophistication.</p>', NULL, NULL, NULL, 'Discover', 'manual', '/the-royal-suites', NULL, 'center', NULL, 1, 0, '2026-05-04 20:01:02', '2026-05-27 06:30:09'),
(15, 21, 'image_overlay_section', 'Presidential Royal Suite', NULL, NULL, '<p>One of the largest suites in Bali, the Presidential Royal Suite offers exceptional space, privacy, and refined jungle living.</p>', NULL, NULL, NULL, 'Discover', 'manual', '/the-royal-suites/presidential-royal-suite', 'index', 'center', NULL, 1, 0, '2026-05-05 19:25:02', '2026-05-05 19:36:05'),
(16, 33, 'split_media_reverse', 'Grand Master Bedroom with Garden and Rainforest Views', NULL, NULL, '<p>The master bedroom of the Presidential Royal Suite is a refined sanctuary designed to deliver absolute comfort, privacy, and understated elegance. Anchored by a luxurious king-size bed dressed in premium linens, the space is thoughtfully furnished with rich textures and handcrafted details that reflect timeless Balinese sophistication. Every element is carefully arranged to create a calm, intimate atmosphere ideal for deep rest and rejuvenation.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-05 19:44:15', '2026-05-05 22:00:09'),
(17, 33, 'split_media_section', 'Private Garden and Outdoor Leisure Space', NULL, NULL, '<p>The villa’s private garden is a beautifully curated outdoor sanctuary, designed to offer a seamless extension of the Presidential Royal Suite’s indoor luxury. Surrounded by manicured greenery, tropical plants, and the natural beauty of the Ubud rainforest, this expansive outdoor space provides an atmosphere of complete tranquility and seclusion. Every corner of the garden is thoughtfully arranged to encourage relaxation, connection with nature, and unhurried moments of leisure.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-05 19:45:23', '2026-05-05 22:00:16'),
(18, 33, 'split_media_reverse', 'In-Suite Wellness and Personalized Spa Experience', NULL, NULL, '<p>Designed with holistic wellbeing at its core, the Presidential Royal Suite offers an intimate and private setting for personalized spa and wellness experiences within the comfort of the villa. This dedicated space allows guests to enjoy rejuvenating treatments without stepping outside, creating a deeply restorative experience enhanced by the villa’s serene surroundings. The gentle presence of tropical greenery and the soothing ambiance of the Ubud rainforest contribute to a sense of calm that begins the moment the treatment starts.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-05 19:46:11', '2026-05-05 22:00:26'),
(19, 33, 'split_media_section', 'Spacious Living Area for Family Gatherings', NULL, NULL, '<p>At the heart of the Presidential Royal Suite lies a generously sized living area, thoughtfully designed to bring comfort, connection, and refined elegance together. Rich wooden furnishings, elegant textures, and curated Balinese décor create a warm and inviting ambiance that reflects timeless craftsmanship and cultural authenticity. Soft lighting and open space enhance the sense of ease, making the living area both welcoming and sophisticated.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-05 19:46:42', '2026-05-05 22:00:34'),
(20, 33, 'split_media_reverse', 'Open-Air Bathroom with Jacuzzi and Rain Shower', NULL, NULL, '<p>The Presidential Royal Suite features a refined open-air bathroom set within a private tropical courtyard, where natural stone textures and lush greenery create a calm, spa-like atmosphere. At the center, a sculptural freestanding bathtub invites leisurely soaking, surrounded by soft daylight and the soothing presence of nature. The open design allows fresh air to circulate freely, enhancing a sense of space, tranquility, and connection to the outdoors while preserving complete privacy.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-05 19:47:37', '2026-05-05 22:00:41'),
(22, 35, 'intro_text_section', 'Your sanctuary to return', 'About Nandini Inner Circle', NULL, '<p>The Nandini Inner Circle is our private membership program — a set of tiers offering exclusive benefits, recognition, and rewards for those who return. Inspired by the Dasa Paramita (Ten Virtues) — a classical philosophy of inner growth.<br><br>The Dasa Paramita (Ten Virtues) are guiding principles in Balinese Hindu life, encouraging balance, self-discipline, and harmony with others and nature. They are often practiced in daily behavior, community life, and spiritual rituals.<br><br>The Nandini Inner Circle mirrors a guest&#039;s journey from first connection to belonging, reflecting generosity, intention, calm, and understanding.<br><br>“Nandini Jungle exists for those who seek more than luxury, but a meaning of life. Every guest who arrives carries the weight of the world. Every guest who leaves, carries only themselves.&quot;</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 1, '2026-05-14 03:06:41', '2026-07-02 17:55:23'),
(23, 35, 'how_it_works_section', 'How It Works?', NULL, NULL, '<p>Becoming part of Nandini Inner Circle is simple. From your first booking to every return stay, each moment brings you closer to more meaningful rewards inspired by Dana (generosity), Upaya (thoughtful service), Dhyana (presence), and Jnana (understanding).</p>', '[{\"icon\": \"user\", \"title\": \"Join For Free\", \"description\": \"Sign up through our website and become part of Nandini Circle\"}, {\"icon\": \"book\", \"title\": \"Book & Earn\", \"description\": \"Book directly with us and start earning benefits instantly\"}, {\"icon\": \"arrow-up\", \"title\": \"Stay & Upgrade\", \"description\": \"Enjoy your stay, earn points, and move up to the next tier\"}, {\"icon\": \"gift\", \"title\": \"Redeem & Enjoy\", \"description\": \"Use your points to enhance your jungle experience\"}]', NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 3, '2026-05-14 03:44:27', '2026-05-16 06:15:43'),
(25, 35, 'intro_text_section', NULL, NULL, NULL, '<p>You will automatically become part of Nandini Inner Circle when you make a booking through our official website. Your tier level and points are calculated based on your total spending during your stay, including accommodation, food &amp; beverage, and spa experiences—allowing every moment at Nandini to bring you closer to greater rewards.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', 'white', 1, 4, '2026-05-14 05:32:24', '2026-05-16 06:15:43'),
(26, 35, 'member_benefits_section', 'Circle Benefits', NULL, '<p><em>** Subject to availability</em></p><p><em>*** Subject to availability and maximum upgrade until Panoramic Corner Jacuzzi Royal Suite</em></p>', '<p>Nandini Inner Circle offers valuable benefits to make your stay more convenient and rewarding, from exclusive savings on rooms to late check-out, complimentary upgrades, and butler service.</p>', '[{\"benefit\":\"Extra savings on rooms\",\"bronze\":\"0%\",\"silver\":\"5%\",\"gold\":\"10%\",\"platinum\":\"15%\"},{\"benefit\":\"10% off Food & Beverage (excluding alcoholic drinks)\",\"bronze\":\"\\u2713\",\"silver\":\"\\u2713\",\"gold\":\"\\u2713\",\"platinum\":\"\\u2713\"},{\"benefit\":\"10% off Spa treatments\",\"bronze\":\"\\u2713\",\"silver\":\"\\u2713\",\"gold\":\"\\u2713\",\"platinum\":\"\\u2713\"},{\"benefit\":\"One-time 15-minute foot massage\",\"bronze\":\"\\u2713\",\"silver\":\"\\u2713\",\"gold\":\"\\u2713\",\"platinum\":\"\\u2713\"},{\"benefit\":\"Late check-out up to 2.00 pm **\",\"bronze\":null,\"silver\":\"\\u2713\",\"gold\":\"\\u2713\",\"platinum\":\"\\u2713\"},{\"benefit\":\"Welcome canap\\u00e9s upon arrival\",\"bronze\":null,\"silver\":\"\\u2713\",\"gold\":\"\\u2713\",\"platinum\":\"\\u2713\"},{\"benefit\":\"Villa category upgrade ***\",\"bronze\":null,\"silver\":null,\"gold\":\"1-Tier\",\"platinum\":\"2-Tier\"},{\"benefit\":\"Early check-in from 12.00 am **\",\"bronze\":null,\"silver\":null,\"gold\":\"\\u2713\",\"platinum\":\"\\u2713\"},{\"benefit\":\"Personalized in-room check-in\",\"bronze\":null,\"silver\":null,\"gold\":null,\"platinum\":\"\\u2713\"},{\"benefit\":\"Butler service\",\"bronze\":null,\"silver\":null,\"gold\":null,\"platinum\":\"\\u2713\"}]', NULL, NULL, 'Private butler', 'manual', NULL, NULL, 'center', NULL, 1, 5, '2026-05-14 06:02:14', '2026-06-12 23:13:23'),
(27, 35, 'how_it_works_section', 'How To Earn Points', NULL, NULL, NULL, '[{\"icon\": \"home\", \"title\": \"Accommodation\", \"description\": \"Earn points from every room booking made during your stay.\"}, {\"icon\": \"cup\", \"title\": \"Food & Beverages\", \"description\": \"Enjoy dining experiences and collect points from all food and beverage spending.\"}, {\"icon\": \"heart\", \"title\": \"Spa & Wellness\", \"description\": \"Indulge in spa treatments and purification rituals, and earn points while you relax and recharge.\"}]', NULL, NULL, NULL, 'manual', NULL, NULL, 'center', 'soft_gray', 1, 6, '2026-05-14 06:36:30', '2026-05-16 06:15:43'),
(28, 35, 'membership_tier_section', 'Circle Level', NULL, NULL, '<p>Each circle represents a deeper relationship with Nandini Jungle, combining meaningful recognition, thoughtful service, and experiences designed around every guest.</p>', '[{\"tier_name\": \"Bronze\", \"card_design\": \"bronze\", \"circle_name\": \"Dana\", \"description\": \"At Nandini, Dana is reflected in how we give—through thoughtful perks, personalized touches, and genuine care. It’s about creating moments where guests feel valued beyond the stay.\", \"circle_meaning\": \"Generosity\"}, {\"tier_name\": \"Silver\", \"card_design\": \"silver\", \"circle_name\": \"Upaya\", \"description\": \"Upaya translates into how we serve. Every detail is handled with care and intention, ensuring each guest experience feels smooth, responsive, and well-considered.\", \"circle_meaning\": \"Thoughtful Service\"}, {\"tier_name\": \"Gold\", \"card_design\": \"gold\", \"circle_name\": \"Dhyana\", \"description\": \"Dhyana comes to life through the peaceful jungle setting and curated experiences. It’s about helping guests slow down, reconnect, and fully enjoy the present moment.\", \"circle_meaning\": \"Calm & Presence\"}, {\"tier_name\": \"Platinum\", \"card_design\": \"platinum\", \"circle_name\": \"Jnana\", \"description\": \"Jnana is about understanding our guests better over time. Through the loyalty program, we learn preferences and create more personalized, relevant experiences with each return visit.\", \"circle_meaning\": \"Meaningful Insight\"}]', NULL, NULL, NULL, 'manual', NULL, NULL, 'center', 'soft_gray', 1, 2, '2026-05-16 02:38:56', '2026-05-16 06:15:43'),
(29, 35, 'membership_use_points_section', 'Use Your Points', NULL, NULL, '<p>Enhance your jungle stay by redeeming your points for a range of curated experiences—from a blessing purification ritual and Exotic Balinese Massage to a cooking class or a romantic candlelight dinner. You can also use your points toward a complimentary room stay for a longer, more relaxing escape.</p>', '[{\"image\": \"membership/use-points/37db053c-c2af-4735-87b5-23590ca94287.webp\", \"title\": \"One-night stay at Jungle View Villa \", \"button_url\": null, \"description\": null, \"button_label\": \"Redeem\", \"points_label\": \"1,983 points\"}, {\"image\": \"membership/use-points/51d6db99-47f2-4618-9b66-162169e92206.webp\", \"title\": \"One-night stay at Panoramic Jungle View Villa\", \"button_url\": null, \"description\": null, \"button_label\": \"Redeem\", \"points_label\": \"2,397 points\"}, {\"image\": \"membership/use-points/063de17c-990f-4e50-9fc6-153dd7bedea3.webp\", \"title\": \"One-night stay at Panoramic Corner Jacuzzi Royal Suite \", \"button_url\": null, \"description\": \"Enjoy a one-night stay with breakfast for two included\", \"button_label\": \"Redeem\", \"points_label\": \"3,140 points\"}, {\"image\": \"membership/use-points/0872e8fa-89e7-430c-ba44-f7aaafe6398d.webp\", \"title\": \"Two-course Lunch or Dinner\", \"button_url\": null, \"description\": \"Enjoy a two-course set menu for lunch or dinner for one person\", \"button_label\": \"Redeem\", \"points_label\": \"264 points\"}, {\"image\": \"membership/use-points/848b5110-9487-4387-bac4-3e48032f48d2.webp\", \"title\": \"Candle Light Dinner by the Pool\", \"button_url\": null, \"description\": \"Enjoy an intimate dining experience with your loved one at the pool deck under the stars\", \"button_label\": \"Redeem\", \"points_label\": \"6,800 points\"}, {\"image\": \"membership/use-points/9d5477e9-c231-49b1-b398-a55c6c58a65d.webp\", \"title\": \"Cooking Class\", \"button_url\": null, \"description\": \"Learn how to prepare authentic Balinese dishes with our chef, for two persons\", \"button_label\": \"Redeem\", \"points_label\": \"2,800 points\"}, {\"image\": \"membership/use-points/4849d9ab-a744-4fa4-948c-fa2e0c99cc91.webp\", \"title\": \"Exotic Balinese Massage 90’\", \"button_url\": null, \"description\": \"Enjoy a traditional Balinese massage with coconut oil to relax your body and improve circulation, for one person\", \"button_label\": \"Redeem\", \"points_label\": \"1,200 points\"}, {\"image\": \"membership/use-points/574fa56a-9b86-400c-b9b2-82dfa7836660.webp\", \"title\": \"Airport Transfer \", \"button_url\": null, \"description\": \"Airport pick-up or drop-off service for up to three persons\", \"button_label\": \"Redeem\", \"points_label\": \"600 points\"}, {\"image\": \"membership/use-points/21aed5a4-7401-431a-be0c-584cae37b0f2.webp\", \"title\": \"Balinese Blessing Purification at the River \", \"button_url\": null, \"description\": \"A sacred Balinese blessing purification by the healing waters of the Ayung River, for two persons\", \"button_label\": \"Redeem\", \"points_label\": \"2,000 points\"}]', NULL, NULL, NULL, 'manual', NULL, NULL, 'center', 'white', 1, 7, '2026-05-16 03:07:28', '2026-05-16 06:15:43'),
(30, 35, 'membership_faq_section', 'Frequently Asked Questions', NULL, NULL, NULL, '[{\"question\":\"What is Nandini Inner Circle?\",\"answer\":\"Nandini Inner Circle is our loyalty program designed to reward your stay with exclusive benefits, points, and curated experiences.\"},{\"question\":\"How do I join the program?\",\"answer\":\"You can join for free by signing up on our official website or automatically when you make a direct booking with us.\"},{\"question\":\"How do I earn points?\",\"answer\":\"Points are earned from your total spending during your stay, including room bookings, food & beverages, and spa & wellness experiences.\"},{\"question\":\"When my point is added?\",\"answer\":\"Your points will be added after your departure (up to 7 days) and the points can be used for the upcoming stay.\"},{\"question\":\"Can I earn points if I book through other platforms?\",\"answer\":\"Points and benefits are only applicable for bookings made directly through our official website.\"},{\"question\":\"What can I use my points for?\",\"answer\":\"You can redeem points for a variety of experiences such as dining, spa treatments, activities, and even complimentary stays.\"},{\"question\":\"Do my points expire?\",\"answer\":\"Your points and Circle tier remain valid for 365 days after your last stay. If there is no activity after 365 days, your tier will be adjusted to the previous level.\"},{\"question\":\"How do tier upgrades work?\",\"answer\":\"Your tier level is based on your total spending. The more you enjoy during your stay, the higher your tier and the better your benefits.\"},{\"question\":\"What benefits do I get as a member?\",\"answer\":\"Members enjoy exclusive perks such as special room rates, late check-out, complimentary upgrades, and personalized services.\"},{\"question\":\"How do I redeem my points?\",\"answer\":\"Points can be redeemed during your stay or when booking directly with us, depending on availability and selected experiences.\"},{\"question\":\"Can I combine points with other promotions?\",\"answer\":\"This depends on the promotion. Some offers may not be combined with loyalty benefits\\u2014please check the terms or contact our team.\"},{\"question\":\"Can I transfer my points to someone else (family members or friends)?\",\"answer\":\"No. Nandini Inner Circle points are non-transferable and can only be used by the member who earned them. Points cannot be gifted, transferred, sold, or combined with another member\'s account.\"}]', NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 8, '2026-05-16 06:15:23', '2026-06-20 21:06:24'),
(31, 39, 'intro_text_section', NULL, NULL, NULL, '<h1><strong>Member-Only Privilege</strong></h1><ul><li><p>Exclusive member-only rates <strong>(not combinable with public promotions)</strong>.</p></li><li><p>Early access to seasonal offers and festive packages.</p></li><li><p>Invitation to exclusive experiences for <strong>Gold &amp; Platinum</strong> members, such as:</p><ul><li><p>Private yoga or wellness sessions.</p></li><li><p>Guided jungle walks.</p></li><li><p>Cultural storytelling evenings.</p></li></ul></li></ul>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'soft_gray', 1, 0, '2026-05-25 06:04:11', '2026-05-25 06:15:42'),
(32, 39, 'intro_text_section', NULL, NULL, NULL, '<h2><strong>POINT REDEMPTION</strong></h2><p>Points may be redeemed for the following:</p><ul><li><p>Complimentary stays.</p></li><li><p>Food &amp; Beverage credits.</p></li><li><p>Spa treatments.</p></li><li><p>Yoga sessions.</p></li><li><p>Transportation or curated tour activities.</p></li></ul><p><br>Redemption Guidelines</p><ul><li><p>Minimum points apply for each reward category.</p></li><li><p>Complimentary stays are subject to availability and blackout dates during high &amp; peak seasons.</p></li><li><p>Points are non-transferable, non-refundable, and cannot be exchanged for cash.</p></li></ul>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 0, '2026-05-25 06:25:32', '2026-05-25 06:26:04'),
(33, 39, 'intro_text_section', NULL, NULL, NULL, '<h2>MEMBERSHIP VALIDITY &amp; RENEWAL</h2><ul><li><p>Membership tier status is valid for 12 months (365 days) from the last qualifying check-out date.</p></li><li><p>Members must complete at least one qualifying stay within each 365-day period to maintain their tier.</p></li><li><p>Tier downgrade applies if no qualifying stay is recorded.</p></li></ul><p></p><p>Example:</p><ul><li><p>Gold → Silver after 365 days of inactivity.</p></li><li><p>Further inactivity will result in additional downgrade.</p></li><li><p>A one-time grace period extension may be considered for Gold and Platinum members upon request.</p></li></ul>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 0, '2026-05-25 06:29:36', '2026-05-25 06:29:36'),
(34, 39, 'intro_text_section', NULL, NULL, NULL, '<h2>BOOKING CHANNEL POLICY</h2><ul><li><p>Full loyalty benefits apply primarily to direct bookings (nandinibali.com, email, WhatsApp).</p></li><li><p>Guests are encouraged to complete their member profile (email, birthday, preferences) to receive personalized offers.</p></li></ul>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 0, '2026-05-25 06:31:16', '2026-05-25 06:31:27'),
(35, 39, 'intro_text_section', NULL, NULL, NULL, '<h2>COMMUNICATION</h2><p><strong>Members will receive: </strong></p><ul><li><p>Post-stay points summary.</p></li><li><p>Tier upgrade or downgrade notifications.</p></li><li><p>Exclusive member communications and offers (opt-in required).</p></li></ul>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'soft_gray', 1, 0, '2026-05-25 06:32:45', '2026-05-25 06:33:01'),
(36, 39, 'intro_text_section', NULL, NULL, NULL, '<h2>TERMS &amp; CONDITIONS</h2><ul><li><p>All benefits are subject to availability and operational conditions.</p></li><li><p>Benefits are applicable only to the registered member during their stay.</p></li><li><p>Management reserves the right to amend, suspend, or terminate the loyalty program, benefits, or point structure with prior notice.</p></li><li><p>Misuse of the loyalty program may result in termination of membership.</p></li></ul>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 0, '2026-05-25 06:36:00', '2026-05-25 06:36:06'),
(37, 40, 'intro_text_section', 'Privilege Redemption', NULL, NULL, '<p>Earn Nandini Jungle Points every time you stay, dine, shop with partners, or use your card — on property.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', 'white', 1, 0, '2026-05-25 08:07:51', '2026-05-25 08:07:51'),
(38, 23, 'split_media_section', '1. Sleep, Reimagined', 'Tailored comfort, beyond five stars', NULL, '<p>We have gone beyond traditional luxury to ensure your sleep is nothing short of transformative. Our bedding is made from Egyptian cotton, with a 600 thread count and 780 GSM, more than triple the weight of standard hotel linens. Your sleep is important, and you will notice the difference.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-26 08:17:13', '2026-05-26 08:17:13'),
(39, 23, 'image_overlay_section', '2. Water, The Nandini Way', 'Better for you, and the planet', NULL, '<p>The water we serve is as pure as the experience we promise. Drawn from a natural spring beneath Nandini, it is mineral-rich, gently filtered, and bottled on-site at our certified treatment facility. Served in refillable glass bottles, it is not only safe and nourishing, but also kinder to the planet. No trucks. No plastic. No compromise.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'right', NULL, 1, 0, '2026-05-26 08:20:32', '2026-05-26 08:33:30'),
(40, 23, 'two_images_section', '3. SPA MOMENTS, NO SCHEDULE NEEDED', 'Peace comes to you', NULL, '<p>You do not need to leave your room to find deep relaxation. Guests staying in selected suites can enjoy professional massages or spa treatments in the privacy of their villa, at no extra charge. Whether it is a sunrise session on your Panoramic Jacuzzi Corner or an evening wind-down, peace comes to you.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-26 08:22:02', '2026-05-26 08:22:02'),
(41, 23, 'split_media_reverse', '4. TOWELS THAT EMBRACE YOU', 'Wrap yourself in luxury', NULL, '<p>A towel should do more than dry, it should indulge. Our 100x200 cm bath towels are made with 700 GSM cotton, a number that is hard to grasp in words, but the moment you wrap yourself in one, you will understand. Heavier, softer, and more absorbent than standard luxury towels, they turn a simple shower into a spa ritual.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-26 08:22:48', '2026-05-26 08:22:48'),
(42, 23, 'split_media_section', '5. NATURE IN EVERY SIP', 'Garden-grown, villa-served', NULL, '<p>At Nandini, flavor begins in the garden. Wild ginger, kecombrang, fragrant herbs and other flora are handpicked from our own gardens and brought straight into your cocktails, teas, and dishes. To make the experience even more personal, our bartender can craft your drink of choice right in your villa, using the freshest flavours of the day.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-26 08:23:29', '2026-05-26 08:23:29'),
(43, 23, 'image_overlay_section', '6. A Pool Beyond the Ordinary', 'Purified and heated to perfection', NULL, '<p>Fed by our own spring water, the Nandini pool is purified using an innovative silver and copper system with minimal chemical additives. The result is a pool that is cleaner, more sustainable, and gentler on your skin. The pool is also heated, allowing guests to enjoy a comfortable swim at any time of day, regardless of season or mountain breeze. The water is soothing and inviting, without the sharp scent of chlorine or irritation on the skin. Clean, calming, and deeply restorative, it is as comforting as stepping into a warm bath, surrounded by the rain forest.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', NULL, 1, 0, '2026-05-26 08:24:14', '2026-05-26 08:34:23'),
(44, 23, 'split_media_section', '7. PILLOWS, YOUR CHOICE', 'As soft or firm as you like it', NULL, '<p>Sleep is personal. That&#039;s why we offer a curated selection of pillows, tailored to suit your unique preferences, from cloud-like softness to structured firmness. For guests seeking elevated support, we&#039;re pleased to offer also the Pillow Pedic, a thoughtfully engineered orthopedic pillow designed to cradle the neck and align the spine for truly restorative rest. Because great days start with better nights.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-26 08:24:54', '2026-05-26 08:24:54'),
(45, 23, 'split_media_reverse', '8. DESIGN TOUCHES', NULL, NULL, '<p>Pieces throughout the resort are designed by world- renowned studios like BLINK and OT Design. Thoughtfully placed, they blend Balinese tradition with contemporary form, adding quiet moments of beauty, story, and soul to your stay.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-26 08:25:22', '2026-05-26 08:25:22'),
(46, 23, 'split_media_section', '9. Free One-Time Photography', 'Your moments, beautifully captured', NULL, '<p>Some memories deserve more than a selfie. As part of your stay, enjoy a complimentary one-time photography session in the privacy of your villa.<br><br>Our professional photographer will capture natural, elegant moments within your villa area — whether it is a quiet morning by the pool, a romantic afternoon on your terrace, or a golden-hour embrace overlooking the jungle.<br><br>No extra arrangements. No additional cost. Just timeless memories, thoughtfully preserved for you.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-26 08:26:35', '2026-05-26 08:26:35'),
(47, 7, 'split_media_section', 'Honeymoon Packages - 4 Days 3 Nights', NULL, NULL, '<p>Discover an oasis of love at Nandini Jungle by Hanging Gardens, acclaimed as Bali&#039;s best honeymoon retreat, where an exceptionally romantic ambiance awaits within the secluded haven of Bali&#039;s rainforest.</p>', NULL, NULL, NULL, 'Discover', 'manual', '/honeymoon/honeymoon-packages-4-days-3-nights', 'honeymoon.show', 'center', NULL, 1, 0, '2026-05-26 08:47:59', '2026-05-27 01:25:32'),
(48, 4, 'dining_information_section', NULL, NULL, '<p><strong>Contact Us:</strong></p><p><a href=\"https://wa.me/6281236871170\" target=\"_blank\">+62 812-3687-1170<br>(Whatsapp Enabled)</a></p><p></p><p><strong>Email Us:</strong></p><p><a href=\"mailto:reservation@nandinibali.com\">reservation@nandinibali.com</a></p>', '<p><strong>Cuisine:</strong></p><p>Western and Indonesian</p><p></p><p><strong>Opening times:</strong></p><p>Breakfast: 07:00 am to 10:30 am<br>Lunch: 12:00 pm to 03:00 pm<br>Dinner: 06:30 pm to 10:30 pm</p>', '[{\"url\": \"https://cho.pe/wildginger.web\", \"label\": \"Reserve Now\"}, {\"url\": \"https://drive.google.com/file/d/1XwHnNgEreiCA4mexe65GOc44Q9WSRSsg/view?usp=sharing\", \"label\": \"View Menu\"}, {\"url\": \"https://drive.google.com/file/d/16XoyEOdlRzFfN2Ca30THHhNfw8OCxWDN/view?usp=sharing\", \"label\": \"Premium Menu\"}, {\"url\": \"https://drive.google.com/file/d/1Xm5YhSbX18muQQTdrLvNLYd7cgFw5EaS/view?usp=sharing\", \"label\": \"Beverage List\"}]', NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-27 02:09:28', '2026-05-27 02:53:43'),
(49, 4, 'three_images_section', 'Wild Ginger Restaurant', NULL, NULL, '<p>Nestled in the heart of the jungle, this dining haven offers a blend of authentic local flavors and international cuisine. With breathtaking views and a warm, inviting atmosphere, each dish celebrates fresh, seasonal ingredients and the rich heritage of Balinese gastronomy. Enjoy an unforgettable meal surrounded by nature&#039;s beauty.</p>', NULL, NULL, NULL, 'Reserve a Table', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 02:35:49', '2026-05-27 02:39:14'),
(50, 4, 'split_media_section', 'World-Class Wine Cellar Selection', NULL, NULL, '<p>Nandini Jungle by Hanging Gardens meticulously curated wine collection, sourced from prestigious vineyards around the globe, promises an unforgettable vinicultural voyage guided by expert sommeliers. It&#039;s a haven for your senses, where nature&#039;s symphony blends with the exquisite notes of a world-class wine cellar selection.</p>', NULL, NULL, NULL, 'Reserve a Table', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 02:40:39', '2026-05-27 02:43:50'),
(51, 4, 'split_media_reverse', 'Bar & Lounge', NULL, NULL, '<p>Unwind at the Bar &amp; Lounge at Nandini Jungle by Hanging Gardens, where relaxation meets elegance. Enjoy handcrafted cocktails, fine wines, and refreshing beverages surrounded by lush jungle views. Perfect for a serene evening or a social gathering, the Bar &amp; Lounge offers a cozy ambiance and a touch of tropical luxury</p>', NULL, NULL, NULL, 'Reserve a Table', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 02:43:09', '2026-05-27 02:43:46'),
(52, 4, 'split_media_section', 'Afternoon Tea in the Heart of the Jungle', NULL, NULL, '<p>Indulge in a serene Afternoon Tea experience at the Lounge and Bar of Nandini Jungle by Hanging Gardens, offered exclusively to our cherished guests. From 3:00 PM to 5:00 PM, unwind with a handpicked selection of premium teas and an assortment of delectable treats, all surrounded by the breathtaking beauty of the jungle.</p>', NULL, NULL, NULL, 'Reserve a Table', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 02:45:10', '2026-05-27 02:45:10'),
(53, 4, 'image_overlay_section', 'Signature Dish – \"Nasi Jinggo One Hundred Dollars\"', NULL, NULL, '<p>Nasi Jinggo offers the authentic ﬂavors of Bali with a blend of distinctive spices like spicy and savory sambal. This food is popular as a light snack or convenient meal that can be enjoyed anytime, whether it&#039;s breakfast, lunch or dinner. You&#039;ll also find grilled pork ribs with peanut soy sauce, pan seared tuna with kecombrang salsa, and pepes ikan kemangi completing your Bali dining experience.</p>', NULL, NULL, NULL, 'Reserve a Table', 'manual', 'https://wa.me/6281236871170', NULL, 'right', NULL, 1, 0, '2026-05-27 02:46:33', '2026-05-27 02:46:33'),
(54, 6, 'spa_information_section', NULL, NULL, '<p><strong>Contact Us:</strong></p><p><a href=\"https://wa.me/6281236871170\" target=\"_blank\">+62 812-3687-1170<br>(Whatsapp Enabled)</a></p><p></p><p><strong>Email Us:</strong></p><p><a href=\"mailto:reservation@nandinibali.com\">reservation@nandinibali.com</a></p>', '<p><strong>Booking:</strong></p><p>Advance booking recommended</p><p></p><p><strong>Opening times:</strong></p><p>09:00 am to 10:00 pm</p>', '[{\"label\":\"View Menu\",\"url\":\"https:\\/\\/drive.google.com\\/file\\/d\\/1psCG6CoweiuESj81zV3DLrCdg2-HJUNE\\/view\"}]', NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 0, '2026-05-27 03:09:45', '2026-06-28 14:28:03'),
(55, 6, 'two_images_section', 'Essence Spa', NULL, NULL, '<p>Essence Spa is a serene retreat nestled deep within Bali&#039;s lush tropical jungle. This spa offers a rejuvenating escape, combining traditional Balinese healing rituals with the natural tranquility of its surroundings. Guests can indulge in treatments that incorporate local herbs, aromatic oils, and ancient techniques, all performed in open-air pavilions overlooking cascading green canopies and the soothing Ayung River below.</p>', NULL, NULL, NULL, 'Book Now', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 05:30:43', '2026-05-27 05:30:43'),
(56, 6, 'split_media_reverse', 'Spa Jaccuzi', NULL, NULL, '<p>Surrounded by the lush greenery and the sounds of nature, our Spa Jacuzzi provides the perfect sanctuary for unwinding and reconnecting with your inner peace. Ideal for guests seeking tranquility and indulgence, this unique feature elevates your spa journey to an unforgettable escape.</p>', NULL, NULL, NULL, 'Book Now', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 05:32:01', '2026-05-27 05:32:01'),
(57, 6, 'split_media_section', 'Wine Spa', NULL, NULL, '<p>This signature treatment harnesses the rejuvenating power of wine extracts, rich in antioxidants, to revitalize and soften the skin. Set in the heart of the tranquil jungle, the experience envelops you in luxury and serenity, promoting deep relaxation and a sense of renewal.</p>', NULL, NULL, NULL, 'Book Now', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 05:37:16', '2026-05-27 06:12:22'),
(58, 6, 'image_overlay_section', 'Spa by the River', NULL, NULL, '<p>This unique riverside spa provides an unparalleled connection to nature, offering a serene escape where body and spirit are rejuvenated. Let the gentle rhythm of the river guide you to ultimate relaxation and renewal.</p>', NULL, NULL, NULL, 'Book Now', 'manual', 'https://wa.me/6281236871170', NULL, 'left', NULL, 1, 0, '2026-05-27 05:46:31', '2026-05-27 05:46:44'),
(59, 8, 'split_media_section', 'Wedding By the River', NULL, NULL, '<p>The magical wedding in our secret Ayung river at Payangan, Ubud. With green rolling hills, a gentle river, and fresh atmosphere of Ubud rainforest. It can be a laughter-filled day at the spa with your bridal party, two people sharing vows amid a tree-shaded forest, or an after-party where night somehow turns into day. Our dreamlike venues and stunning location are backed by a culinary team who can design a custom menu for your special day. Invite your guests to experience an unmatched destination-wedding holiday in Bali.</p>', NULL, NULL, NULL, 'Inquire Now', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 07:14:28', '2026-05-27 07:14:28'),
(60, 8, 'split_media_reverse', 'Wedding by the Chapel', NULL, NULL, '<p>There’s something truly special about saying “I do” surrounded by nature’s quiet beauty. At Nandini Bali, our jungle chapel offers an intimate and unforgettable setting for your wedding—where forest views, and fresh blooms come together in harmony.<br><br>This is where your story begins—surrounded by loved ones, your ceremony becomes more than a ritual; it becomes a cherished memory that will stay with you forever.<br><br>Let us help bring your vision to life, with every detail thoughtfully arranged to reflect your story, your love, and your dreams.</p>', NULL, NULL, NULL, 'Inquire Now', 'manual', 'https://wa.me/6281236871170', NULL, 'center', NULL, 1, 0, '2026-05-27 07:15:14', '2026-05-27 07:15:14'),
(61, 25, 'intro_text_section', NULL, NULL, NULL, '<h2><strong>1) What is Nandini Jungle by Hanging Gardens, and where is it located?</strong></h2><p>Nandini Jungle by Hanging Gardens is a luxury hideaway set in the rainforest outside <strong>Ubud, Bali, Indonesia</strong>. The resort overlooks jungle and river valleys, offering accommodation, spa, dining, and immersive nature experiences. Learn more about our story and setting on our <a href=\"https://nandinibali.com/about-us\"><strong>About Us</strong></a> page.<br><br></p><h2><strong>2) Why choose Nandini Jungle over other luxury resorts in Ubud?</strong></h2><p>Nandini Jungle combines an intimate scale, a secluded jungle location, and a focus on wellness. Guests choose us for tranquility, panoramic rainforest views, personalized hospitality, spa rituals, cooking classes, and guided walks, with easy access to Ubud’s cultural scene. Discover more on our <a href=\"https://nandinibali.com/experiences\"><strong>Experiences</strong></a> page.<br><br></p><h2><strong>3) How far is Ubud town center, and how do I get there?</strong></h2><p>It usually takes <strong>30–40 minutes by car</strong> to reach Ubud center depending on traffic. Our reception can arrange transfers and excursions. <a href=\"https://nandinibali.com/contact-us\"><strong>Contact us</strong></a> for options.<br><br></p><h2><strong>4) How do I get from Bali’s airport (DPS) to Nandini Jungle?</strong></h2><p>From <strong>Ngurah Rai International Airport (DPS)</strong>, the transfer typically takes around <strong>90 minutes by car</strong>. Booking an airport transfer with us is the most convenient option. Arrange your transfer through our <a href=\"https://nandinibali.com/contact-us\"><strong>Contact Us</strong></a> page.<br><br></p><h2><strong>5) When is the best time of year to visit Ubud?</strong></h2><p>Bali is tropical year-round. <strong>April–October</strong> is drier, ideal for trekking and outdoor activities. <strong>November–March</strong> is greener, quieter, and features short tropical showers. Explore our <a href=\"https://nandinibali.com/offers\"><strong>Current Offers</strong></a> to find the right time for you.<br><br></p><h2><strong>6) What room types do you offer? Do they have jungle views and outdoor spaces?</strong></h2><p>Our rooms and suites are designed to connect with nature, many featuring <strong>jungle views</strong> and <strong>private balconies or terraces</strong>. Explore our <a href=\"https://nandinibali.com/villas\"><strong>Villas</strong></a> and our <a href=\"https://nandinibali.com/suites\"><strong>Suites</strong></a>—or why not stay at our <a href=\"https://nandinibali.com/suite/villa-presidential-suite\"><strong>Presidential Suite</strong></a>, the largest hotel room in Bali!<br><br></p><h2><strong>7) Do you offer spa treatments, yoga, and meditation?</strong></h2><p>Yes. Our therapists provide <strong>Balinese spa treatments</strong>, and <strong>yoga/meditation sessions</strong> are available daily in natural settings. Explore our <a href=\"https://nandinibali.com/spa-wellness\"><strong>Spa and Wellness</strong></a> page for details.<br><br></p><h2><strong>8) Can guests join cooking classes or other authentic experiences?</strong></h2><p>Yes, we host <strong>Balinese cooking classes</strong>, where our executive chef Gustu brings his philosophy to heart and invites all our guests to enjoy the excellence of Balinese cooking made by themselves. See all our experiences <a href=\"https://nandinibali.com/experiences\"><strong>here</strong></a>.<br><br></p><h2><strong>9) Is the resort family-friendly? Do you have quiet zones for couples or honeymooners?</strong></h2><p>We welcome <strong>families</strong> and <strong>couples</strong>. Share your purpose of stay (honeymoon, family trip) and we’ll recommend the best room and activities. Learn more about our <a href=\"https://nandinibali.com/honeymoon\"><strong>Honeymoon</strong></a> experience.<br><br></p><h2><strong>10) How does Nandini Jungle support sustainability?</strong></h2><p>We reduce plastic, prioritize <strong>local produce</strong>, train our team in <strong>resource efficiency</strong>, and partner with local communities. Read about our initiatives on our <a href=\"https://nandinibali.com/sustainability\"><strong>Sustainability</strong></a> page.<br><br></p><h2><strong>11) How accessible is the resort for guests with limited mobility?</strong></h2><p>The hillside terrain is <strong>steep</strong>, with stairs and slopes in some areas. <a href=\"https://nandinibali.com/contact-us\"><strong>Contact us</strong></a> before booking so we can recommend the most suitable rooms.<br><br></p><h2><strong>12) What packages and offers are available right now?</strong></h2><p>We publish promotions <strong>on our website</strong> and via newsletters. See our <a href=\"https://nandinibali.com/offers\"><strong>Offers</strong></a> page for the latest and sign up for our newsletter at the bottom of the <a href=\"https://nandinibali.com\"><strong>home page</strong></a>.<br><br></p><h2><strong>13) Can you arrange transfers from other parts of Bali?</strong></h2><p>Yes, we arrange <strong>private transfers</strong> across Bali. Contact us through our <a href=\"https://nandinibali.com/contact-us\"><strong>Contact page</strong></a> to book.<br><br></p><h2><strong>14) Do you host weddings, elopements, or private events?</strong></h2><p>Yes. We create <strong>intimate ceremonies</strong>,<strong> jungle-view dining experiences</strong>, and tailored events. Explore possibilities on our <a href=\"https://nandinibali.com/weddings\"><strong>Weddings</strong></a> page.<br><br></p><h2><strong>15) Do I need an adapter?</strong></h2><p>Bali uses <strong>Type C/F, 230V outlets</strong>. Bring an adapter if needed and <a href=\"https://nandinibali.com/contact-us\"><strong>contact us</strong></a> if you need any assistance.<br><br></p><h2><strong>16) Can you help plan a personalized stay (wellness-focused, nature + culture mix)?</strong></h2><p>Yes. Share your interests (<strong>yoga, trekking, cooking, temples, art</strong>) and we’ll design a tailored itinerary. Start planning via our <a href=\"https://nandinibali.com/contact-us\"><strong>Contact page</strong></a>, we are happy to help plan your perfect trip!<br><br></p><h2><strong>17) What are the top things to see and do in Bali?</strong></h2><p>Highlights include<strong> rice terraces, waterfalls, temples, Ubud’s arts scene</strong>, and <strong>the lush rainforest</strong>. For wellness and jungle immersion, explore our <a href=\"https://nandinibali.com/experiences\"><strong>Experiences</strong></a> page.</p><p></p><h2><strong>18) How safe is it to travel in Bali?</strong></h2><p>Bali is generally very safe for travelers. Use normal precautions and licensed transport.<br><br></p><h2><strong>19) Can I book special dining experiences at the resort?</strong></h2><p>Absolutely. Guests often enjoy <strong>private jungle-view dinners</strong>, romantic setups, or themed evenings featuring Balinese cuisine. Explore our <a href=\"https://nandinibali.com/dining\"><strong>Dining</strong></a> page or <a href=\"https://nandinibali.com/experiences\"><strong>Experiences</strong></a> page for options and let us know your preferences!<br><br></p><h2><strong>20) Can I combine a stay at Nandini Jungle with other destinations in Bali?</strong></h2><p>Yes. Many of our guests combine their rainforest stay with time on Bali’s beaches, cultural trips in Ubud, or mountain adventures near Mount Batur. We can arrange transfers and personalized itineraries to make your journey seamless. <a href=\"https://nandinibali.com/contact-us\"><strong>Contact us</strong></a> to start planning.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 0, '2026-05-29 03:23:16', '2026-05-29 03:29:56'),
(62, 1, 'contained_image_section', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'center', NULL, 1, 1, '2026-06-20 20:31:40', '2026-06-20 20:33:55');
INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `title`, `subtitle`, `excerpt`, `description`, `items`, `image`, `mobile_image`, `button_label`, `button_link_type`, `button_url`, `button_route`, `text_align`, `background_color`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(63, 31, 'seo_split_media_section', 'Why Choose a Jungle Resort in Ubud?', NULL, '<p></p>', '<p>Choosing a <strong>jungle resort in Ubud</strong> offers a completely different experience from staying at the beach.<br><br></p><h3><strong>1. Cooler Climate &amp; Tranquility</strong></h3><p>Unlike the busy southern coastline, Ubud’s elevated rainforest setting provides cooler temperatures and a naturally peaceful atmosphere. The sounds of waves are replaced by flowing river water and forest wildlife.<br><br></p><h3><strong>2. Secluded &amp; Romantic Environment</strong></h3><p>A Bali jungle resort offers privacy that beachfront hotels often cannot. Villas are tucked into the valley landscape, creating a sense of exclusivity ideal for couples and honeymooners.<br><br></p><h3><strong>3. Immersive Nature Experience</strong></h3><p>Instead of city lights and traffic, guests enjoy:</p><ul><li><p>Lush rainforest panoramas</p></li><li><p>Mist-covered valleys at sunrise</p></li><li><p>Elevated pathways through the trees</p></li><li><p>Deep connection to Bali’s spiritual environment</p></li></ul><p><br>For travelers seeking serenity, a jungle resort in Ubud delivers a more restorative stay.</p>', NULL, NULL, NULL, 'See Jungle View Villa', 'manual', 'https://nandinibali.com/jungle-villas/jungle-view-villa', NULL, 'left', NULL, 1, 0, '2026-06-26 17:48:06', '2026-06-26 18:30:22'),
(64, 31, 'seo_split_media_reverse', 'Private Villas Surrounded by Tropical Jungle', NULL, '<p></p>', '<p>Each villa at Nandini is positioned to capture sweeping valley views, making it one of the most scenic jungle villas in Bali.<br></p><p><br>Natural stone, warm wood textures, and traditional Balinese craftsmanship create a seamless flow between indoor comfort and the surrounding forest. Floor-to-ceiling openings invite daylight and fresh air inside, while private terraces overlook layers of tropical greenery.</p><p></p><p><br>Guests can enjoy:</p><ul><li><p>Private terraces facing the jungle</p></li><li><p>Spacious interiors with handcrafted details</p></li><li><p>Elevated views above the rainforest canopy</p></li><li><p>Peaceful evenings accompanied by forest sounds</p></li></ul><p></p><p>These jungle villas in Bali are designed not only for luxury, but for deep immersion in nature.</p>', NULL, NULL, NULL, 'See Panoramic Jungle View Villa', 'manual', 'https://nandinibali.com/jungle-villas/panoramic-jungle-view-villa', NULL, 'left', 'white', 1, 0, '2026-06-26 18:42:06', '2026-06-26 18:42:06'),
(65, 31, 'seo_split_media_section', 'Wellness and Spa Experiences in Nature', NULL, '<p></p>', '<p>As a true <strong>Ubud jungle resort</strong>, Nandini integrates wellness and cultural experiences into every stay.</p><h3><strong><br>Wellness &amp; Spiritual Experiences</strong></h3><ul><li><p>Sunrise yoga overlooking the valley</p></li><li><p>Guided river purification rituals</p></li><li><p>Jungle spa treatments inspired by Balinese healing traditions</p></li><li><p>Meditation sessions surrounded by forest stillness</p></li></ul><h3><strong><br>Cultural Immersion</strong></h3><p>Guests may also explore authentic Balinese traditions through curated cultural activities that celebrate Ubud’s heritage and artistry.<br><br>The surrounding valley becomes a living sanctuary, allowing travelers to reconnect with themselves while experiencing the soul of Bali.</p>', NULL, NULL, NULL, 'Our Wellness Activity', 'manual', 'https://nandinibali.com/experiences/jungle-wellness-spa-rituals', NULL, 'left', 'soft_gray', 1, 0, '2026-06-26 18:45:04', '2026-06-26 18:46:47'),
(66, 31, 'intro_text_section', NULL, NULL, NULL, '<h2>Why Travelers Choose Nandini</h2><p>This Bali jungle resort is ideal for:</p><ul><li><p>Honeymoon couples seeking romance and privacy</p></li><li><p>Wellness travelers pursuing calm and reflection</p></li><li><p>Nature lovers wanting forest immersion</p></li><li><p>Couples celebrating anniversaries</p></li><li><p>Travelers seeking a quieter alternative to beach destinations<br></p></li></ul><p>For those who value tranquility over crowds, an Ubud jungle resort provides a deeper, more meaningful escape.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 0, '2026-06-26 18:48:11', '2026-06-26 18:50:54'),
(67, 31, 'intro_text_section', NULL, NULL, NULL, '<h2><strong>Exclusive Direct Booking Benefits</strong></h2><p>Guests who book directly with Nandini Jungle by Hanging Gardens enjoy:</p><ul><li><p>Special direct booking rates</p></li><li><p>Priority villa allocation</p></li><li><p>Personalized pre-arrival assistance</p></li><li><p>Flexible arrangements when available</p></li><li><p>Thoughtful arrival touches inspired by Balinese hospitality</p></li></ul><p><br>Direct reservations ensure the best value while enhancing your overall jungle retreat experience.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'soft_gray', 1, 0, '2026-06-26 18:49:53', '2026-06-26 18:53:52'),
(68, 31, 'intro_text_section', NULL, NULL, NULL, '<h2><strong>FAQ</strong></h2><p><strong>What makes this a true Ubud jungle resort?</strong><br>Its hillside rainforest location, immersive nature setting, handcrafted villas, and wellness experiences create an authentic jungle stay in Ubud.<br><br><strong>Is staying in a jungle resort better than the beach in Bali?</strong><br>For travelers seeking privacy, cooler climate, and tranquility, a jungle resort in Ubud offers a more peaceful and intimate experience compared to coastal areas.<br><br><strong>Is this Bali jungle resort suitable for honeymoon?</strong><br>Yes. Many couples choose Nandini for honeymoons and romantic escapes due to its secluded villas and serene forest atmosphere.<br><br><strong>Do jungle resorts in Bali offer wellness activities?</strong><br>Guests can enjoy yoga, meditation, river purification rituals, and spa treatments inspired by traditional Balinese healing practices.<br><br><strong>How far is the resort from central Ubud?</strong><br>The resort is located in a quiet valley setting within the greater Ubud area, offering seclusion while remaining accessible to cultural attractions.<br><br><strong>When is the best time to stay in an Ubud jungle resort?</strong><br>Ubud is beautiful year-round, though many guests prefer the drier months for clearer valley views and outdoor experiences.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 0, '2026-06-26 18:51:26', '2026-06-26 18:53:24'),
(69, 34, 'seo_split_media_section', 'Why Ubud Is the Perfect Destination for a Wellness Retreat', NULL, '<p></p>', '<p>Ubud has built a global reputation as one of the best destinations for wellness travel. The area combines <strong>nature, culture, and holistic healing traditions</strong> that have been part of Balinese life for centuries.<br><br>Unlike busy beach destinations, Ubud offers a quieter atmosphere where visitors can truly slow down. Morning mist drifting through jungle valleys, the sound of birds and flowing rivers, and the gentle rhythm of village life create an environment naturally suited for healing and relaxation.<br><br>This unique setting makes Ubud an ideal place to focus on wellness practices such as:</p><ul><li><p>Yoga and meditation</p></li><li><p>Spa and holistic therapies</p></li><li><p>Mindful movement and breathing</p></li><li><p>Healthy cuisine and detox programs</p></li><li><p>Cultural experiences that nurture inner balance</p></li></ul><p>Many wellness retreats in Ubud combine these elements to create a complete experience designed to restore both body and mind.</p>', NULL, NULL, NULL, 'Book Exotic Spa Treatment', 'manual', 'https://nandinibali.com/spa-wellness', NULL, 'left', 'soft_gray', 1, 1, '2026-06-26 19:02:28', '2026-06-26 19:12:39'),
(70, 34, 'intro_text_section', NULL, NULL, NULL, '<h2>A Holistic Approach to Wellness</h2><p>A true wellness retreat focuses on more than physical relaxation. The goal is to achieve <strong>balance across mind, body, and spirit</strong>.<br>Programs typically integrate several key elements:</p><h3><strong><br>Yoga and Mindful Movement</strong></h3><p>Daily yoga sessions help improve flexibility, reduce stress, and reconnect the body with breath and movement. Practicing yoga in an open-air jungle pavilion adds a calming dimension to the experience.</p><h3><strong><br>Meditation and Inner Reflection</strong></h3><p>Guided meditation sessions encourage stillness and clarity. Whether practiced at sunrise or sunset, meditation in nature allows guests to reconnect with themselves away from daily distractions.</p><h3><strong><br>Spa and Healing Rituals</strong></h3><p>Balinese healing traditions are deeply rooted in the island’s culture. Wellness retreats often include spa treatments inspired by these traditions, featuring natural ingredients such as herbs, flowers, and essential oils.</p><p><br>Massage therapies, body scrubs, and aromatic rituals help release tension while promoting deep relaxation.</p><h3><strong><br>Nourishing Cuisine</strong></h3><p>Healthy cuisine is an essential part of any wellness journey. Many retreats offer menus designed to support vitality, focusing on fresh ingredients, balanced nutrition, and mindful eating.</p><p><br>Meals often highlight locally sourced produce and traditional Indonesian flavors presented in a healthy, nourishing way.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 4, '2026-06-26 19:03:58', '2026-06-26 19:12:39'),
(71, 34, 'seo_split_media_reverse', 'The Power of Nature in Ubud', NULL, '<p></p>', '<p>One of the most transformative aspects of an Ubud wellness retreat is the <strong>natural environment itself</strong>.</p><p><br>Unlike urban wellness centers, retreats in Ubud are often surrounded by dense jungle, rice fields, and flowing rivers. This connection with nature helps reduce stress levels and encourages a deeper sense of calm.</p><p><br>Simply waking up to the sounds of the rainforest, breathing fresh tropical air, and watching sunlight filter through the trees can be a powerful part of the healing process.</p><p><br>Many wellness retreats incorporate outdoor experiences such as:</p><ul><li><p>Jungle walks</p></li><li><p>Rice field cycling</p></li><li><p>River meditation sessions</p></li><li><p>Sunrise yoga overlooking the valley</p></li></ul><p><br>These activities allow guests to reconnect with nature while gently nourishing the body.</p>', NULL, NULL, NULL, 'Book Sunrise Cycling', 'manual', 'https://nandinibali.com/experience/from-bike-trails-to-bar-skills', NULL, 'left', 'white', 1, 2, '2026-06-26 19:07:08', '2026-06-26 19:12:39'),
(72, 34, 'seo_split_media_section', 'Cultural Experiences that Enrich the Journey', NULL, '<p></p>', '<p>Wellness in Bali is deeply connected to culture and spirituality. Many retreats include cultural activities that help visitors better understand the island’s traditions.<br></p><p>These experiences might include:</p><ul><li><p>Balinese offering making workshops</p></li><li><p>Traditional cooking classes</p></li><li><p>Temple visits and cultural excursions</p></li><li><p>Local art and craft experiences</p></li></ul><p><br>Participating in these traditions offers a meaningful way to connect with the island while enriching the overall retreat experience.</p>', NULL, NULL, NULL, 'Book A Cooking Class', 'manual', 'https://nandinibali.com/experience/cooking-class', NULL, 'left', 'soft_gray', 1, 3, '2026-06-26 19:09:57', '2026-06-26 19:12:39'),
(73, 34, 'intro_text_section', NULL, NULL, NULL, '<h2>A Sanctuary for Relaxation and Renewal</h2><p>Accommodation plays an important role in the retreat experience. Many wellness retreats in Ubud offer <strong>private villas or tranquil suites surrounded by nature</strong>.</p><p><br>These spaces are designed to create a peaceful sanctuary where guests can rest between activities. Large windows, natural materials, and open views of the jungle landscape enhance the sense of serenity.</p><p><br>Whether relaxing by a private pool, enjoying a spa treatment, or simply listening to the sounds of nature, every moment becomes part of the wellness journey.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'soft_gray', 1, 5, '2026-06-26 19:11:31', '2026-06-26 19:13:03'),
(74, 34, 'intro_text_section', NULL, NULL, NULL, '<h2>Who Is an Ubud Wellness Retreat For?</h2><p>A wellness retreat in Ubud can benefit many types of travelers, including:</p><ul><li><p>Individuals seeking stress relief and relaxation</p></li><li><p>Couples looking for a peaceful getaway</p></li><li><p>Travelers interested in yoga and mindfulness</p></li><li><p>Guests wanting to reconnect with nature</p></li><li><p>Anyone seeking balance and rejuvenation</p></li></ul><p><br>You do not need prior experience with wellness programs to enjoy a retreat. Many experiences are designed to be accessible for beginners while still offering depth for experienced practitioners.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'white', 1, 6, '2026-06-26 19:11:50', '2026-06-26 19:13:17'),
(75, 34, 'intro_text_section', NULL, NULL, NULL, '<h2>Begin Your Wellness Journey in Ubud</h2><p>An <strong>Ubud wellness retreat</strong> offers the rare opportunity to step away from everyday routines and focus entirely on well-being.</p><p><br>Surrounded by Bali’s lush jungle landscape, guided by holistic practices, and supported by nourishing cuisine and healing traditions, guests can rediscover balance and clarity in a truly inspiring setting.</p><p><br>Whether you are looking to restore your energy, reconnect with nature, or simply enjoy a peaceful escape, Ubud provides the perfect environment to begin your wellness journey.</p>', NULL, NULL, NULL, NULL, 'manual', NULL, NULL, 'left', 'soft_gray', 1, 7, '2026-06-26 19:12:13', '2026-06-26 19:13:27');

