INSERT INTO `spas` (`id`, `title`, `slug`, `subtitle`, `excerpt`, `description`, `hero_image`, `hero_image_alt`, `hero_mobile_image`, `hero_mobile_image_alt`, `card_image`, `card_image_alt`, `valid_start_date`, `valid_end_date`, `button_label`, `button_url`, `booking_url_override`, `meta_title`, `meta_description`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, '2-Day Balinese Wellness Escape', '2-day-balinese-wellness-escape', NULL, 'A two-day Balinese wellness escape designed to restore balance, soften the body, and renew the senses through traditional massage, flower bath ritual, body scrub, and pure nature facial treatments.', '<p>A two-day Balinese wellness escape designed to restore balance, soften the body, and renew the senses through traditional massage, flower bath ritual, body scrub, and pure nature facial treatments.</p><p></p><h2>DAY 1 - GROUNDING THE BODY “AS YOU ARRIVE IN THE JUNGLE, THE EARTH WELCOMES YOU.”</h2><p><strong>EXOTIC BALINESE MASSAGE (90 MIN)</strong><br>Gentle stretching, rolling, and deep kneading to release travel fatigue and ground the body.</p><p><strong>AROMATHERAPY FLOWER BATH (15 MIN)</strong><br>A symbolic cleansing ritual inspired by Balinese purification traditions.</p><p><em>The body softens, the breath slows, and the jungle begins its quiet healing.</em></p><h2>DAY 2 - AWAKENING THE GLOW “NATURE RESTORES WHAT THE WORLD HAS TAKEN AWAY.”</h2><p><strong>TRADITIONAL LULUR BODY SCRUB (30 MIN)</strong><br>Inspired by royal Balinese pre-wedding rituals to cleanse and brighten the skin.</p><p><strong>PURE NATURE FACIAL (60 MIN)</strong><br>Using cucumber, honey, yogurt, and oatmeal to refresh and nourish naturally.</p><p><em>You depart feeling radiant, calm, and gently renewed.</em></p>', 'spas/hero/68d37345-f6e6-4f1d-a962-725cf049fe62.webp', '2-Day Balinese Wellness Escape', 'spas/hero-mobile/b0c38891-a675-4d73-a08b-f02f55e3e31b.webp', '2-Day Balinese Wellness Escape', NULL, NULL, NULL, NULL, 'Book Now', 'https://wa.me/6281236871170', NULL, '2-Day Balinese Wellness Escape | Nandini Jungle Spa', 'Restore balance with a 2-day Balinese wellness escape at Nandini Jungle Spa, featuring massage, flower bath, body scrub, and pure nature facial treatments.', 0, 1, 1, '2026-05-27 03:23:45', '2026-05-27 05:16:11'),
(2, '3-Day Inner Harmony Retreat', '3-day-inner-harmony-retreat', NULL, 'A three-day inner harmony retreat designed to calm the body, cleanse the skin, and restore balance through Balinese massage, flower bath ritual, body scrub, body mask, facial treatment, herbal tea, and foot reflexology.', '<p>A three-day inner harmony retreat designed to calm the body, cleanse the skin, and restore balance through Balinese massage, flower bath ritual, body scrub, body mask, facial treatment, herbal tea, and foot reflexology.</p><h2>DAY 1 - GROUNDING &amp; RELAXATION “THE JUNGLE SLOWS YOUR RHYTHM.”</h2><p><strong>EXOTIC BALINESE MASSAGE (90 MIN)</strong><br>Gentle stretching, rolling, and deep kneading to release travel fatigue and ground the body.</p><p><strong>AROMATHERAPY FLOWER BATH (15 MIN)</strong><br>A symbolic cleansing ritual inspired by Balinese purification traditions.</p><p><em>Muscles release, thoughts soften.</em></p><h2>DAY 2 - CLEANSING &amp; RENEWAL “OLD ENERGY IS GENTLY WASHED AWAY.”</h2><p><strong>GREEN TEA OR COCONUT BODY SCRUB (30 MIN)</strong><br>Antioxidant-rich exfoliation inspired by natural island remedies.</p><p><strong>JUNGLE BODY MASK – PAPAYA OR MILK (30 MIN)</strong><br>To nourish, hydrate, and restore skin vitality.</p><p><strong>HERBAL TEA</strong></p><p><em>The skin glows, energy begins to flow freely.</em></p><h2>DAY 3 - HARMONY &amp; LIGHTNESS “BALANCE IS FELT, NOT FORCED.”</h2><p><strong>PURE NATURE FACIAL OR BIO REJUVENATION FACIAL (60 MIN)</strong></p><p><strong>FOOT REFLEXOLOGY (60 MIN)</strong><br>Stimulating pressure points to harmonize the entire body.</p><p><em>You leave centered, lighter, and deeply rested.</em></p>', 'spas/hero/b5490cd9-d622-4ce2-b483-992ef4ea0c3c.webp', '3-Day Inner Harmony Retreat', 'spas/hero-mobile/b3958880-8e8d-46ce-ae26-4890e807f5e9.webp', '3-Day Inner Harmony Retreat', NULL, NULL, NULL, NULL, 'Book Now', 'https://wa.me/6281236871170', NULL, '3-Day Inner Harmony Retreat | Nandini Jungle Spa', 'Reconnect with balance through a 3-day inner harmony retreat at Nandini Jungle Spa, featuring Balinese massage, flower bath, body scrub, facial, and reflexology.', 0, 1, 2, '2026-05-27 03:26:16', '2026-05-27 05:20:20'),
(3, '4-Day Deep Balinese Wellness Immersion', '4-day-deep-balinese-wellness-immersion', NULL, 'A four-day deep Balinese wellness immersion designed to restore the body and calm the mind through Balinese massage, flower bath ritual, body scrub, body mask, stone therapy, scalp treatment, facial, and reflexology.', '<p>A four-day deep Balinese wellness immersion designed to restore the body and calm the mind through Balinese massage, flower bath ritual, body scrub, body mask, stone therapy, scalp treatment, facial, and reflexology.</p><h2>DAY 1 - ARRIVAL &amp; GROUNDING “THE EARTH RECEIVES YOU.”</h2><p><strong>EXOTIC BALINESE MASSAGE (90 MIN)</strong><br>Gentle stretching, rolling, and deep kneading to release travel fatigue and ground the body.</p><p><strong>AROMATHERAPY FLOWER BATH (15 MIN)</strong><br>A symbolic cleansing ritual inspired by Balinese purification traditions.</p><p><em>A gentle welcome into stillness.</em></p><h2>DAY 2 - CLEANSING THE BODY “NATURE RENEWS FROM THE OUTSIDE IN.”</h2><p><strong>TRADITIONAL LULUR OR GREEN TEA BODY SCRUB (30 MIN)</strong></p><p><strong>JUNGLE BODY MASK – ALOE AVOCADO OR MILK (30 MIN)</strong></p><p><strong>HERBAL TEA</strong></p><p><em>Skin is nourished, tension slowly dissolves.</em></p><h2>DAY 3 - ENERGY &amp; DEEP RELEASE “ENERGY FLOWS WHERE ATTENTION RESTS.”</h2><p><strong>STONE THERAPY (90 MIN)</strong><br>Using sacred river stones to release deep muscular tension.</p><p><strong>SHINING GLORY HAIR &amp; SCALP TREATMENT (30 MIN)</strong><br>A traditional herbal oil ritual for crown and mind clarity.</p><p><em>The body feels aligned, the mind clear.</em></p><h2>DAY 4 - HARMONY &amp; COMPLETION “YOU RETURN TO THE WORLD WHOLE.”</h2><p><strong>PURE NATURE FACIAL OR BIO REJUVENATION FACIAL (60 MIN)</strong></p><p><strong>REFLEXOLOGY OR FEET SPA (60 MIN)</strong></p><p><em>A final ritual to restore balance before departure.</em></p>', 'spas/hero/19d9f7d8-6a93-422d-8a13-b333a2384ff8.webp', '4-Day Deep Balinese Wellness Immersion', 'spas/hero-mobile/48ba71cb-273c-47e0-b722-61c59611d293.webp', '4-Day Deep Balinese Wellness Immersion', NULL, NULL, NULL, NULL, 'Book Now', 'https://wa.me/6281236871170', NULL, '4-Day Deep Balinese Wellness Immersion | Nandini Jungle Spa', 'Experience a 4-day Balinese wellness immersion at Nandini Jungle Spa with massage, flower bath, body scrub, stone therapy, scalp treatment, facial, and reflexology.', 0, 1, 3, '2026-05-27 03:28:34', '2026-05-27 05:24:00'),
(4, 'A Mystical Journey at Nandini - 4D3N Wellness Retreat', 'a-mystical-journey-at-nandini-4d3n-wellness-retreat', NULL, 'Discover the spiritual essence of Bali with our exclusive Nandini Wellness Retreat, nestled in the heart of the jungle at our luxury jungle resort in Bali, along the sacred Ayung River.', '<p>Discover the spiritual essence of Bali with our exclusive Nandini Wellness Retreat, nestled in the heart of the jungle at our luxury jungle resort in Bali, along the sacred Ayung River. Revered for its mystical energy, the Ayung River will be your companion as you unwind, heal, and reconnect with yourself and nature over four transformative days in one of the best wellness retreats in Bali.</p><h2>Day 1: A Warm Welcome to Paradise</h2><p>Your wellness journey begins as you arrive at Nandini Jungle, a premier Ubud jungle resort, greeted with a truly Balinese welcome while you unwind with a 30-minute express massage. As the evening descends, indulge in a dinner experience where every dish celebrates the vibrant flavors of the tropics.</p><h2>Day 2: A Day of Exploration and Sacred Rituals</h2><p>Awaken to the sounds of nature as your second day begins with a refreshing guided morning trek, followed by our signature À la carte &amp; Mezze Breakfast, a delightful spread of locally sourced ingredients to fuel your body for the day ahead.</p><p>Your spiritual journey deepens with a Melukat Purification Ceremony, a traditional Balinese ritual led by a revered local priest. As you bathe in the sacred holy water of the Ayung River, feel your spirit cleansed and renewed.</p><p>Enjoy a serene set menu lunch before resting. Later in the afternoon, unwind with Afternoon Tea at the A’Lang Bar &amp; Lounge, and further your relaxation with a soothing 60-minute reflexology session, ensuring a deep sense of peace and balance, followed by a hearty dinner.</p><h2>Day 3: Flow with the River’s Energy</h2><p>The mystical energy of the Ayung River sets the tone for a rejuvenating morning Ashtanga yoga session on the river deck. After another nourishing À la carte &amp; Mezze Breakfast, the healing continues with a spa treatment by the river, where the sacred waters enhance your wellness retreat experience. The day closes with a serene Sunset Yoga session at Djiwa Shala. As the sun sets behind the lush canopy, allow your body to stretch and your mind to quieten, paving the way for a restful evening.</p><h2>Day 4: A Tranquil Farewell</h2><p>On your final morning, find peace with a meditation session by the pool, followed by a nourishing breakfast. As your healing &amp; wellness retreat comes to a close, bid farewell to Nandini Jungle Resort, carrying the calm and healing energy of this sacred place with you.</p><p>Join us on this transformative journey and discover the magic of the sacred water and Balinese healing traditions with one of the best health &amp; wellness retreat packages, where the lush Ubud jungle and the mystical Ayung River meets to reinvigorate your soul.</p>', 'spas/hero/53c39f42-9deb-4263-b9a0-7d92b84b310b.webp', 'A Mystical Journey at Nandini - 4D3N Wellness Retreat', 'spas/hero-mobile/ec534c54-f664-4088-a6f1-884ce1576d10.webp', 'A Mystical Journey at Nandini - 4D3N Wellness Retreat', NULL, NULL, NULL, NULL, 'Book Now', 'https://nandinijunglebyhanginggardens.reserve-online.net/?checkin=2026-05-27&nights=3&bkcode=wellness&rate=', NULL, '4D3N Wellness Retreat in Bali | Nandini Jungle Resort', 'Discover a 4D3N wellness retreat at Nandini Jungle by Hanging Gardens, where Bali’s jungle, Ayung River, and spiritual healing create a transformative escape.', 0, 1, 4, '2026-05-27 03:30:53', '2026-05-27 05:27:00');

