CREATE TABLE `synced_webhotelier_bookings` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `member_id` bigint(20) UNSIGNED DEFAULT NULL,
  `member_assigned_manually` tinyint(1) NOT NULL DEFAULT 0,
  `booking_number` varchar(191) NOT NULL,
  `guest_name` varchar(191) DEFAULT NULL,
  `email` varchar(191) NOT NULL,
  `phone` varchar(191) DEFAULT NULL,
  `check_in` date DEFAULT NULL,
  `check_out` date DEFAULT NULL,
  `rooms` int(10) UNSIGNED DEFAULT NULL,
  `room_type` varchar(191) DEFAULT NULL,
  `room_name` varchar(191) DEFAULT NULL,
  `rate_name` varchar(191) DEFAULT NULL,
  `currency` varchar(10) DEFAULT NULL,
  `room_subtotal` decimal(14,2) DEFAULT NULL,
  `booking_total` decimal(14,2) DEFAULT NULL,
  `status` varchar(191) DEFAULT NULL,
  `source_name` varchar(191) DEFAULT NULL,
  `affiliate_code` varchar(255) DEFAULT NULL,
  `remote_updated_at` timestamp NULL DEFAULT NULL,
  `last_synced_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

