CREATE TABLE `vouchers` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `voucher_category_id` bigint(20) UNSIGNED DEFAULT NULL,
  `experience_id` bigint(20) UNSIGNED DEFAULT NULL,
  `title` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `sku` varchar(191) DEFAULT NULL,
  `excerpt` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `inclusions` longtext DEFAULT NULL,
  `terms_conditions` longtext DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `card_image` varchar(191) DEFAULT NULL,
  `gallery_images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gallery_images`)),
  `image_alt` varchar(191) DEFAULT NULL,
  `voucher_type` varchar(191) NOT NULL DEFAULT 'custom',
  `face_value` bigint(20) UNSIGNED DEFAULT NULL,
  `selling_price` bigint(20) UNSIGNED NOT NULL,
  `price_options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`price_options`)),
  `discount_percentage` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `currency` varchar(3) NOT NULL DEFAULT 'IDR',
  `price_type` varchar(191) DEFAULT NULL,
  `unit_type` varchar(191) DEFAULT NULL,
  `validity_type` varchar(191) NOT NULL DEFAULT 'days_after_issue',
  `validity_days` int(10) UNSIGNED DEFAULT NULL,
  `fixed_valid_from` date DEFAULT NULL,
  `fixed_valid_until` date DEFAULT NULL,
  `minimum_quantity` int(10) UNSIGNED NOT NULL DEFAULT 1,
  `maximum_quantity` int(10) UNSIGNED DEFAULT NULL,
  `purchase_limit_per_order` int(10) UNSIGNED DEFAULT NULL,
  `allow_partial_redemption` tinyint(1) NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `meta_title` varchar(191) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
