(6, 'Holy River', 'holy-river', '<p>Reconnect with nature through a serene riverside experience surrounded by lush jungle scenery. Holy River offers a peaceful setting for reflection, spiritual rituals, and meaningful moments inspired by Bali’s natural beauty and cultural traditions.</p>', NULL, NULL, 1, 0, '2026-07-10 15:08:32', '2026-07-14 23:29:13'),
(7, 'Jungle Romance', 'jungle-romance', 'Intimate moments crafted for couples, surrounded by the beauty of Ubud\'s jungle and river.', 'experience-categories/c5e0deb3-cd14-4488-ba06-31efb046d0fd.webp', 'Jungle Romance', 1, 20, '2026-07-10 15:08:32', '2026-07-18 06:12:58'),
(8, 'Jungle Wellness & Spa Rituals', 'jungle-wellness-spa-rituals', 'Relaxing rituals designed to restore balance, refresh the body, and calm the mind.', 'experience-categories/0f670856-8d39-49a1-97ff-96a88f13e2e2.webp', 'Jungle Wellness & Spa Rituals', 1, 30, '2026-07-10 15:08:32', '2026-07-18 06:12:58'),
(9, 'Signature Dining Experiences', 'signature-dining-experiences', 'Memorable dining moments with scenic settings, refined flavors, and warm Balinese hospitality.', 'experience-categories/cff9f2ff-71e8-42c8-bcf4-a95c32488c53.webp', 'Signature Dining Experiences', 1, 10, '2026-07-10 15:08:32', '2026-07-18 06:12:58'),
(10, 'Ubud Jungle Adventures', 'ubud-jungle-adventures', 'Discover Bali’s natural beauty through outdoor adventures, cultural encounters, and scenic jungle experiences designed to enrich your stay at Nandini.', 'experience-categories/0b764bc6-95d2-4fa7-bd1b-58f4eba5eb97.webp', 'Ubud Jungle Adventures', 1, 0, '2026-07-10 15:08:32', '2026-07-14 23:27:18'),
